window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0072", [{"word":"bacterial","ipa_uk":"/bækˈtɪəriəl/","ipa_us":"/bækˈtɪriəl/","definition_zh":"细菌的；由细菌引起的；与细菌有关的","definition_en":"of, relating to, or caused by bacteria","core_image":"培养皿里一排排细小的杆状菌体，在显微镜下排成整齐的短线","scene":"The bacterial culture on the plate turned cloudy within a day.","sceneCN":"这里 bacterial 是「细菌的」（第 1 个义项：与细菌这一整类生物相关）；句意：培养皿上的细菌培养物一天之内就变浑浊了。图中可辨识物件：圆形培养皿、接种环、由清变浊的菌液。","pos":[{"tag":"adj.","zh":"细菌的；由细菌引起的（由名词 bacterium 加形容词后缀 -al 构成，只能作定语或表语，不能直接作名词）"}],"collocations":[{"phrase":"bacterial infection","zh":"细菌感染"},{"phrase":"bacterial growth","zh":"细菌生长；细菌增殖"},{"phrase":"bacterial cell","zh":"细菌细胞"},{"phrase":"bacterial resistance","zh":"细菌耐药性"},{"phrase":"bacterial contamination","zh":"细菌污染"},{"phrase":"bacterial flora","zh":"细菌群落；菌群"}],"forms":[{"label":"原级（形容词）","form":"bacterial（细菌的）"},{"label":"副词形式","form":"bacterially（以细菌的方式；罕用）"},{"label":"名词单数","form":"bacterium（细菌，单数）"},{"label":"名词复数","form":"bacteria（细菌，复数）"},{"label":"相关形容词","form":"bactericidal（杀菌的）；antibacterial（抗菌的）"}],"derivatives":[{"word":"bacterium","pos":"n.","zh":"细菌（单数形式）"},{"word":"bacteria","pos":"n.","zh":"细菌（bacterium 的复数，常作集合名词）"},{"word":"bacterially","pos":"adv.","zh":"以细菌的方式；由细菌作用地（罕用）"},{"word":"bacteriology","pos":"n.","zh":"细菌学"},{"word":"bacteriological","pos":"adj.","zh":"细菌学的；细菌学方法的"},{"word":"bactericide","pos":"n.","zh":"杀菌剂；杀细菌的物质"},{"word":"antibacterial","pos":"adj.","zh":"抗菌的；抗细菌的"}],"senses":[{"no":"01","title":"Of Bacteria as a Class","titleCN":"细菌的：属于细菌这一整类","definition":"relating to bacteria as a group of living things","definitionCN":"与细菌这一类生物有关的","example":"Bacterial cells are far smaller than the cells of animals and plants.","exampleCN":"细菌细胞远小于动物和植物的细胞。","why":"The suffix -al turns the noun bacterium into an adjective of relation, meaning 'having to do with bacteria'. The core picture is the rod-shaped single cell first seen under the microscope.","whyCN":"后缀 -al 把名词 bacterium 变成表示关联的形容词，意为「与细菌有关」；核心画面就是最早在显微镜下看到的杆状单细胞。"},{"no":"02","title":"Caused by Bacteria","titleCN":"细菌引起的：病因来自细菌","definition":"caused by bacteria rather than by a virus or another agent","definitionCN":"由细菌而非病毒或其他病原引起的","example":"The wound developed a bacterial infection after the flood.","exampleCN":"洪水过后，伤口出现了细菌感染。","why":"Once bacteria are known to cause disease, the adjective marks the cause. Here -al no longer means merely 'about'; it means 'produced by', and it contrasts directly with viral.","whyCN":"当细菌被确认能致病之后，这个形容词就用来标出病因；此时 -al 已不只是「关于」，而是「由……引起的」，并与 viral 直接对立。"},{"no":"03","title":"Of the Bacterial Cell","titleCN":"细菌细胞的：讲细胞结构","definition":"relating to the structure or the single cell of a bacterium","definitionCN":"与细菌的细胞结构或单个细菌细胞有关的","example":"The bacterial cell wall differs from the wall of a plant cell.","exampleCN":"细菌的细胞壁与植物细胞的细胞壁不同。","why":"A bacterium is a single cell without a nucleus. When biologists say bacterial cell, they mean that whole prokaryotic unit, so the adjective points to a level of organisation rather than to a disease.","whyCN":"细菌是没有细胞核的单细胞生物；生物学家说细菌细胞时，指的是整个原核细胞单位，因此这个形容词指向的是组织层次，而不是疾病。"},{"no":"04","title":"Of Growth and Culture","titleCN":"细菌生长的：培养与增殖","definition":"relating to the growth or cultivation of bacteria","definitionCN":"与细菌的生长或培养有关的","example":"Bacterial growth slowed once the dish was moved to a cold room.","exampleCN":"培养皿被移到冷室后，细菌生长变慢了。","why":"In the laboratory bacteria are grown as a population, and growth is measured as the increase of that population. Bacterial growth therefore names a process over time, not a shape or a cell.","whyCN":"在实验室里，细菌是作为一个种群来培养的，生长量就是该种群的增加量；因此 bacterial growth 指的是随时间发生的过程，而不是形状或单个细胞。"},{"no":"05","title":"Of Drug Resistance","titleCN":"细菌耐药性的：药物不再有效","definition":"relating to the ability of bacteria to survive antibiotics","definitionCN":"与细菌在抗生素作用下仍能存活的能力有关的","example":"Bacterial resistance to the drug appeared within two years.","exampleCN":"细菌对该药物的耐药性在两年内就出现了。","why":"Resistance is a trait of the bacteria themselves, not of the patient. The adjective assigns the trait to the organism, which is why the phrase is bacterial resistance rather than patient resistance.","whyCN":"耐药性是细菌自身的性状，而不是病人的性状；这个形容词把该性状归属于生物体，所以说细菌耐药性，而不说病人耐药性。"},{"no":"06","title":"Of the Resident Flora","titleCN":"细菌群落的：共居于某处的菌群","definition":"relating to the community of bacteria living in a place","definitionCN":"与某一部位或环境中共同生活的细菌群落有关的","example":"Diet changes the bacterial flora of the gut within weeks.","exampleCN":"饮食在数周内就会改变肠道的细菌群落。","why":"Flora here is the old word for the resident community of a place. Bacterial flora names which members of that community are meant, as opposed to fungal or viral members.","whyCN":"flora 在这里是旧用法，指某处常住的生物群落；bacterial flora 用来指明该群落中是细菌的那一部分，以区别于真菌或病毒部分。"},{"no":"07","title":"Of Contamination","titleCN":"细菌污染的：食品与环境中的菌","definition":"relating to contamination by bacteria","definitionCN":"与细菌造成的污染有关的","example":"The inspection found bacterial contamination in the water supply.","exampleCN":"检查发现供水系统存在细菌污染。","why":"Contamination is the entry of unwanted bacteria into a substance or a place. The adjective marks the source of the fault, so the phrase names what kind of pollution is being reported.","whyCN":"污染是指不需要的细菌进入某物质或某场所；这个形容词标出问题的来源，因此该短语说明的是被报告的是哪一类污染。"},{"no":"08","title":"Of Plant Disease","titleCN":"植物细菌性病害的：植物病理学用法","definition":"relating to diseases of plants caused by bacteria","definitionCN":"与由细菌引起的植物病害有关的","example":"Bacterial wilt destroyed the tomato field in a single season.","exampleCN":"细菌性枯萎病在一个季节里毁掉了整片番茄田。","why":"Plant pathology borrowed the same adjective for diseases with a bacterial cause, such as wilt and spot. The cause-and-effect sense of S2 is carried over to a new host, the plant.","whyCN":"植物病理学借用了同一个形容词来指由细菌引起的病害，如枯萎病和斑点病；第 2 个义项的因果含义被原样移用到新的宿主——植物身上。"}],"etymology":{"intro":{"en":"Bacterial is the adjective of bacterium, whose name records what the first observers actually saw: a small rod. The Greek word for a stick became a scientific term for a whole class of single cells, and the adjective followed.","cn":"bacterial 是 bacterium 的形容词，而 bacterium 这个名字记录了最早观察者真正看到的东西：一根小棍。希腊语里表示棍子的词，后来成了整类单细胞生物的科学术语，形容词也随之产生。"},"items":[{"era":"GREEK BAKTRON","en":"Greek baktron meant 'stick, rod, staff, cudgel'. Its diminutive baktērion, 'small staff', supplied the name because the first bacteria seen under a microscope were rod-shaped.","cn":"希腊语 baktron 意为「棍、杆、杖、短棒」；其指小形式 baktērion 意为「小棍」，因为最早在显微镜下看到的细菌正是杆状的，于是这个词被用来命名。"},{"era":"PROTO-INDO-EUROPEAN *BAK-","en":"The Greek word is usually connected with a reconstructed root *bak- 'staff used for support, peg', said to lie behind Latin baculum 'rod, walking stick'. De Vaan notes that *b was very rare in Indo-European and that the Celtic forms show an unexplained geminate, so the root may be a loanword from an unidentified source. This is a reconstructed form, and the origin is uncertain.","cn":"这个希腊词通常与重构词根 *bak-「支撑用的棍、木钉」联系起来，并被认为也衍生出拉丁语 baculum「杆、手杖」。但 De Vaan 指出 *b 在印欧语中极罕见，凯尔特语形式还出现无法解释的叠辅音，因此该词根可能是来自不明语言的借词。这是重构形式，来源不确定。"},{"era":"MODERN LATIN BACTERIUM","en":"In 1838 the German naturalist Christian Gottfried Ehrenberg introduced bacterium as a scientific word for the rod-shaped microbes he observed. The plural bacteria is recorded from 1847, and the singular bacterium from about 1848 as a back-formation from that plural. The exact first English citation of the adjective is not fixed, so only its century is safe to state.","cn":"1838 年，德国博物学家克里斯蒂安·戈特弗里德·埃伦贝格把 bacterium 引入为科学术语，用来指他观察到的杆状微生物。复数 bacteria 记录于 1847 年，单数 bacterium 约 1848 年由该复数逆构而成。该形容词在英语中的确切首见书证并无定论，因此只能稳妥地说它出现于十九世纪。"},{"era":"THE PLURAL TRAP","en":"Bacteria is a classical plural, but English writers have often treated it as a singular mass noun. Scientific style keeps bacterium for one cell and bacteria for two or more, which is why the adjective bacterial avoids the number question altogether.","cn":"bacteria 是古典复数，但英语作者常把它当作单数集合名词使用。科学写作仍坚持一个细胞用 bacterium、两个及以上用 bacteria；正因如此，形容词 bacterial 干脆回避了单复数问题。"},{"era":"NINETEENTH-CENTURY DERIVATIVES","en":"Bacteriology and bacteriological were coined in the later nineteenth century, when the germ theory of disease turned bacteria into an object of systematic study. The exact dates of these formations are approximate, since different authors introduced them independently.","cn":"bacteriology 与 bacteriological 产生于十九世纪后半叶，当时病菌学说使细菌成为系统研究的对象。这些派生词的确切年代只是约数，因为不同作者曾各自独立地创制它们。"},{"era":"BACTERIAL VERSUS VIRAL","en":"Modern medicine pairs bacterial with viral as two competing causes of infection. The pair matters clinically because antibiotics act on bacteria and not on viruses, so the adjective decides the treatment.","cn":"现代医学把 bacterial 与 viral 作为两类相对的感染病因并列。这一对立在临床上很重要，因为抗生素作用于细菌而不作用于病毒，所以这个形容词直接决定治疗方案。"}]},"similar":{"note":{"en":"The first group holds words built on the same bacterium stem but filling different grammatical slots. The second group holds words with related meanings, none of which is an exact synonym.","cn":"第一组是建立在同一个 bacterium 词干上、但占据不同语法位置的一组词；第二组是意义相近、但没有一个完全同义的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bacterially","ipa":"/bækˈtɪəriəli/","tag":"adverb","definition":"The adverb of bacterial, meaning 'by or with bacteria'. It is rare and mostly appears in technical prose.","definitionCN":"形容词 bacterial 的副词形式，意为「以细菌方式地、借细菌作用地」；用法罕见，多见于技术性文字。"},{"word":"bacteriology","ipa":"/bækˌtɪəriˈɒlədʒi/","tag":"noun, the science","definition":"The study of bacteria, not the adjective describing them. The ending -logy marks a field of study.","definitionCN":"指研究细菌的学科，而不是描述细菌的形容词；词尾 -logy 表示一门学问。"},{"word":"bactericidal","ipa":"/bækˌtɪəriˈsaɪdəl/","tag":"adjective, killing bacteria","definition":"Killing bacteria, as opposed to merely slowing their growth. The second element comes from Latin caedere 'to cut down'.","definitionCN":"指杀死细菌的，与仅仅抑制其生长不同；后半部分来自拉丁语 caedere「砍倒」。"}]},{"heading":"NEAR-SYNONYMS","entries":[{"word":"microbial","ipa":"/maɪˈkrəʊbiəl/","tag":"adjective, of microbes","definition":"Of microbes in general, including fungi and protists, not only bacteria. It is broader than bacterial and is the better choice when the group is mixed.","definitionCN":"指微生物的，范围包括真菌与原生生物，而不只是细菌；比 bacterial 更宽，群体混杂时更宜用这个词。"},{"word":"pathogenic","ipa":"/ˌpæθəˈdʒenɪk/","tag":"adjective, disease-causing","definition":"Disease-causing, whether the agent is a bacterium, a virus or a fungus. It names the effect on the host, not the kind of organism.","definitionCN":"指能致病的，无论病原是细菌、病毒还是真菌；它命名的是对宿主的作用，而不是生物种类。"},{"word":"septic","ipa":"/ˈseptɪk/","tag":"adjective, infected","definition":"Infected with pathogenic bacteria, or relating to such infection. It describes the state of a wound or a blood stream, not the bacteria themselves.","definitionCN":"指被致病细菌感染的，或与这种感染有关的；描述的是伤口或血流所处的状态，而不是细菌本身。"},{"word":"viral","ipa":"/ˈvaɪrəl/","tag":"adjective, of viruses","definition":"Of or caused by viruses. It is the direct counterpart of bacterial in medical usage and must not be substituted for it.","definitionCN":"指病毒的或由病毒引起的；在医学用法中与 bacterial 直接相对，不可替换使用。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"bacterium + -al: the suffix means 'having to do with', so bacterial is simply 'having to do with bacteria'.","cn":"bacterium + -al：后缀意为「与……有关」，所以 bacterial 就是「与细菌有关的」。"},{"en":"The name began with a shape: Greek baktērion is a small stick, and the first bacteria seen were rod-shaped.","cn":"这个名字起于形状：希腊语 baktērion 是「小棍」，而最早看到的细菌正是杆状的。"},{"en":"One cell is bacterium, two or more are bacteria; the adjective bacterial sidesteps the choice.","cn":"一个细胞是 bacterium，两个及以上是 bacteria；形容词 bacterial 回避了这个选择。"},{"en":"The family runs bacterium, bacteria, bacterial, bacterially, bacteriology, bactericidal and antibacterial.","cn":"同族词包括 bacterium、bacteria、bacterial、bacterially、bacteriology、bactericidal、antibacterial。"},{"en":"Medical pairs fix the meaning: bacterial infection against viral infection; bacterial resistance against antibiotic misuse.","cn":"医学上的成对搭配固定了词义：细菌感染对病毒感染；细菌耐药性对抗生素滥用。"}],"abstract":[{"en":"Picture a row of short dashes in a dish, each dash a living cell that splits in two.","cn":"想象培养皿里一排短横线，每一道都是一个活细胞，正在一分为二。"},{"en":"Picture an invisible army entering a wound, carrying a flag that reads bacterial.","cn":"想象一支看不见的军队进入伤口，打着写有 bacterial 的旗号。"},{"en":"Picture a door marked 'no entry' that antibiotics can open, while the bacteria behind it keep changing the lock.","cn":"想象一扇写着「禁止入内」的门，抗生素本可打开它，而门后的细菌不断换锁。"}]},"examples":[{"en":"Bacterial contamination forced the plant to recall the whole batch.","cn":"细菌污染迫使工厂召回整批产品。"},{"en":"The nurse swabbed the wound to identify the bacterial species involved.","cn":"护士擦拭伤口取样，以确定涉及的细菌种类。"},{"en":"Bacterial life survives in hot springs and around deep-sea vents.","cn":"细菌生命在温泉和深海热泉周围依然存活。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"bacterium（细菌，单数）+ -al（与……有关的）→ 与细菌有关的 → bacterial 细菌的","word":"bacterial"},"root":"希腊 baktron「棍、杖」→ 指小词 baktērion「小棍」→ 现代拉丁 bacterium（1838 年作为科学术语引入，因最早观察到的细菌呈杆状）→ 英语复数 bacteria → 逆构单数 bacterium → 形容词 bacterial（bacterium + -al）。","sensesIntro":{"en":"Eight senses share one core, the rod-shaped single cell. The adjective attaches that cell to a structure, a cause, a population, a trait, a community, a contamination or a plant disease.","cn":"八个义项共用一个核心——杆状单细胞。这个形容词把这细胞分别接到结构、病因、种群、性状、群落、污染与植物病害上。"},"semanticMap":{"core":{"en":"CORE IMAGE: one rod-shaped cell seen through a microscope, alone or in a row.","cn":"核心意象：显微镜下的一根杆状细胞，或单独、或排成一列。"},"chain":["THE CELL ITSELF","THE DISEASE IT CAUSES","THE WALL IT BUILDS","THE POPULATION IT FORMS","THE DRUG IT SURVIVES","THE PLACE IT OCCUPIES"],"branches":[{"senses":"S1","en":"CLASS: the bare relation to bacteria as a group, with no further claim.","cn":"类别：只表示与细菌这一类相关，不附加其他断言。"},{"senses":"S2 · S8","en":"CAUSE: a bacterial cause can act on an animal wound or on a plant field; the adjective stays the same while the host changes.","cn":"病因：细菌病因既可作用于动物伤口，也可作用于植物田地；宿主改变，形容词不变。"},{"senses":"S3","en":"STRUCTURE: the adjective can point to the cell as an object of study rather than to its effects.","cn":"结构：该形容词可以指向作为研究对象的细胞本身，而不是它的影响。"},{"senses":"S4 · S6","en":"POPULATION: growth measures a multiplying population, and flora names a settled community in one place.","cn":"种群：生长量衡量的是不断增殖的种群，菌群则指某处稳定居住的群落。"},{"senses":"S5 · S7","en":"THREAT: resistance is a trait kept by the organism, while contamination is unwanted bacteria entering a substance.","cn":"威胁：耐药性是生物体自身保有的性状，污染则是不需要的细菌进入某物质。"}]},"affixes":{"intro":{"en":"Bacterial is a Greek-derived noun turned adjective by a Latin suffix: a root meaning 'stick', a diminutive ending, a Modern Latin noun and an adjective ending.","cn":"bacterial 是希腊来源的名词经拉丁后缀变成形容词：表示「棍」的词根、指小词尾、现代拉丁名词与形容词词尾。"},"latinIntro":{"en":"Modern Latin bacterium supplied the noun; Latin -alis supplied the adjective ending. Latin baculum 'rod, staff' is a cognate from the same reconstructed root, not the source of the Greek word.","cn":"现代拉丁 bacterium 提供了名词，拉丁 -alis 提供了形容词词尾。拉丁语 baculum「杆、杖」与希腊词同出同一个重构词根，但并不是希腊词的来源。"},"items":[{"word":"bacterial","structure":"bacterium + -al (adjective of relation)","meaning":"relating to or caused by bacteria","meaningCN":"与细菌有关的或由细菌引起的","example":"Bacterial cells lack a true nucleus.","exampleCN":"细菌细胞没有真正的细胞核。"},{"word":"bacterium","structure":"Modern Latin bacterium < Greek baktērion (small staff)","meaning":"a single rod-shaped microbe","meaningCN":"单个杆状微生物","example":"A single bacterium reproduced within the hour.","exampleCN":"一个细菌在一小时内就完成了繁殖。"},{"word":"bacteria","structure":"Latin plural of bacterium","meaning":"bacteria as a class or a group","meaningCN":"细菌这一类，或一群细菌","example":"The soil teems with bacteria.","exampleCN":"土壤里充满细菌。"},{"word":"bacterially","structure":"bacterial + -ly (adverb of manner)","meaning":"by means of bacteria","meaningCN":"借细菌作用地","example":"The wound was bacterially contaminated.","exampleCN":"伤口受到了细菌污染。"},{"word":"bacteriology","structure":"bacterio- (bacteria) + -logy (study)","meaning":"the science that studies bacteria","meaningCN":"研究细菌的科学","example":"Bacteriology grew out of the germ theory.","exampleCN":"细菌学随着病菌学说发展起来。"},{"word":"bacteriological","structure":"bacteriology + -ical (adjective of relation)","meaning":"relating to bacteriology","meaningCN":"与细菌学有关的","example":"The bacteriological survey tested every well.","exampleCN":"这次细菌学调查检测了每一口井。"},{"word":"bactericide","structure":"bacterio- (bacteria) + -cide (killing)","meaning":"a substance that kills bacteria","meaningCN":"杀死细菌的物质","example":"The cleaner contains a bactericide.","exampleCN":"这种清洁剂含有杀菌成分。"},{"word":"antibacterial","structure":"anti- (against) + bacterial","meaning":"working against bacteria","meaningCN":"对抗细菌的","example":"Antibacterial soap was banned in several hospitals.","exampleCN":"抗菌肥皂在若干医院被禁用。"},{"word":"bacteremia","structure":"bacteri- (bacteria) + -emia (blood condition)","meaning":"the presence of bacteria in the blood","meaningCN":"血液中存在细菌的状态","example":"Bacteremia followed the untreated wound.","exampleCN":"未经处理的伤口引发了菌血症。"}],"latinEntries":[{"word":"bacterium","structure":"bacterium, -ii (n., Modern Latin, from Greek baktērion)","meaning":"a rod-shaped microbe","meaningCN":"杆状微生物"},{"word":"bacteria","structure":"bacteria, plural of Modern Latin bacterium","meaning":"microbes of the rod-shaped kind, collectively","meaningCN":"杆状微生物的集合称"},{"word":"baculum","structure":"baculum, -i (n., classical Latin); cognate with Greek baktron, not its source","meaning":"rod, walking stick","meaningCN":"杆；手杖"}]}},{"word":"bacterium","ipa_uk":"/bækˈtɪəriəm/","ipa_us":"/bækˈtɪriəm/","definition_zh":"细菌（单数）；一种无细胞核的单细胞微生物","definition_en":"a single-celled microorganism with no organized nucleus, usually reproducing by division","core_image":"显微镜下一根短小的杆状细胞，中央正在收窄、分裂成两半","scene":"A single bacterium can double in number every twenty minutes in warm broth.","sceneCN":"这里 bacterium 是「细菌（单数）」（第 1 个义项：一个单细胞个体）；句意：在温热的培养液里，一个细菌每二十分钟就能增殖一倍。图中可辨识物件：试管中的培养液、正在分裂的杆状细胞、计时器。","pos":[{"tag":"n.","zh":"细菌（单数可数名词）；复数形式为 bacteria，不能写作 bacteriums"}],"collocations":[{"phrase":"a single bacterium","zh":"单个细菌"},{"phrase":"pathogenic bacterium","zh":"致病细菌"},{"phrase":"beneficial bacterium","zh":"有益细菌"},{"phrase":"soil bacterium","zh":"土壤细菌"},{"phrase":"rod-shaped bacterium","zh":"杆状细菌"},{"phrase":"bacterium species","zh":"细菌物种；菌种"}],"forms":[{"label":"单数","form":"bacterium（一个细菌）"},{"label":"复数","form":"bacteria（多个细菌）"},{"label":"形容词形式","form":"bacterial（细菌的）"},{"label":"副词形式","form":"bacterially（以细菌方式地；罕用）"},{"label":"常见错误复数","form":"bacteriums（非标准，应作 bacteria）"},{"label":"学名层级","form":"Bacterium（旧属名，现多并入其他属）"}],"derivatives":[{"word":"bacteria","pos":"n.","zh":"细菌（复数，常作集合名词）"},{"word":"bacterial","pos":"adj.","zh":"细菌的；由细菌引起的"},{"word":"bacteriology","pos":"n.","zh":"细菌学"},{"word":"bacteriologist","pos":"n.","zh":"细菌学家"},{"word":"bacteriophage","pos":"n.","zh":"噬菌体（感染细菌的病毒）"},{"word":"probiotic","pos":"adj./n.","zh":"益生菌的；益生菌（与有益细菌相关的现代词）"}],"senses":[{"no":"01","title":"One Single Cell","titleCN":"单个细菌：一个单细胞个体","definition":"one individual single-celled organism of the bacterial kind","definitionCN":"一个细菌类的单细胞个体","example":"A single bacterium was enough to start the culture.","exampleCN":"一个细菌就足以启动这次培养。","why":"Bacterium is the count noun for one cell. The plural bacteria names any number of them, so the singular is used when the point is individuality, as in a single cell starting a colony.","whyCN":"bacterium 是数一个细胞的单数可数名词；复数 bacteria 指任意数量。当强调个体性时——比如一个细胞起始一个菌落——就用单数。"},{"no":"02","title":"The Rod Shape","titleCN":"杆状：得名的形状","definition":"a bacterium of the rod-shaped kind, the shape that gave the class its name","definitionCN":"指杆状的细菌，即给这一类生物命名的形状","example":"The rod-shaped bacterium in the sample measured two micrometres.","exampleCN":"样本中的杆状细菌长约两微米。","why":"Greek baktērion means 'small staff', and the first bacteria seen were rods. The singular still evokes that shape, which is why rod-shaped bacterium is a natural phrase rather than a tautology.","whyCN":"希腊语 baktērion 意为「小棍」，最早看到的细菌正是杆状；单数形式仍唤起这一形状，因此「杆状细菌」是自然搭配，而不是同义反复。"},{"no":"03","title":"A Prokaryote","titleCN":"原核生物：没有细胞核","definition":"a prokaryotic cell, that is, one without a membrane-bound nucleus","definitionCN":"原核细胞，即没有膜包裹的细胞核的细胞","example":"Unlike an animal cell, a bacterium keeps its DNA loose in the cytoplasm.","exampleCN":"与动物细胞不同，细菌的 DNA 松散地留在细胞质中。","why":"The defining trait of a bacterium is not its size but its lack of a nucleus. The singular is used here as a type label: any one member of the prokaryotic class.","whyCN":"细菌的决定性特征不是大小，而是没有细胞核；这里的单数用作类型标签，指原核类中的任意一个成员。"},{"no":"04","title":"A Pathogenic Bacterium","titleCN":"致病细菌：能引起疾病的那一个","definition":"a bacterium that causes disease in a host","definitionCN":"能在宿主中引起疾病的细菌","example":"The lab isolated the pathogenic bacterium from the patient's blood.","exampleCN":"实验室从病人的血液中分离出了那种致病细菌。","why":"Pathogenicity is a property of particular strains, not of all bacteria. Using the singular focuses on the one organism that was isolated and identified as the cause.","whyCN":"致病性是某些菌株的属性，而非所有细菌的属性；用单数是为了聚焦于被分离并确认为病因的那一个生物体。"},{"no":"05","title":"A Beneficial Bacterium","titleCN":"有益细菌：与人共处或为人所用","definition":"a bacterium that helps its host or is useful in industry","definitionCN":"对宿主有益或在工业上有用的细菌","example":"A beneficial bacterium in the root zone supplies nitrogen to the plant.","exampleCN":"根区的一种有益细菌为植物提供氮。","why":"Most bacteria do no harm, and many are useful. The singular names one such partner, which balances the disease-centred sense and explains why the word is not a synonym of germ.","whyCN":"大多数细菌无害，许多还有用；单数形式命名一个这样的伙伴，平衡了以疾病为中心的那个义项，也说明这个词并不等于「病菌」。"},{"no":"06","title":"A Bacterium in the Environment","titleCN":"环境中的细菌：土壤与水体里的个体","definition":"a bacterium living freely in soil, water or air","definitionCN":"自由生活在土壤、水体或空气中的细菌","example":"A soil bacterium broke down the pesticide within a month.","exampleCN":"一种土壤细菌在一个月内分解了那种农药。","why":"Outside a host, bacteria drive nutrient cycles. The singular points to a functioning individual in an ecosystem, the unit that carries out decomposition or fixation.","whyCN":"在宿主体外，细菌驱动养分循环；单数指向生态系统中一个发挥功能的个体，也就是执行分解或固氮的那个单位。"},{"no":"07","title":"A Cell Factory","titleCN":"细菌工厂：生物技术中的生产单元","definition":"a bacterium used as a host for industrial or genetic production","definitionCN":"被用作工业或基因生产宿主的细菌","example":"The company engineered a bacterium to make insulin.","exampleCN":"该公司改造了一种细菌来生产胰岛素。","why":"Because a bacterium grows fast and is easy to modify, biotechnology treats it as a factory. The singular names the working unit, not the species as a whole.","whyCN":"由于细菌生长快、易于改造，生物技术把它当作工厂；单数命名的是这个工作单元，而不是整个物种。"},{"no":"08","title":"Singular Versus Plural","titleCN":"单数与复数：bacterium 与 bacteria 的分工","definition":"the singular form used where standard usage requires one cell, in contrast to the plural bacteria","definitionCN":"在标准用法需要一个细胞时使用的单数形式，与复数 bacteria 相对","example":"Write one bacterium but many bacteria; the singular is not used for a group.","exampleCN":"一个写作 bacterium，许多写作 bacteria；单数不用于指一群。","why":"Bacteria is a Latin plural and English often treats it as a mass noun, yet scientific writing keeps the number distinction. This sense records that grammatical rule, which is why bacteriums is marked as non-standard.","whyCN":"bacteria 是拉丁复数，英语常把它当作集合名词，但科学写作仍保留单复数区别；这个义项记录的就是这条语法规则，因此 bacteriums 被标为非标准。"}],"etymology":{"intro":{"en":"Bacterium is a Modern Latin noun coined from a Greek diminutive for 'small staff'. It names one rod-shaped cell, and its plural bacteria names the class. The word's history is unusually well dated because a named scientist introduced it.","cn":"bacterium 是用希腊语「小棍」的指小形式构成的现代拉丁名词，命名一个杆状细胞，其复数 bacteria 命名整类。这个词的历史年代异常清楚，因为是一位具名科学家引入的。"},"items":[{"era":"GREEK BAKTRON","en":"Baktron meant 'stick, rod, staff, cudgel'; the diminutive baktērion meant 'small staff'. The shape of the first observed cells, not their function, determined the name.","cn":"baktron 意为「棍、杆、杖、短棒」，其指小形式 baktērion 意为「小棍」。决定这个名字的是最早观察到的细胞的形状，而不是其功能。"},{"era":"RECONSTRUCTED ROOT *BAK-","en":"The Greek word is linked to a reconstructed root *bak- 'staff, peg', also said to underlie Latin baculum 'rod'. De Vaan doubts a clean Indo-European pedigree: *b is rare in the family, and Celtic shows an unexplained geminate. The root may be a loanword. This is a reconstruction and the deeper origin is uncertain.","cn":"这个希腊词被联系到重构词根 *bak-「棍、木钉」，并被认为也构成拉丁语 baculum「杆」。但 De Vaan 怀疑它没有干净的印欧语系谱：*b 在语系中罕见，凯尔特语还出现无法解释的叠辅音，因此该词根可能是借词。这是重构形式，更深层的来源不确定。"},{"era":"EHRenberg'S COINAGE","en":"Christian Gottfried Ehrenberg introduced the word in 1838 as a scientific term for the rod-shaped microbes he studied. The plural bacteria appears in English by 1847.","cn":"克里斯蒂安·戈特弗里德·埃伦贝格于 1838 年把它作为科学术语引入，用来指他研究的杆状微生物；复数 bacteria 于 1847 年出现在英语中。"},{"era":"BACK-FORMED SINGULAR","en":"Bacterium as an English singular is recorded from about 1848, formed by removing the plural ending from bacteria. Classical plurals were sometimes wrongly used as singulars, which is how the modern number confusion began.","cn":"bacterium 作为英语单数约 1848 年才有记录，是从 bacteria 去掉复数词尾逆构而来。古典复数有时被误用作单数，现代的单复数混乱就是这样开始的。"},{"era":"THE MASS-NOUN DRIFT","en":"English often treats bacteria as an uncountable mass, as in 'bacteria is present'. Scientific style resists this drift and keeps bacterium for one cell, a distinction the adjective bacterial avoids.","cn":"英语常把 bacteria 当作不可数的集合名词，如「bacteria is present」；科学写作抵制这种漂移，坚持一个细胞用 bacterium，而形容词 bacterial 则绕开了这一区分。"},{"era":"MODERN CLASSIFICATION","en":"Modern taxonomy places bacteria in their own domain, separate from archaea and eukaryotes. The old genus name Bacterium has largely been divided among other genera, but the common noun and its singular remain standard.","cn":"现代分类学把细菌放在独立的域，与古菌和真核生物分开。旧的属名 Bacterium 大多已被拆分并入其他属，但普通名词及其单数形式仍是标准用法。"}]},"similar":{"note":{"en":"The first group separates the singular, the plural and the adjective built on this stem. The second group lists words for small living things that are often confused with bacterium.","cn":"第一组区分同一词干上的单数、复数与形容词；第二组列出常与 bacterium 混淆的「微小生物」类词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bacteria","ipa":"/bækˈtɪəriə/","tag":"plural noun","definition":"The plural of bacterium, used for two or more cells or for the class as a whole. It is not a singular form, though English often treats it as a mass noun.","definitionCN":"bacterium 的复数，用于两个及以上细胞或整类；它不是单数形式，尽管英语常把它当作集合名词。"},{"word":"bacterial","ipa":"/bækˈtɪəriəl/","tag":"adjective","definition":"The adjective of relation or cause. It cannot stand alone as a noun, and it never carries a plural.","definitionCN":"表示关联或病因的形容词；不能单独作名词，也没有复数形式。"},{"word":"bacteriology","ipa":"/bækˌtɪəriˈɒlədʒi/","tag":"noun, the science","definition":"The study of bacteria. The ending -logy marks a discipline, so it is not a word for an organism.","definitionCN":"研究细菌的学科；词尾 -logy 表示学科，因此它不是指某种生物的词。"}]},{"heading":"NEAR-SYNONYMS","entries":[{"word":"microbe","ipa":"/ˈmaɪkrəʊb/","tag":"popular noun","definition":"A popular word for any very small living thing, especially one causing disease. It covers fungi and protists as well as bacteria.","definitionCN":"指任何极小的生物、尤指致病者的通俗词；除细菌外也涵盖真菌与原生生物。"},{"word":"germ","ipa":"/dʒɜːm/","tag":"everyday noun","definition":"An everyday word for a microbe that may cause disease. It is not a taxonomic term and carries no information about cell type.","definitionCN":"日常用语，指可能致病的微生物；不是分类学术语，也不包含细胞类型的信息。"},{"word":"pathogen","ipa":"/ˈpæθədʒən/","tag":"noun, disease agent","definition":"Any agent that causes disease, whether bacterium, virus or fungus. Being a bacterium does not make an organism a pathogen.","definitionCN":"任何引起疾病的病原，无论细菌、病毒还是真菌；是细菌并不意味着就是病原体。"},{"word":"prokaryote","ipa":"/prəʊˈkæriəʊt/","tag":"noun, cell type","definition":"A cell without a nucleus. Bacteria are prokaryotes, but the term also covers archaea.","definitionCN":"没有细胞核的细胞；细菌属于原核生物，但该词也涵盖古菌。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"One bacterium, many bacteria: the -um ending is singular, the -a ending is plural.","cn":"一个 bacterium，许多 bacteria：-um 结尾是单数，-a 结尾是复数。"},{"en":"Greek baktērion 'small staff' explains both the name and the rod shape.","cn":"希腊语 baktērion「小棍」既解释了名字，也解释了杆状外形。"},{"en":"The word was introduced by Ehrenberg in 1838, so its birth date is known rather than guessed.","cn":"这个词由埃伦贝格于 1838 年引入，所以它的生日是已知的，不是猜的。"},{"en":"The family runs bacterium, bacteria, bacterial, bacteriology, bacteriologist and bacteriophage.","cn":"同族词包括 bacterium、bacteria、bacterial、bacteriology、bacteriologist、bacteriophage。"},{"en":"A bacterium is defined by what it lacks: no nucleus, no membrane-bound organelles.","cn":"bacterium 靠「缺少什么」来定义：没有细胞核，没有膜包细胞器。"}],"abstract":[{"en":"Picture one dash that splits into two dashes, then four, until the dish is full.","cn":"想象一道短横线分裂成两道、再分裂成四道，直到培养皿装满。"},{"en":"Picture a cell with no room in the middle, its DNA lying loose like a coil of rope on a floor.","cn":"想象一个中央没有房间的细胞，DNA 像地板上的一卷绳子那样松散放着。"},{"en":"Picture a single worker so small that a whole factory fits inside it.","cn":"想象一个工人小到整座工厂都能装进它体内。"}]},"examples":[{"en":"A single bacterium multiplied into a visible colony overnight.","cn":"一个细菌一夜之间增殖成肉眼可见的菌落。"},{"en":"The soil bacterium fixes nitrogen that the crop can use.","cn":"这种土壤细菌固定氮，供作物利用。"},{"en":"Scientists edited a bacterium to produce a useful enzyme.","cn":"科学家改造了一种细菌来生产有用的酶。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"bacteri-（小棍，希腊语指小形式）+ -um（拉丁单数名词词尾）→ 一根小棍 → bacterium 一个细菌","word":"bacterium"},"root":"希腊 baktron「棍、杖」→ 指小词 baktērion「小棍」→ 现代拉丁 bacterium（1838 年由埃伦贝格引入）→ 英语复数 bacteria（1847）→ 逆构英语单数 bacterium（约 1848）。","sensesIntro":{"en":"Eight senses track one cell through its grammar and its roles: an individual, a rod shape, a prokaryote, a pathogen, a helper, an ecosystem worker, a factory and a singular form.","cn":"八个义项让同一个细胞走过它的语法与角色：个体、杆状、原核生物、病原、帮手、生态工作者、工厂以及单数形式。"},"semanticMap":{"core":{"en":"CORE IMAGE: one rod-shaped cell, alone, about to divide.","cn":"核心意象：一个杆状细胞，独自待着，即将分裂。"},"chain":["ONE CELL","ITS SHAPE","NO NUCLEUS","IT MAKES DISEASE","IT HELPS","IT WORKS IN THE WORLD"],"branches":[{"senses":"S1 · S8","en":"NUMBER: the singular names one cell, and the grammar of that singular is itself a sense because English often blurs it.","cn":"数量：单数命名一个细胞，而这一单数的语法本身也算一个义项，因为英语常把它模糊掉。"},{"senses":"S2 · S3","en":"FORM: the rod shape gave the name, and the missing nucleus defines the cell type.","cn":"形态：杆状给了它名字，而缺失的细胞核定义了它的细胞类型。"},{"senses":"S4","en":"HARM: one strain can cause disease, which is why the word is often met in medicine.","cn":"危害：某个菌株可以致病，因此这个词常出现在医学语境。"},{"senses":"S5 · S6","en":"BENEFIT: the same cell can help a host or drive nutrient cycles in soil and water.","cn":"益处：同一个细胞也能帮助宿主，或在土壤与水体中驱动养分循环。"},{"senses":"S7","en":"TOOL: biotechnology turns the cell into a production unit, a factory with a cell wall.","cn":"工具：生物技术把这个细胞变成生产单元，一座带细胞壁的工厂。"}]},"affixes":{"intro":{"en":"Bacterium is a Greek diminutive dressed in a Latin noun ending: a root for 'stick', a diminutive suffix and a neuter singular ending.","cn":"bacterium 是披着拉丁名词词尾的希腊指小词：表示「棍」的词根、指小后缀与中性单数词尾。"},"latinIntro":{"en":"The noun was coined in Modern Latin on a Greek model, so its Latin ending is real while its root is Greek. Latin baculum 'rod' shares the reconstructed root but is not the source of the Greek word.","cn":"这个名词是按希腊模式在现代拉丁语中创制的，因此拉丁词尾是真的，词根却是希腊的。拉丁语 baculum「杆」共享重构词根，但并非希腊词的来源。"},"items":[{"word":"bacterium","structure":"Greek baktērion (small staff) + Modern Latin neuter ending -um","meaning":"one rod-shaped cell","meaningCN":"一个杆状细胞","example":"One bacterium started the colony.","exampleCN":"一个细菌起始了这个菌落。"},{"word":"bacteria","structure":"bacterium + Latin plural -a","meaning":"the class of such cells","meaningCN":"这类细胞的集合","example":"Bacteria were visible under the lens.","exampleCN":"在镜头下可以看到细菌。"},{"word":"bacterial","structure":"bacterium + -al (relation)","meaning":"of or caused by bacteria","meaningCN":"细菌的或由细菌引起的","example":"Bacterial growth requires moisture.","exampleCN":"细菌生长需要水分。"},{"word":"bacteriology","structure":"bacterio- + -logy (study)","meaning":"the science of bacteria","meaningCN":"研究细菌的科学","example":"Bacteriology began with stained slides.","exampleCN":"细菌学始于染色玻片。"},{"word":"bacteriologist","structure":"bacteriology + -ist (person)","meaning":"a specialist in bacteria","meaningCN":"研究细菌的专家","example":"The bacteriologist identified the strain.","exampleCN":"细菌学家鉴定了该菌株。"},{"word":"bacteriophage","structure":"bacterio- + -phage (eater)","meaning":"a virus that infects bacteria","meaningCN":"感染细菌的病毒","example":"A bacteriophage lysed the culture.","exampleCN":"一种噬菌体裂解了培养物。"},{"word":"bactericide","structure":"bacterio- + -cide (killing)","meaning":"a bacteria-killing agent","meaningCN":"杀灭细菌的药剂","example":"The surface was treated with a bactericide.","exampleCN":"表面用杀菌剂处理过。"},{"word":"probiotic","structure":"pro- (for) + biot- (life) + -ic (adjective)","meaning":"supporting beneficial bacteria","meaningCN":"支持有益细菌的","example":"Probiotic cultures were added to the yoghurt.","exampleCN":"酸奶中加入了益生菌培养物。"}],"latinEntries":[{"word":"bacterium","structure":"bacterium, -ii (n., Modern Latin, from Greek baktērion)","meaning":"a rod-shaped microbe","meaningCN":"杆状微生物"},{"word":"bacteria","structure":"plural of Modern Latin bacterium","meaning":"such microbes collectively","meaningCN":"这类微生物的集合"},{"word":"baculum","structure":"baculum, -i (n., classical Latin); cognate with Greek baktron","meaning":"rod, staff, walking stick","meaningCN":"杆；杖；手杖"}]}},{"word":"microorganism","ipa_uk":"/ˌmaɪkrəʊˈɔːɡənɪzəm/","ipa_us":"/ˌmaɪkroʊˈɔːrɡənɪzəm/","definition_zh":"微生物；肉眼不可见、需借助显微镜观察的生物","definition_en":"a living thing so small that it can be seen only with a microscope","core_image":"一滴池塘水里挤满肉眼看不见的小生命，放大后显出球状、杆状与螺旋状的轮廓","scene":"A single microorganism in the pond water can start a whole bloom once nutrients rise.","sceneCN":"这里 microorganism 是「微生物」（第 1 个义项：需用显微镜观察的微小生物）；句意：养分升高后，池塘水里的一个微生物就能引发整片水华。图中可辨识物件：水滴、显微镜视野、成片变绿的水面。","pos":[{"tag":"n.","zh":"微生物（可数名词，复数 microorganisms；涵盖细菌、古菌、原生生物、真菌等微小生物）"}],"collocations":[{"phrase":"pathogenic microorganism","zh":"病原微生物"},{"phrase":"soil microorganism","zh":"土壤微生物"},{"phrase":"marine microorganism","zh":"海洋微生物"},{"phrase":"beneficial microorganism","zh":"有益微生物"},{"phrase":"microorganism growth","zh":"微生物生长"},{"phrase":"indicator microorganism","zh":"指示微生物"}],"forms":[{"label":"单数","form":"microorganism（一个微生物）"},{"label":"复数","form":"microorganisms（多个微生物）"},{"label":"连字符变体","form":"micro-organism（英式旧式拼写，义同）"},{"label":"形容词形式","form":"microbial / microorganismal（微生物的）"},{"label":"学科名称","form":"microbiology（微生物学）"}],"derivatives":[{"word":"microorganisms","pos":"n.","zh":"微生物（复数）"},{"word":"micro-organism","pos":"n.","zh":"微生物（带连字符的旧式拼写）"},{"word":"microbial","pos":"adj.","zh":"微生物的"},{"word":"microbiology","pos":"n.","zh":"微生物学"},{"word":"microbiologist","pos":"n.","zh":"微生物学家"},{"word":"microbiota","pos":"n.","zh":"微生物区系；某处的微生物群落"},{"word":"microbiome","pos":"n.","zh":"微生物组；微生物群落基因组"}],"senses":[{"no":"01","title":"A Microscopic Living Thing","titleCN":"微生物：小到需显微镜才可见","definition":"a living thing too small to be seen clearly with the naked eye","definitionCN":"小到肉眼无法清楚看见的生物","example":"Each drop of pond water holds thousands of microorganisms.","exampleCN":"每一滴池塘水里都含有成千上万个微生物。","why":"The word joins micro-, 'small', to organism, 'living body'. The defining picture is not a particular shape but a scale: the creature is below the resolving power of the eye.","whyCN":"这个词由表示「小」的 micro- 与表示「生物体」的 organism 合成；它的核心画面不是某个特定形状，而是尺度：小到超出眼睛的分辨能力。"},{"no":"02","title":"A Unicellular Form","titleCN":"单细胞形态：一个细胞就是一个个体","definition":"a organism consisting of a single cell","definitionCN":"由一个细胞构成的生物","example":"A microorganism such as an amoeba lives as one cell.","exampleCN":"像变形虫这样的微生物以一个细胞的形式生活。","why":"Most microorganisms are unicellular: one cell performs every function of life. The sense marks body plan rather than size, though the two usually coincide.","whyCN":"大多数微生物是单细胞的：一个细胞承担全部生命功能；这个义项标出的是身体构造，而不是大小，尽管两者通常同时成立。"},{"no":"03","title":"A Broad Taxonomic Cover","titleCN":"分类上的宽泛覆盖：不止细菌","definition":"the loose group covering bacteria, archaea, protists and fungi, and sometimes viruses","definitionCN":"涵盖细菌、古菌、原生生物与真菌，有时也包括病毒的宽泛类别","example":"The term microorganism covers both bacteria and single-celled fungi.","exampleCN":"「微生物」这一术语既涵盖细菌，也包括单细胞真菌。","why":"Microorganism is not a taxonomic rank; it is a convenience class defined by size. That is why it can hold several unrelated kingdoms, and why virologists debate whether viruses belong.","whyCN":"microorganism 不是分类层级，而是按大小划分的方便类别；因此它能容纳几个互不相关的界，也因此病毒学家会争论病毒是否算在内。"},{"no":"04","title":"A Soil Microorganism","titleCN":"土壤微生物：地下循环的工人","definition":"a microorganism living in soil and driving its nutrient cycles","definitionCN":"生活在土壤中并驱动土壤养分循环的微生物","example":"A soil microorganism released phosphorus from the dead leaves.","exampleCN":"一种土壤微生物从枯叶中释放出磷。","why":"In soil the word usually names a decomposer or a symbiont. The scale sense recedes and the ecological job comes forward: the organism is defined by what it does in the ground.","whyCN":"在土壤语境中，这个词通常指分解者或共生者；尺度义退后，生态职能走上前，生物体靠它在地里所做的事来定义。"},{"no":"05","title":"A Marine Microorganism","titleCN":"海洋微生物：水体中的微小生产者","definition":"a microorganism living in seawater, often a primary producer","definitionCN":"生活在海水中、常为初级生产者的微生物","example":"Marine microorganisms produce a large share of the oxygen we breathe.","exampleCN":"海洋微生物产生了我们呼吸的氧气中的很大一部分。","why":"In the sea, microscopic algae and bacteria carry out photosynthesis and form the base of the food web. The word then points to a functional layer of the ecosystem.","whyCN":"在海洋中，微小藻类与细菌进行光合作用，构成食物网的基础；此时这个词指向生态系统中的一个功能层。"},{"no":"06","title":"A Pathogenic Microorganism","titleCN":"病原微生物：引起疾病的那一类","definition":"a microorganism that causes disease in a host","definitionCN":"能在宿主中引起疾病的微生物","example":"The outbreak was traced to a pathogenic microorganism in the water.","exampleCN":"疫情被追溯至水中的一种病原微生物。","why":"Here the neutral scale word takes on the medical role. The sense is narrower than S1 because only some microorganisms cause disease, and the speaker is naming that subset.","whyCN":"这里中性的尺度词带上了医学角色；该义项比第 1 个义项窄，因为只有部分微生物致病，说话人指的是这个子集。"},{"no":"07","title":"A Useful Microorganism","titleCN":"有益微生物：发酵与生产中的帮手","definition":"a microorganism used for fermentation or industrial production","definitionCN":"用于发酵或工业生产的微生物","example":"A beneficial microorganism turns milk into yoghurt overnight.","exampleCN":"一种有益微生物一夜之间把牛奶变成酸奶。","why":"Humans have long used microorganisms as tools. The sense shifts from 'what it is' to 'what it is good for', and it explains the everyday phrase beneficial microorganism.","whyCN":"人类早已把微生物当作工具；这个义项从「它是什么」转向「它有什么用」，也解释了「有益微生物」这一日常说法。"},{"no":"08","title":"An Indicator Microorganism","titleCN":"指示微生物：用来判断水质或卫生","definition":"a microorganism whose presence signals contamination or a condition","definitionCN":"其存在能提示污染或某种状况的微生物","example":"The lab counts an indicator microorganism to judge water safety.","exampleCN":"实验室计数一种指示微生物来判断水的安全性。","why":"Public health cannot test every pathogen, so it watches a proxy. The indicator is chosen because it is easy to detect and travels the same way as the dangerous ones.","whyCN":"公共卫生无法检测每一种病原，于是监测一个替身；被选作指示者的微生物易于检出，且与危险病原走同一条传播路径。"}],"etymology":{"intro":{"en":"Microorganism is a nineteenth-century compound of two Greek-derived elements: micro-, 'small', and organism, 'living body'. The word dates from the great expansion of microscopy and germ theory.","cn":"microorganism 是十九世纪由两个希腊来源成分构成的复合词：micro-「小」与 organism「生物体」。它诞生于显微镜技术与病菌学说大发展的年代。"},"items":[{"era":"GREEK MIKROS","en":"Greek mikros, the Attic form of smikros, meant 'small, little, petty'. Its Latinized combining form micro- became the standard prefix for 'small' in scientific English. Beekes considers the Greek word possibly Pre-Greek, so its deeper origin is uncertain.","cn":"希腊语 mikros（阿提卡方言形式 smikros）意为「小的、微小的」；其拉丁化组合形式 micro- 成为科学英语中表示「小」的标准前缀。Beekes 认为这个希腊词可能来自前希腊语底层，因此其更深来源不确定。"},{"era":"ORGANISM","en":"Organism is recorded from the 1660s for 'organic structure'; the sense 'living animal or plant' appears by 1825, translating German Organismus. It rests on Greek organon 'tool, instrument', literally 'that with which one works'.","cn":"organism 于十七世纪六十年代记录为「有机结构」，到 1825 年才出现「活的动物或植物」这一义项，译自德语 Organismus。其基础是希腊语 organon「工具、器具」，字面意为「用来工作的东西」。"},{"era":"THE 1855 COMPOUND","en":"Microorganism is recorded from 1855, with the hyphenated micro-organism appearing in the same period. The compound was formed in English rather than borrowed whole from another language.","cn":"microorganism 记录于 1855 年，带连字符的 micro-organism 也出现在同一时期；这个复合词是在英语内部构成的，而不是从其他语言整体借入。"},{"era":"THE MICROSCOPE'S CENTURY","en":"The word spread as improved lenses let naturalists see a world below the eye. Pasteur and Koch then linked particular microorganisms to particular diseases, giving the neutral word a medical charge.","cn":"随着透镜改进，博物学者看见了一个肉眼以下的世界，这个词随之传播；随后巴斯德与科赫把特定微生物与特定疾病联系起来，使这个中性词带上了医学色彩。"},{"era":"THE VIRUS BORDERLINE","en":"Viruses are smaller still and cannot reproduce without a host cell. Because they lack independent life, many authors exclude them from microorganisms, while others keep them in the loose class. The boundary is a matter of convention, not of etymology.","cn":"病毒更小，且离开宿主细胞无法繁殖；由于不具备独立生命，许多作者把它排除在微生物之外，也有人把它留在这个宽泛类别里。这条边界是约定问题，不是词源问题。"},{"era":"MODERN MICROBIOME","en":"Recent science added microbiome and microbiota, which name whole communities rather than single cells. Microorganism now sits at the level of the individual, beside these collective terms.","cn":"近年的科学又加入了 microbiome 与 microbiota，它们命名的是整个群落而非单个细胞；于是 microorganism 现在处在个体的层次，与这些集体术语并列。"}]},"similar":{"note":{"en":"The first group holds spellings and derivatives built on the same compound. The second group holds everyday and technical words for small life that overlap without being equivalent.","cn":"第一组是同一复合词上的拼写变体与派生词；第二组是与「微小生命」相关、彼此重叠但并不等同的日常词与技术词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"micro-organism","ipa":"/ˌmaɪkrəʊˈɔːɡənɪzəm/","tag":"hyphenated variant","definition":"The older British spelling with a hyphen. It means exactly the same thing and follows the nineteenth-century habit of hyphenating new compounds.","definitionCN":"带连字符的英式旧拼写，意义完全相同，遵循十九世纪给新复合词加连字符的习惯。"},{"word":"microbial","ipa":"/maɪˈkrəʊbiəl/","tag":"adjective","definition":"The usual adjective meaning 'of microbes'. It is built on microbe rather than directly on microorganism.","definitionCN":"常用形容词，意为「微生物的」；它建立在 microbe 上，而不是直接建立在 microorganism 上。"},{"word":"microbiology","ipa":"/ˌmaɪkrəʊbaɪˈɒlədʒi/","tag":"noun, the science","definition":"The study of microorganisms. The ending -logy marks a discipline, so it is not a word for a living thing.","definitionCN":"研究微生物的学科；词尾 -logy 表示学科，因此它不是指某种生物的词。"}]},{"heading":"NEAR-SYNONYMS","entries":[{"word":"microbe","ipa":"/ˈmaɪkrəʊb/","tag":"popular noun","definition":"A popular nineteenth-century word for a very small living thing, especially a disease-causing one. It is warmer and less formal than microorganism.","definitionCN":"十九世纪的通俗词，指极小的生物、尤指致病者；比 microorganism 更口语、更不正式。"},{"word":"germ","ipa":"/dʒɜːm/","tag":"everyday noun","definition":"An everyday word for a microbe that may cause disease. It carries no scientific information about cell type or kingdom.","definitionCN":"日常词，指可能致病的微生物；不包含关于细胞类型或生物界的科学信息。"},{"word":"bacterium","ipa":"/bækˈtɪəriəm/","tag":"noun, one kingdom","definition":"One kind of microorganism only. Microorganism is the wider term and can cover fungi and protists that bacterium cannot.","definitionCN":"只指其中一类微生物；microorganism 是更宽的词，能涵盖 bacterium 无法涵盖的真菌与原生生物。"},{"word":"pathogen","ipa":"/ˈpæθədʒən/","tag":"noun, disease agent","definition":"Any disease-causing agent, including viruses and parasitic worms. It names a role, while microorganism names a size class.","definitionCN":"任何致病因子，包括病毒与寄生蠕虫；它命名的是角色，而 microorganism 命名的是尺度类别。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"micro- 'small' + organism 'living body': a living body too small to see.","cn":"micro-「小」+ organism「生物体」：小到看不见的生物体。"},{"en":"The word is a size class, not a family: bacteria, protists and fungi can all be microorganisms.","cn":"这个词是尺度类别，不是科属：细菌、原生生物与真菌都可以是微生物。"},{"en":"The family runs microorganism, microorganisms, micro-organism, microbial, microbiology, microbiota and microbiome.","cn":"同族词包括 microorganism、microorganisms、micro-organism、microbial、microbiology、microbiota、microbiome。"},{"en":"Collocations mark the habitat: soil, marine, pathogenic, beneficial and indicator microorganisms.","cn":"搭配标出生境：土壤、海洋、病原、有益与指示微生物。"},{"en":"A microorganism is defined by scale; a pathogen is defined by harm. The two labels can meet in one cell.","cn":"microorganism 按尺度定义，pathogen 按危害定义，两个标签可以落在同一个细胞上。"}],"abstract":[{"en":"Picture a whole forest, with predators and prey, living inside one drop of water.","cn":"想象一整片森林连同捕食者与猎物，住在一滴水里面。"},{"en":"Picture a crowd so small that a single lens must stand in for your eye.","cn":"想象一群小生命，小到必须用一枚镜片代替你的眼睛。"},{"en":"Picture a worker invisible to the boss who depends on it every day.","cn":"想象一个老板看不见的工人，而老板每天都依赖他。"}]},"examples":[{"en":"A microorganism in the milk turned it sour before the morning.","cn":"牛奶中的一种微生物在天亮前就让它变酸了。"},{"en":"The team sampled the soil to count every microorganism in a gram.","cn":"团队采集土壤样本，统计每克中的微生物数量。"},{"en":"No microorganism was found in the sealed water sample.","cn":"密封水样中没有发现任何微生物。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"micro-（微小）+ organism（生物体）→ 微小的生物体 → microorganism 微生物","word":"microorganism"},"root":"希腊 mikros「小」（阿提卡形式 smikros）→ 拉丁化前缀 micro- → 英语 micro- + organism（有机体，1825 年出现生物义）→ 1855 年合成 microorganism「微生物」。","sensesIntro":{"en":"Eight senses move from scale to body plan, to taxonomy, to five habitats and roles: soil, sea, disease, use and indication.","cn":"八个义项从尺度走向身体构造，再走向分类，最后落到五种生境与角色：土壤、海洋、致病、利用与指示。"},"semanticMap":{"core":{"en":"CORE IMAGE: a drop of water under a lens, crowded with living shapes.","cn":"核心意象：镜片下的一滴水，挤满各种活的形状。"},"chain":["TOO SMALL TO SEE","ONE CELL ONLY","MANY KINGDOMS","IN THE SOIL","IN THE SEA","IN THE BODY"],"branches":[{"senses":"S1 · S2","en":"SCALE AND BODY: smallness is the entry condition, and a single cell is the common body plan.","cn":"尺度与身体：小是入门条件，单细胞是常见的身体构造。"},{"senses":"S3","en":"TAXONOMY: the class is defined by size, so it cuts across kingdoms and even touches the virus border.","cn":"分类：这一类别按大小定义，因此横跨多个界，甚至触及病毒那条边界。"},{"senses":"S4 · S5","en":"HABITAT: the same word covers the decomposer in soil and the producer in the sea.","cn":"生境：同一个词既涵盖土壤中的分解者，也涵盖海洋中的生产者。"},{"senses":"S6 · S7","en":"ROLE TOWARD HUMANS: one subset causes disease, another ferments food and makes medicine.","cn":"对人的角色：一个子集致病，另一个子集发酵食物、制造药物。"},{"senses":"S8","en":"PROXY: an indicator microorganism is watched not for itself but for what its presence means.","cn":"替身：监测指示微生物不是为了它本身，而是为了它的存在所意味的东西。"}]},"affixes":{"intro":{"en":"Microorganism is a two-part scientific compound: a Greek prefix for smallness and a Greek-derived noun for a living body, joined in English.","cn":"microorganism 是两部分组成的科学复合词：表示「微小」的希腊前缀，加上希腊来源的「生物体」名词，在英语中组合而成。"},"latinIntro":{"en":"Neither element is native Latin: micro- is the Latinized form of Greek mikros, and organismus is Modern/Medical Latin built on Greek organon. The compound itself was made in English, so no single Latin etymon exists.","cn":"两个成分都不是本族拉丁语：micro- 是希腊 mikros 的拉丁化形式，organismus 是建立在希腊 organon 上的现代或医学拉丁语。复合词本身在英语中构成，因此没有单一拉丁语词源。"},"items":[{"word":"microorganism","structure":"micro- (small) + organism (living body)","meaning":"a living thing visible only under a microscope","meaningCN":"只有借助显微镜才可见的生物","example":"A microorganism started the bloom.","exampleCN":"一种微生物引发了这次水华。"},{"word":"micro-organism","structure":"hyphenated variant of microorganism","meaning":"same meaning, older British spelling","meaningCN":"同义，英式旧拼写","example":"Early papers wrote micro-organism.","exampleCN":"早期论文写作 micro-organism。"},{"word":"microbe","structure":"micro- + Greek bios (life)","meaning":"a very small living thing","meaningCN":"极小的生物","example":"The microbe was first seen in 1878.","exampleCN":"这种微生物最早于 1878 年被观察到。"},{"word":"microbial","structure":"microbe + -al (relation)","meaning":"of microbes","meaningCN":"微生物的","example":"Microbial life fills the mat.","exampleCN":"微生物生命填满了这片菌席。"},{"word":"microbiology","structure":"micro- + biology (study of life)","meaning":"the science of microorganisms","meaningCN":"研究微生物的科学","example":"Microbiology became a degree in 1880.","exampleCN":"微生物学在 1880 年成为一门学科。"},{"word":"microbiologist","structure":"microbiology + -ist (person)","meaning":"a specialist in microorganisms","meaningCN":"研究微生物的专家","example":"The microbiologist grew the sample.","exampleCN":"微生物学家培养了这份样本。"},{"word":"microbiota","structure":"micro- + biota (life of a region)","meaning":"the microorganisms of a particular place","meaningCN":"某一特定地点的微生物群落","example":"The gut microbiota changed with diet.","exampleCN":"肠道微生物群落随饮食而变。"},{"word":"microbiome","structure":"micro- + biome (life community)","meaning":"the whole community and its genes","meaningCN":"整个微生物群落及其基因","example":"The skin microbiome differs by site.","exampleCN":"皮肤微生物组因部位而异。"},{"word":"microscope","structure":"micro- + -scope (viewing instrument)","meaning":"an instrument for viewing small things","meaningCN":"观察微小物体的仪器","example":"The microscope revealed the cells.","exampleCN":"显微镜使这些细胞显现出来。"}],"latinEntries":[{"word":"organismus","structure":"organismus, -i (m., Medical/Modern Latin, from Greek organon)","meaning":"an organized living body","meaningCN":"有组织的生物体"},{"word":"organum","structure":"organum, -i (n., Latin, from Greek organon)","meaning":"tool, instrument; organ of the body","meaningCN":"工具、器具；身体器官"}]}},{"word":"microbial","ipa_uk":"/maɪˈkrəʊbiəl/","ipa_us":"/maɪˈkroʊbiəl/","definition_zh":"微生物的；由微生物引起的；与微生物有关的","definition_en":"of, relating to, or caused by microbes","core_image":"岩石表面一层黏滑的绿色菌席，在放大镜下由无数微小细胞连成一片","scene":"The microbial mat on the rock surface turned the shallow water green.","sceneCN":"这里 microbial 是「微生物的」（第 1 个义项：与微生物相关）；句意：岩石表面的微生物席把浅水染成了绿色。图中可辨识物件：岩石、贴附其上的菌席、被映绿的水面。","pos":[{"tag":"adj.","zh":"微生物的；由微生物引起的（由名词 microbe 加 -ial 构成，范围比 bacterial 更宽）"}],"collocations":[{"phrase":"microbial growth","zh":"微生物生长"},{"phrase":"microbial community","zh":"微生物群落"},{"phrase":"microbial infection","zh":"微生物感染"},{"phrase":"microbial contamination","zh":"微生物污染"},{"phrase":"microbial fuel cell","zh":"微生物燃料电池"},{"phrase":"microbial decomposition","zh":"微生物分解"}],"forms":[{"label":"原级（形容词）","form":"microbial（微生物的）"},{"label":"另一形容词形式","form":"microbic（微生物的；罕用同义变体）"},{"label":"副词形式","form":"microbially（以微生物方式地）"},{"label":"名词单数","form":"microbe（微生物）"},{"label":"名词复数","form":"microbes（微生物，复数）"},{"label":"相关名词","form":"microbiota（微生物区系）；microbiome（微生物组）"}],"derivatives":[{"word":"microbe","pos":"n.","zh":"微生物（尤指致病的微小生物）"},{"word":"microbes","pos":"n.","zh":"微生物（复数）"},{"word":"microbic","pos":"adj.","zh":"微生物的（罕用变体）"},{"word":"microbially","pos":"adv.","zh":"以微生物方式地"},{"word":"microbiology","pos":"n.","zh":"微生物学"},{"word":"microbiota","pos":"n.","zh":"微生物区系；特定生境的微生物群落"},{"word":"microbiome","pos":"n.","zh":"微生物组"}],"senses":[{"no":"01","title":"Of Microbes in General","titleCN":"微生物的：与微生物这一类相关","definition":"relating to microbes as a broad class of small life","definitionCN":"与作为一大类微小生命的微生物有关的","example":"Microbial life exists in every handful of garden soil.","exampleCN":"每一把园土里都有微生物生命。","why":"Microbial is built on microbe, a popular nineteenth-century word for small life. The suffix -ial marks relation, so the adjective is wider than bacterial and can cover fungi and protists as well.","whyCN":"microbial 建立在 microbe 上，那是十九世纪指微小生命的通俗词；后缀 -ial 表示关联，因此这个形容词比 bacterial 更宽，也能涵盖真菌与原生生物。"},{"no":"02","title":"Microbial Life","titleCN":"微生物生命：作为生命形态本身","definition":"the living activity of microbes taken as a whole","definitionCN":"把微生物作为整体来看的生命活动","example":"Microbial life in the vent thrives without sunlight.","exampleCN":"热泉喷口处的微生物生命不依赖阳光而繁盛。","why":"Here the adjective modifies life itself, not a process or a disease. The phrase treats microbes as a form of life with its own chemistry, such as chemosynthesis.","whyCN":"这里形容词修饰的是「生命」本身，而不是某个过程或疾病；该短语把微生物视为一种有自身化学机制（如化能合成）的生命形态。"},{"no":"03","title":"A Microbial Community","titleCN":"微生物群落的：共同生活的集合","definition":"relating to a community or assemblage of microbes","definitionCN":"与微生物群落或集合体有关的","example":"The microbial community in the gut shifted after the antibiotic.","exampleCN":"使用抗生素后，肠道中的微生物群落发生了变化。","why":"A community is more than many cells; it is a set of populations that interact. The adjective marks that ecological level, which is why microbial community and microbiome are so frequent.","whyCN":"群落不只是许多细胞，而是相互作用的种群集合；这个形容词标出的是生态层次，因此 microbial community 与 microbiome 如此常用。"},{"no":"04","title":"Microbial Growth","titleCN":"微生物生长的：数量增加的过程","definition":"relating to the increase of microbial populations","definitionCN":"与微生物种群数量增加有关的","example":"Microbial growth in the tank was measured every hour.","exampleCN":"罐中的微生物生长每小时测量一次。","why":"Growth here is population growth, not the enlargement of one body. The adjective attaches the process to the microbial level, as bacterial growth does for one kind of microbe.","whyCN":"这里的生长是种群增长，而不是单个身体变大；这个形容词把过程固定在微生物层次，正如 bacterial growth 固定于细菌这一类。"},{"no":"05","title":"Microbial Infection","titleCN":"微生物感染的：由微生物侵入引起","definition":"caused by microbes entering a host","definitionCN":"由微生物侵入宿主引起的","example":"The burns unit screened every patient for microbial infection.","exampleCN":"烧伤病房对每位病人进行微生物感染筛查。","why":"In clinical use the adjective can stand in for a cause, like bacterial but broader. The speaker may not yet know which microbe is responsible, so the general term is preferred.","whyCN":"在临床用法中，这个形容词可以像 bacterial 一样表示病因，但范围更宽；说话人可能还不知道是哪种微生物，因此宁用泛称。"},{"no":"06","title":"Microbial Technology","titleCN":"微生物技术的：把微生物当作工具","definition":"relating to the use of microbes in technology or industry","definitionCN":"与在技术或工业中利用微生物有关的","example":"The microbial fuel cell produced current from waste water.","exampleCN":"微生物燃料电池用废水产生了电流。","why":"Here microbes are components of an engineered system. The adjective moves from biology to engineering: the organism is valued for a function it can be made to perform.","whyCN":"这里微生物是工程系统的部件；这个形容词从生物学转向工程学：生物体因其可被安排执行的功能而受重视。"},{"no":"07","title":"Microbial Decomposition","titleCN":"微生物分解的：物质循环中的分解","definition":"relating to the breakdown of matter by microbes","definitionCN":"与微生物分解物质有关的","example":"Microbial decomposition returned the carbon to the soil.","exampleCN":"微生物分解把碳归还给土壤。","why":"Decomposition is a service performed by microbes in every ecosystem. The adjective names the agent of the process, which is why it often appears in ecology and waste treatment.","whyCN":"分解是微生物在每个生态系统中提供的服务；这个形容词命名过程的执行者，因此常出现在生态学与废物处理语境中。"},{"no":"08","title":"Microbial Contamination","titleCN":"微生物污染的：产品或环境被沾染","definition":"relating to contamination by microbes","definitionCN":"与微生物造成的污染有关的","example":"Microbial contamination closed the bottling line for a week.","exampleCN":"微生物污染使灌装线停工一周。","why":"Contamination names the entry of unwanted microbes into a product or a place. The adjective identifies the kind of unwanted life, not the process by which it got in.","whyCN":"污染指不需要的微生物进入产品或场所；这个形容词指明的是不受欢迎的生命种类，而不是它们进入的方式。"}],"etymology":{"intro":{"en":"Microbial is the adjective of microbe, a French coinage of 1878 that was itself built from two Greek elements. Its birth date is known, but its second element was chosen in a way that Greek would not have allowed.","cn":"microbial 是 microbe 的形容词，microbe 是 1878 年法语造出的词，本身由两个希腊成分构成。它的生日已知，但第二个成分的选择方式在希腊语里其实并不成立。"},"items":[{"era":"GREEK MIKROS","en":"Greek mikros, Attic for smikros, meant 'small'. Its Latinized form micro- became the scientific prefix for the very small. Beekes suggests the Greek word may be Pre-Greek, so its deeper source is uncertain.","cn":"希腊语 mikros（阿提卡形式 smikros）意为「小」，其拉丁化形式 micro- 成为表示「极小」的科学前缀。Beekes 认为这个希腊词可能来自前希腊语底层，因此更深来源不确定。"},{"era":"GREEK BIOS","en":"Greek bios meant 'life, course of life, lifetime', as opposed to zōē, 'animal life'. It supplies the second element of many modern compounds through the combining form bio-.","cn":"希腊语 bios 意为「生命、生命历程、寿命」，与表示动物生命的 zōē 相对；它通过组合形式 bio- 为许多现代复合词提供第二成分。"},{"era":"SÉDILLOT'S 1878 COINAGE","en":"French microbe was coined in 1878 by the surgeon Charles Sédillot. Etymonline, quoting Weekley, calls it 'badly coined', because in Greek the compound would mean 'short-lived' rather than 'small living thing'. The intended meaning won anyway.","cn":"法语 microbe 由外科医生夏尔·塞迪约于 1878 年创制。etymonline 引用 Weekley 的说法称其「造得不好」，因为在希腊语中这个复合词会表示「短命的」，而不是「微小的生物」。但意图中的意义最终胜出。"},{"era":"MICROBIAL, 1879","en":"Microbial is recorded from 1879, from Modern Latin microbion, the Latinized form of microbe, plus the adjective ending -al. The adjective therefore entered English one year after the noun.","cn":"microbial 记录于 1879 年，由 microbe 的拉丁化形式现代拉丁 microbion 加形容词词尾 -al 构成；因此形容词比名词晚一年进入英语。"},{"era":"MICROBE VERSUS MICROORGANISM","en":"Microbe was coined as a popular word for disease-causing small life; microorganism, from 1855, is the neutral scientific term. Microbial inherits the popular word's breadth and its medical flavour.","cn":"microbe 创制时是「致病微小生命」的通俗词，而 1855 年出现的 microorganism 是中性的科学术语。microbial 继承了通俗词的宽泛范围与医学色彩。"},{"era":"MODERN MICROBIOME","en":"Since the 2000s microbial has appeared in microbial ecology, microbial genetics and microbiome research. In these names it marks a level of biological organisation rather than a single organism.","cn":"自本世纪以来，microbial 出现在微生物生态学、微生物遗传学与微生物组研究中；在这些名称里，它标出的是一个生物组织层次，而不是单个生物体。"}]},"similar":{"note":{"en":"The first group holds adjectives and nouns built on the microbe stem. The second group holds overlapping terms whose scope or register differs.","cn":"第一组是建立在 microbe 词干上的形容词与名词；第二组是范围或语体不同的重叠词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"microbic","ipa":"/maɪˈkrəʊbɪk/","tag":"adjective, rare variant","definition":"An older and rarer synonym of microbial, formed with -ic instead of -ial. It appears mainly in nineteenth- and early twentieth-century writing.","definitionCN":"microbial 的旧式罕用同义词，用 -ic 而非 -ial 构成；主要见于十九世纪与二十世纪初的文字。"},{"word":"microbially","ipa":"/maɪˈkrəʊbiəli/","tag":"adverb","definition":"The adverb, meaning 'by or with microbes'. It is technical and uncommon outside laboratory writing.","definitionCN":"副词，意为「借微生物作用地」；属于技术用语，实验室文字之外少见。"},{"word":"microbiology","ipa":"/ˌmaɪkrəʊbaɪˈɒlədʒi/","tag":"noun, the science","definition":"The study of microbes. The ending -logy marks a field, so it cannot substitute for the adjective.","definitionCN":"研究微生物的学科；词尾 -logy 表示领域，不能代替形容词使用。"}]},{"heading":"NEAR-SYNONYMS","entries":[{"word":"bacterial","ipa":"/bækˈtɪəriəl/","tag":"adjective, narrower","definition":"Of bacteria only. It is the right word when the group is known to be bacterial, and microbial is the right word when fungi or protists may be involved.","definitionCN":"只指细菌的；当已知是细菌时用 bacterial，当可能涉及真菌或原生生物时用 microbial。"},{"word":"microbiological","ipa":"/ˌmaɪkrəʊbaɪəˈlɒdʒɪkəl/","tag":"adjective, of the science","definition":"Relating to microbiology as a discipline or to its methods, as in microbiological testing. It points to the science, not directly to the organisms.","definitionCN":"与微生物学这一学科或其方法有关的，如微生物学检测；它指向学科，而不是直接指向生物体。"},{"word":"pathogenic","ipa":"/ˌpæθəˈdʒenɪk/","tag":"adjective, harmful","definition":"Disease-causing. It says nothing about size or kingdom, and many microbes are not pathogenic.","definitionCN":"指致病的；不涉及大小或生物界，而许多微生物并不致病。"},{"word":"germinal","ipa":"/ˈdʒɜːmɪnəl/","tag":"adjective, of seeds or early growth","definition":"Relating to a germ or seed, or to an early stage of development. It is not a synonym of microbial despite the everyday sense of germ.","definitionCN":"指胚芽、种子或发育早期的；尽管 germ 有「病菌」的日常义，germinal 并不是 microbial 的同义词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"microbe + -ial: 'having to do with microbes', broader than bacterial.","cn":"microbe + -ial：意为「与微生物有关」，范围比 bacterial 更宽。"},{"en":"micro- is 'small', bios is 'life'; the compound was meant to say 'small life'.","cn":"micro- 是「小」，bios 是「生命」；这个复合词本意是说「微小的生命」。"},{"en":"The noun arrived in 1878 and the adjective in 1879, so the pair is almost the same age.","cn":"名词 1878 年出现，形容词 1879 年出现，两者几乎同龄。"},{"en":"The family runs microbe, microbes, microbial, microbic, microbially, microbiology and microbiome.","cn":"同族词包括 microbe、microbes、microbial、microbic、microbially、microbiology、microbiome。"},{"en":"Use microbial when the kind is unknown or mixed; use bacterial when only bacteria are meant.","cn":"种类未知或混杂时用 microbial；只指细菌时用 bacterial。"}],"abstract":[{"en":"Picture a green skin over a wet rock, made of cells too small to name one by one.","cn":"想象湿岩石上的一层绿皮，由小到无法逐个命名的细胞构成。"},{"en":"Picture a city whose citizens are invisible but whose work keeps the streets clean.","cn":"想象一座城市，市民看不见，而他们的工作让街道保持清洁。"},{"en":"Picture a power station run by creatures you need a lens to meet.","cn":"想象一座由必须借助镜片才能见到的生物运转的电站。"}]},"examples":[{"en":"Microbial activity made the sealed jar swell with gas.","cn":"微生物活动使密封罐因气体而鼓起。"},{"en":"The microbial community on the skin protects against some invaders.","cn":"皮肤上的微生物群落能抵御某些入侵者。"},{"en":"Microbial contamination was found in three of the sampled bottles.","cn":"抽样检测的瓶子中有三瓶发现了微生物污染。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"microbe（微生物）+ -ial（与……有关的）→ 与微生物有关的 → microbial 微生物的","word":"microbial"},"root":"希腊 mikros「小」→ 拉丁化 micro- + 希腊 bios「生命」→ 法语 microbe（1878 年塞迪约创制）→ 现代拉丁 microbion → 英语 microbial（microbion + -al，1879）。","sensesIntro":{"en":"Eight senses attach the adjective to eight objects: the class, life itself, a community, a population, an infection, a technology, a decomposition and a contamination.","cn":"八个义项把这个形容词接到八个对象上：类别、生命本身、群落、种群、感染、技术、分解与污染。"},"semanticMap":{"core":{"en":"CORE IMAGE: a slippery green mat over wet rock, made of countless invisible cells.","cn":"核心意象：湿岩石上的一层滑绿菌席，由无数看不见的细胞构成。"},"chain":["OF MICROBES","LIFE ITSELF","A COMMUNITY","A POPULATION","AN INFECTION","AN INDUSTRY"],"branches":[{"senses":"S1 · S2","en":"THE CLASS AND LIFE: the broadest relation, then the same adjective applied to life as a form.","cn":"类别与生命：最宽泛的关联，随后同一形容词落在作为一种形态的生命上。"},{"senses":"S3 · S4","en":"COLLECTIVE AND QUANTITATIVE: a community is organised, while growth is a population count over time.","cn":"集体与数量：群落是有组织的，生长则是种群随时间的计数。"},{"senses":"S5","en":"HARM: the adjective can name a cause of disease without naming the species.","cn":"危害：这个形容词可以只命名病因，而不指明物种。"},{"senses":"S6 · S7","en":"WORK: microbes are put to work in fuel cells and in the decomposition that recycles matter.","cn":"工作：微生物被用于燃料电池，也用于使物质循环的分解过程。"},{"senses":"S8","en":"UNWANTED PRESENCE: contamination is the same life arriving where it is not wanted.","cn":"不受欢迎的存在：污染就是同样的生命来到了不该来的地方。"}]},"affixes":{"intro":{"en":"Microbial combines a Greek prefix for smallness, a Greek root for life, and a Latin adjective ending, with a Modern Latin noun in between.","cn":"microbial 由表示「微小」的希腊前缀、表示「生命」的希腊词根、中间的现代拉丁名词与拉丁形容词词尾组合而成。"},"latinIntro":{"en":"Modern Latin microbion Latinized the French microbe before English added -al. There is no classical Latin etymon for microbe; the Latin-looking shape is a modern scientific construction.","cn":"在现代拉丁语中，microbion 把法语 microbe 拉丁化，随后英语加上 -al。microbe 没有古典拉丁语词源；它看似拉丁的外形只是现代科学构造。"},"items":[{"word":"microbial","structure":"microbion + -al (relation)","meaning":"of or caused by microbes","meaningCN":"微生物的或由微生物引起的","example":"Microbial growth filled the dish.","exampleCN":"微生物生长充满了培养皿。"},{"word":"microbe","structure":"Greek mikros (small) + bios (life)","meaning":"a very small living thing","meaningCN":"极小的生物","example":"The microbe was cultured from the wound.","exampleCN":"从伤口中培养出了这种微生物。"},{"word":"microbes","structure":"microbe + plural -s","meaning":"more than one microbe","meaningCN":"不止一个微生物","example":"Microbes colonise the gut at birth.","exampleCN":"微生物在出生时定殖于肠道。"},{"word":"microbic","structure":"microbe + -ic (relation)","meaning":"of microbes, rare variant","meaningCN":"微生物的，罕用变体","example":"Old texts speak of microbic disease.","exampleCN":"旧文献会说到微生物疾病。"},{"word":"microbially","structure":"microbial + -ly (adverb)","meaning":"by microbial action","meaningCN":"通过微生物作用地","example":"The waste was microbially degraded.","exampleCN":"废物被微生物降解了。"},{"word":"microbiology","structure":"micro- + biology (life study)","meaning":"the science of microbes","meaningCN":"研究微生物的科学","example":"Microbiology examines both harm and use.","exampleCN":"微生物学既研究危害也研究用途。"},{"word":"microbiota","structure":"micro- + biota (regional life)","meaning":"the microbes of one place","meaningCN":"某一地点的微生物群落","example":"The oral microbiota differs from the gut's.","exampleCN":"口腔微生物区系与肠道的不同。"},{"word":"microbiome","structure":"micro- + biome (life community)","meaning":"a microbial community and its genes","meaningCN":"微生物群落及其基因","example":"The microbiome was sequenced in full.","exampleCN":"该微生物组被完整测序。"}],"latinEntries":[{"word":"microbion","structure":"microbion, -ii (n., Modern Latin latinization of French microbe)","meaning":"a very small living thing","meaningCN":"极小的生物"},{"word":"organismus","structure":"organismus, -i (m., Medical Latin, from Greek organon)","meaning":"organized living body","meaningCN":"有组织的生物体"}]}},{"word":"microbiology","ipa_uk":"/ˌmaɪkrəʊbaɪˈɒlədʒi/","ipa_us":"/ˌmaɪkroʊbaɪˈɑːlədʒi/","definition_zh":"微生物学；研究微生物及其活动的学科","definition_en":"the science that studies microorganisms, their structure, growth, and effects","core_image":"实验台上成排的培养皿与显微镜，标签上写满菌种编号，一张记录表逐项填写","scene":"Clinical microbiology identified the strain before the second dose was given.","sceneCN":"这里 microbiology 是「微生物学」（第 3 个义项：临床微生物学这一分支）；句意：临床微生物学在给予第二剂之前就鉴定了菌株。图中可辨识物件：培养皿、显微镜、菌种鉴定报告。","pos":[{"tag":"n.","zh":"微生物学（不可数名词）；指学科时通常不加冠词，指某一分支时可加限定语"}],"collocations":[{"phrase":"clinical microbiology","zh":"临床微生物学"},{"phrase":"food microbiology","zh":"食品微生物学"},{"phrase":"environmental microbiology","zh":"环境微生物学"},{"phrase":"microbiology laboratory","zh":"微生物学实验室"},{"phrase":"microbiology department","zh":"微生物学系；微生物科"},{"phrase":"molecular microbiology","zh":"分子微生物学"}],"forms":[{"label":"学科名词","form":"microbiology（微生物学，不可数）"},{"label":"从业者","form":"microbiologist（微生物学家）"},{"label":"形容词形式","form":"microbiological（微生物学的）"},{"label":"副词形式","form":"microbiologically（从微生物学角度地）"},{"label":"研究对象","form":"microorganism / microbe（微生物）"}],"derivatives":[{"word":"microbiologist","pos":"n.","zh":"微生物学家"},{"word":"microbiological","pos":"adj.","zh":"微生物学的；微生物学方法的"},{"word":"microbiologically","pos":"adv.","zh":"从微生物学角度地"},{"word":"microbe","pos":"n.","zh":"微生物"},{"word":"microbial","pos":"adj.","zh":"微生物的"},{"word":"microbiome","pos":"n.","zh":"微生物组"},{"word":"biotechnology","pos":"n.","zh":"生物技术（与微生物学交叉的现代领域）"}],"senses":[{"no":"01","title":"The Science of Microbes","titleCN":"微生物学：研究微生物的科学","definition":"the branch of biology that studies microorganisms","definitionCN":"生物学中研究微生物的分支","example":"Microbiology asks how a single cell can live, grow and cause disease.","exampleCN":"微生物学追问一个细胞如何生存、生长并致病。","why":"The word joins micro-, 'small', biology, 'study of life', and -logy, 'science of'. The core is a discipline, not an organism: it names the organised knowledge about small life.","whyCN":"这个词由 micro-「小」、biology「生命研究」与 -logy「……学」构成；核心是一门学科，而不是某种生物：它命名的是关于微小生命的系统知识。"},{"no":"02","title":"A Discipline and a Department","titleCN":"学科与院系：作为建制单位","definition":"the academic field or the institutional unit that teaches and researches it","definitionCN":"教授与研究该领域的学术建制或单位","example":"She joined the microbiology department as a lecturer.","exampleCN":"她以讲师身份加入了微生物学系。","why":"A science becomes an institution: it has chairs, degrees, journals and laboratories. The uncountable name can therefore stand for the department that houses the field.","whyCN":"一门科学会变成一种建制：它拥有教席、学位、期刊与实验室；因此这个不可数名词可以代指容纳该领域的院系。"},{"no":"03","title":"Clinical Microbiology","titleCN":"临床微生物学：为诊断服务","definition":"the branch that identifies microbes causing human disease","definitionCN":"鉴定引起人类疾病的微生物的分支","example":"Clinical microbiology reports the species and its drug sensitivity.","exampleCN":"临床微生物学报告菌种及其药物敏感性。","why":"In hospital use the science is narrowed to diagnosis. The adjective clinical marks the setting, and the work is to name the agent and guide treatment.","whyCN":"在医院语境中，这门科学被收窄为诊断用途；形容词 clinical 标出场景，工作内容是命名病原并指导治疗。"},{"no":"04","title":"Food and Industrial Microbiology","titleCN":"食品与工业微生物学：发酵与保质","definition":"the branch concerned with fermentation, preservation and industrial use","definitionCN":"研究发酵、防腐与工业应用的微生物学分支","example":"Food microbiology keeps cheese cultures pure and spoilage out.","exampleCN":"食品微生物学保持奶酪菌种纯净，并防止腐败。","why":"Here the discipline serves production: it manages useful microbes and excludes harmful ones. The same science that studies disease also runs a factory.","whyCN":"这里这门学科为生产服务：管理有益微生物、排除有害微生物；研究疾病的同一门科学，也在经营工厂。"},{"no":"05","title":"Environmental Microbiology","titleCN":"环境微生物学：生境中的微生物","definition":"the branch that studies microbes in soil, water and air","definitionCN":"研究土壤、水体与空气中微生物的分支","example":"Environmental microbiology traced the oil spill's cleanup to local bacteria.","exampleCN":"环境微生物学把漏油的清理归功于本地细菌。","why":"The setting shifts from the clinic to the ecosystem. The discipline asks how microbial communities cycle elements and degrade pollutants.","whyCN":"场景从诊室转向生态系统；这门学科研究微生物群落如何循环元素、降解污染物。"},{"no":"06","title":"Laboratory Methods","titleCN":"实验室方法：培养、染色与鉴定","definition":"the practical methods of culturing, staining and identifying microbes","definitionCN":"培养、染色与鉴定微生物的实用方法","example":"The course begins with the microbiology of streaking a plate.","exampleCN":"这门课从平板划线这一微生物学基本操作开始。","why":"A science is also a set of hands-on techniques. The name can denote the method side, which is why a laboratory course and a research field share the word.","whyCN":"一门科学也是一套动手技术；这个名称可以指方法层面，因此实验室课程与研究领域共用同一个词。"},{"no":"07","title":"A Course or a Textbook","titleCN":"课程与教材：作为教学科目","definition":"a course or textbook that teaches the subject","definitionCN":"教授该科目的课程或教材","example":"Microbiology is a second-year course in most biology programmes.","exampleCN":"在多数生物专业中，微生物学是二年级课程。","why":"The name of a science can metonymically name its teaching. Students say they are taking microbiology, meaning the course rather than the whole field.","whyCN":"学科名可以通过转喻指它的教学；学生说自己在上微生物学，指的是课程，而不是整个领域。"},{"no":"08","title":"The Microbes of a Sample","titleCN":"样本的微生物组成：转喻用法","definition":"the microbial content or profile of a sample or a body site","definitionCN":"某样本或身体部位的微生物组成或图谱","example":"The microbiology of the gut changed after the treatment.","exampleCN":"治疗之后，肠道的微生物组成发生了变化。","why":"Professional shorthand says the microbiology of a site when it means the microbes found there. The discipline name stands for its object, a familiar kind of metonymy.","whyCN":"专业简称会说某部位的「微生物学」，实际指的是该处检出的微生物；学科名代替了它的研究对象，这是常见的转喻。"}],"etymology":{"intro":{"en":"Microbiology was coined in English in 1880 by joining the Greek prefix micro- to biology, a word itself only sixty years older. Its history shows how a new instrument, the microscope, created a new science.","cn":"microbiology 于 1880 年在英语中由希腊前缀 micro- 与 biology 组合而成，而 biology 本身只比它早六十年。它的历史显示，一件新工具——显微镜——如何创造出一门新科学。"},"items":[{"era":"GREEK MIKROS","en":"Greek mikros, Attic smikros, meant 'small'. The Latinized prefix micro- entered scientific English as the standard marker of the very small. Beekes suspects a Pre-Greek origin, so the deeper etymology is uncertain.","cn":"希腊语 mikros（阿提卡形式 smikros）意为「小」；拉丁化前缀 micro- 作为「极小」的标准标记进入科学英语。Beekes 怀疑它源自前希腊语底层，因此更深词源不确定。"},{"era":"BIOLOGY, 1819","en":"Biology was suggested in 1802 by Treviranus and introduced in French by Lamarck, entering English by 1819. It joins Greek bios 'life' and -logia 'study, discourse'.","cn":"biology 由特雷维拉努斯于 1802 年提出，并由拉马克以法语引入，1819 年进入英语；它由希腊 bios「生命」与 -logia「研究、论述」构成。"},{"era":"THE -LOGY SUFFIX","en":"Greek -logia came from -log-, the combining form of legein 'to speak, tell', itself from a root meaning 'to gather, pick out'. Hence -logy names a disciplined way of speaking about a subject.","cn":"希腊 -logia 来自 -log-，即 legein「说、讲述」的组合形式，其词根意为「收集、拣选」；因此 -logy 命名的是关于某主题的一套有纪律的论述方式。"},{"era":"COINED IN 1880","en":"Microbiology is recorded from 1880, coined in English from micro- and biology. The same period produced microbiologist (1882) and the adjective microbiological.","cn":"microbiology 记录于 1880 年，在英语中由 micro- 与 biology 构成；同一时期还产生了 microbiologist（1882）与形容词 microbiological。"},{"era":"THE GERM THEORY CONTEXT","en":"Pasteur's and Koch's work in the 1870s and 1880s gave the new science its first great successes: sterilisation, pure culture and the identification of specific pathogens.","cn":"巴斯德与科赫在十九世纪七十至八十年代的工作，给这门新科学带来最初的重大成功：灭菌、纯培养与特定病原的鉴定。"},{"era":"FROM BACTERIOLOGY TO MICROBIOLOGY","en":"The older name bacteriology covered only bacteria. Microbiology became the wider term once protists, fungi and later viruses were studied with the same methods. The shift is a widening of the object, not a change of root.","cn":"较早的 bacteriology 只涵盖细菌；当原生生物、真菌以及后来的病毒用同样方法研究之后，microbiology 成为更宽的名称。这一变化是研究对象的扩展，而不是词根的更换。"}]},"similar":{"note":{"en":"The first group holds words built on the same stem that occupy other grammatical or professional slots. The second group holds neighbouring disciplines, each with a narrower object.","cn":"第一组是同词干上占据其他语法或职业位置的词；第二组是相邻学科，各自的研究对象更窄。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"microbiologist","ipa":"/ˌmaɪkrəʊbaɪˈɒlədʒɪst/","tag":"noun, person","definition":"A person who practises microbiology. The ending -ist marks the practitioner, not the field.","definitionCN":"从事微生物学的人；词尾 -ist 标记从业者，而不是学科。"},{"word":"microbiological","ipa":"/ˌmaɪkrəʊbaɪəˈlɒdʒɪkəl/","tag":"adjective","definition":"Relating to microbiology or its methods, as in microbiological safety. It describes the discipline's procedures rather than the organisms.","definitionCN":"与微生物学或其方法有关的，如微生物学安全；描述的是学科程序，而不是生物体。"},{"word":"microbial","ipa":"/maɪˈkrəʊbiəl/","tag":"adjective, of microbes","definition":"Of microbes themselves. It is the object-level adjective, while microbiological is the discipline-level one.","definitionCN":"指微生物本身的形容词；它是对象层面的形容词，而 microbiological 是学科层面的。"}]},{"heading":"NEAR-SYNONYMS","entries":[{"word":"bacteriology","ipa":"/bækˌtɪəriˈɒlədʒi/","tag":"noun, narrower field","definition":"The study of bacteria only. It is a subset of microbiology and was the older name for much of the same work.","definitionCN":"只研究细菌的学科；它是微生物学的子集，也曾是大部分同类工作的旧名称。"},{"word":"virology","ipa":"/vaɪˈrɒlədʒi/","tag":"noun, viruses only","definition":"The study of viruses, which are not cells and are often excluded from microorganisms. It is a separate discipline with separate methods.","definitionCN":"研究病毒的学科；病毒不是细胞，常被排除在微生物之外，因此它是一门有独立方法的独立学科。"},{"word":"mycology","ipa":"/maɪˈkɒlədʒi/","tag":"noun, fungi only","definition":"The study of fungi, including yeasts and moulds. Many fungi are microorganisms, but the discipline is defined by the group, not the size.","definitionCN":"研究真菌（包括酵母与霉菌）的学科；许多真菌是微生物，但这门学科按类群而非大小定义。"},{"word":"biotechnology","ipa":"/ˌbaɪəʊtekˈnɒlədʒi/","tag":"noun, applied field","definition":"The industrial use of living systems, microbes among them. It is an application of microbiology rather than a branch of it.","definitionCN":"对生命系统（包括微生物）的工业利用；它是微生物学的应用，而不是其分支。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"micro- 'small' + biology 'study of life' + -logy 'science of': the science of small life.","cn":"micro-「小」+ biology「生命研究」+ -logy「……学」：研究微小生命的科学。"},{"en":"The word was coined in 1880, one year after microbial and two after microbe.","cn":"这个词于 1880 年创制，比 microbial 晚一年，比 microbe 晚两年。"},{"en":"The family runs microbiology, microbiologist, microbiological, microbiologically, microbe, microbial and microbiome.","cn":"同族词包括 microbiology、microbiologist、microbiological、microbiologically、microbe、microbial、microbiome。"},{"en":"Prefixes mark the branch: clinical, food, environmental, molecular and industrial microbiology.","cn":"限定语标出分支：临床、食品、环境、分子与工业微生物学。"},{"en":"Microbiology is wider than bacteriology because its object is defined by size, not by kingdom.","cn":"microbiology 比 bacteriology 宽，因为它的对象按大小定义，而不是按生物界定义。"}],"abstract":[{"en":"Picture a science that began the day a lens made a hidden world visible.","cn":"想象一门科学，始于镜片让隐藏世界变得可见的那一天。"},{"en":"Picture a department where every shelf holds a dish of invisible citizens.","cn":"想象一个院系，每个架子上都放着一盘看不见的居民。"},{"en":"Picture a single cell asked to explain both a disease and a loaf of bread.","cn":"想象要求一个细胞同时解释一场疾病和一条面包。"}]},"examples":[{"en":"Microbiology turned the unknown outbreak into a named species.","cn":"微生物学把不明疫情变成了一个有名字的物种。"},{"en":"She studied microbiology before moving into public health.","cn":"她在转入公共卫生之前学习过微生物学。"},{"en":"Industrial microbiology keeps the fermentation tanks free of spoilage.","cn":"工业微生物学让发酵罐免于腐败。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"micro-（微小）+ biology（生物学）→ 研究微小生物的学科 → microbiology 微生物学","word":"microbiology"},"root":"希腊 mikros「小」→ 拉丁化 micro-；希腊 bios「生命」+ -logia「研究、论述」→ biology（1819 年入英语）→ 1880 年英语合成 micro- + biology = microbiology。","sensesIntro":{"en":"Eight senses move from the science itself to its institutional, clinical, industrial, environmental, practical, teaching and metonymic uses.","cn":"八个义项从这门科学本身，走向它的建制、临床、工业、环境、实践、教学与转喻用法。"},"semanticMap":{"core":{"en":"CORE IMAGE: rows of labelled dishes on a bench, a microscope and a report being filled in.","cn":"核心意象：实验台上一排贴标签的培养皿、显微镜，以及正在填写的报告。"},"chain":["THE SCIENCE","THE INSTITUTION","THE CLINIC","THE FACTORY","THE FIELD SITE","THE CLASSROOM"],"branches":[{"senses":"S1","en":"KNOWLEDGE: the organised study of small life is the root sense from which the others radiate.","cn":"知识：关于微小生命的系统研究是根义，其他义项都由它辐射而出。"},{"senses":"S2 · S7","en":"INSTITUTION AND TEACHING: a science can be a department or a course, because people organise and teach it.","cn":"建制与教学：一门科学可以是一个院系或一门课，因为人们会组织它、教授它。"},{"senses":"S3 · S4","en":"APPLIED SETTINGS: the clinic names pathogens, the factory manages cultures.","cn":"应用场景：诊所命名病原，工厂管理菌种。"},{"senses":"S5","en":"ENVIRONMENT: the same methods move outdoors to soil, water and air.","cn":"环境：同样的方法移到户外，用于土壤、水体与空气。"},{"senses":"S6 · S8","en":"HANDS AND OBJECT: techniques are the hands of the science, and 'the microbiology of a site' is its object standing in for it.","cn":"双手与对象：技术是这门科学的双手，而「某处的微生物学」是它的研究对象代它出场。"}]},"affixes":{"intro":{"en":"Microbiology stacks three Greek elements: a prefix of smallness, a root of life, and a suffix of disciplined study.","cn":"microbiology 叠合了三个希腊成分：表示「微小」的前缀、表示「生命」的词根，以及表示「系统研究」的后缀。"},"latinIntro":{"en":"The elements reached English through Latinized scientific forms: micro- from Greek mikros, biology from New Latin biologia, and -logy from Latin -logia. No single classical Latin word lies behind the compound.","cn":"这些成分经拉丁化的科学形式进入英语：micro- 来自希腊 mikros，biology 来自新拉丁 biologia，-logy 来自拉丁 -logia。这个复合词背后并没有单一的古典拉丁词。"},"items":[{"word":"microbiology","structure":"micro- + biology","meaning":"the science of small life","meaningCN":"研究微小生命的科学","example":"Microbiology has its own methods.","exampleCN":"微生物学有自己的方法。"},{"word":"microbiologist","structure":"microbiology + -ist (person)","meaning":"a practitioner of the science","meaningCN":"从事这门科学的从业者","example":"The microbiologist read the plate.","exampleCN":"微生物学家判读了培养皿。"},{"word":"microbiological","structure":"microbiology + -ical (relation)","meaning":"relating to the science","meaningCN":"与这门科学有关的","example":"Microbiological safety was checked.","exampleCN":"检查了微生物学安全。"},{"word":"microbiologically","structure":"microbiological + -ly (adverb)","meaning":"from a microbiological point of view","meaningCN":"从微生物学角度地","example":"The sample was microbiologically clean.","exampleCN":"该样本在微生物学上是洁净的。"},{"word":"biology","structure":"Greek bios + -logia","meaning":"the study of life","meaningCN":"研究生命的学科","example":"Biology split into many branches.","exampleCN":"生物学分成许多分支。"},{"word":"microbe","structure":"micro- + bios","meaning":"a small living thing","meaningCN":"微小的生物","example":"The microbe was cultured in agar.","exampleCN":"这种微生物在琼脂中培养。"},{"word":"microbial","structure":"microbion + -al","meaning":"of microbes","meaningCN":"微生物的","example":"Microbial mats cover the pool.","exampleCN":"微生物席覆盖着水塘。"},{"word":"microbiome","structure":"micro- + biome","meaning":"a whole microbial community","meaningCN":"完整的微生物群落","example":"The microbiome project sampled many sites.","exampleCN":"微生物组计划在许多地点取样。"},{"word":"bacteriology","structure":"bacterio- + -logy","meaning":"the study of bacteria only","meaningCN":"只研究细菌的学科","example":"Bacteriology predates microbiology.","exampleCN":"细菌学早于微生物学。"}],"latinEntries":[{"word":"biologia","structure":"biologia, -ae (f., New Latin, coined 1802)","meaning":"the study of life","meaningCN":"研究生命的学科"},{"word":"microbiologia","structure":"microbiologia, -ae (f., Modern Latin, 19th century)","meaning":"the study of microorganisms","meaningCN":"研究微生物的学科"}]}},{"word":"virus","ipa_uk":"/ˈvaɪrəs/","ipa_us":"/ˈvaɪrəs/","definition_zh":"病毒；一种比细菌更小、只能在活细胞内复制的感染因子","definition_en":"an infectious agent smaller than a bacterium that can reproduce only inside a living cell","core_image":"一个带有多面体外壳的微小颗粒，正把自己的一小段遗传物质注入宿主细胞","scene":"The virus passes from one host cell to another within hours.","sceneCN":"这里 virus 是「病毒」（第 1 个义项：只能在活细胞内复制的感染因子）；句意：这种病毒在数小时内就从一个宿主细胞传到另一个宿主细胞。图中可辨识物件：多面体外壳、伸出的尾部、被注入遗传物质的宿主细胞。","pos":[{"tag":"n.","zh":"病毒（可数名词，复数 viruses）；也可引申指计算机病毒或具有传染性的有害影响"}],"collocations":[{"phrase":"virus infection","zh":"病毒感染"},{"phrase":"virus strain","zh":"病毒毒株"},{"phrase":"virus replication","zh":"病毒复制"},{"phrase":"computer virus","zh":"计算机病毒"},{"phrase":"virus transmission","zh":"病毒传播"},{"phrase":"attenuated virus","zh":"减毒病毒"}],"forms":[{"label":"单数","form":"virus（一种病毒）"},{"label":"复数","form":"viruses（多种病毒；不用 viri）"},{"label":"形容词形式","form":"viral（病毒的）"},{"label":"学科名称","form":"virology（病毒学）"},{"label":"名词（颗粒）","form":"virion（病毒颗粒）"}],"derivatives":[{"word":"viruses","pos":"n.","zh":"病毒（复数）"},{"word":"viral","pos":"adj.","zh":"病毒的；由病毒引起的"},{"word":"virology","pos":"n.","zh":"病毒学"},{"word":"virologist","pos":"n.","zh":"病毒学家"},{"word":"virion","pos":"n.","zh":"病毒颗粒（完整的感染性颗粒）"},{"word":"antiviral","pos":"adj./n.","zh":"抗病毒的；抗病毒药物"},{"word":"virulent","pos":"adj.","zh":"毒力强的；恶性的（与 virus 同出拉丁语词根）"}],"senses":[{"no":"01","title":"The Biological Agent","titleCN":"病毒：只能在活细胞内复制","definition":"an infectious agent that consists of genetic material in a protein coat and reproduces only inside a host cell","definitionCN":"由遗传物质与蛋白质外壳构成、只能在宿主细胞内复制的感染因子","example":"The virus cannot multiply outside a living cell.","exampleCN":"这种病毒在活细胞之外无法增殖。","why":"A virus is defined by dependence: it has no metabolism of its own and must borrow a cell's machinery. That is why it is not called a cell, and why the old name for poison was reused for it.","whyCN":"病毒靠依赖性来定义：它没有自己的代谢，必须借用细胞的机器；因此它不被称为细胞，也因此那个古老的「毒」字被重新用来命名它。"},{"no":"02","title":"The Illness It Brings","titleCN":"病毒性疾病：口语中的「得了病毒」","definition":"an illness caused by a virus, especially in everyday speech","definitionCN":"由病毒引起的疾病，尤用于日常口语","example":"The child picked up a virus at school and stayed home for three days.","exampleCN":"孩子在学校染上了一种病毒，在家待了三天。","why":"Speakers often shorten 'a viral infection' to 'a virus'. The cause stands for the illness by metonymy, which is why one can catch a virus rather than merely encounter one.","whyCN":"说话人常把「病毒感染」简称为「病毒」；病因通过转喻代替了疾病，因此人可以说「染上病毒」，而不只是「遇到了病毒」。"},{"no":"03","title":"The Computer Virus","titleCN":"计算机病毒：会自我复制的恶意程序","definition":"a malicious computer program that copies itself into other files or systems","definitionCN":"能把自己复制进其他文件或系统的恶意程序","example":"A virus erased the archive before the backup ran.","exampleCN":"一个病毒在备份运行之前就删掉了档案。","why":"The computing sense, recorded by 1972, borrows the biological picture: a small piece of code that enters a host and makes it reproduce the code. The metaphor is structural, not merely decorative.","whyCN":"计算机义项于 1972 年有记录，它借用生物学画面：一小段代码进入宿主，并让宿主复制这段代码；这个隐喻是结构性的，不只是修辞装饰。"},{"no":"04","title":"A Contagious Idea","titleCN":"有传染性的观念：像病毒一样扩散","definition":"an idea, habit or mood that spreads rapidly from person to person","definitionCN":"在人与人之间迅速扩散的观念、习惯或情绪","example":"A virus of suspicion spread through the office after the leak.","exampleCN":"泄密之后，一种猜疑的病毒在办公室里蔓延。","why":"The extension treats a social thing as an agent that infects minds. It keeps the core features of S1: small, copying, host-dependent, hard to stop.","whyCN":"这一引申把社会性事物当作感染心智的因子；它保留了第 1 个义项的核心特征：微小、复制、依赖宿主、难以阻止。"},{"no":"05","title":"Poison, the Old Sense","titleCN":"毒物：拉丁语的本义","definition":"a poisonous or slimy substance, the word's original Latin sense","definitionCN":"有毒的或黏稠的物质，即该词在拉丁语中的本义","example":"In early medical writing a virus meant the thin discharge of a sore.","exampleCN":"在早期医学文献中，virus 指伤口流出的稀薄液体。","why":"Latin virus meant 'poison, sap, slimy liquid'. English borrowed it in the late fourteenth century for pus and venom, and only later narrowed it to the infectious agent.","whyCN":"拉丁语 virus 意为「毒、树液、黏稠液体」；英语在十四世纪末借入它，用来指脓与毒液，后来才收窄为感染因子。"},{"no":"06","title":"A Lab Strain","titleCN":"病毒毒株：实验室中的分离物","definition":"a particular isolate or strain of a virus kept for study or production","definitionCN":"为研究或生产而保存的某一病毒分离物或毒株","example":"The lab keeps the virus frozen at minus eighty degrees.","exampleCN":"实验室把这种病毒冻存在零下八十度。","why":"Once a virus is isolated, it becomes a named laboratory object. The sense shifts from the category to one sample of it, as strain does in microbiology.","whyCN":"病毒一旦被分离，就成为有名字的实验室对象；这个义项从类别转向其中的一份样本，正如微生物学中的「菌株」。"},{"no":"07","title":"A Vaccine Component","titleCN":"疫苗用的病毒：减毒或灭活","definition":"a weakened or killed virus used to prepare a vaccine","definitionCN":"用于制备疫苗的减毒或灭活病毒","example":"The vaccine uses a weakened virus to train the immune system.","exampleCN":"这种疫苗使用减毒病毒来训练免疫系统。","why":"Here the virus is an ingredient rather than a threat. The same agent is turned into a tool by removing or reducing its ability to replicate.","whyCN":"这里病毒是原料而不是威胁；通过去除或削弱其复制能力，同一个因子被变成了工具。"},{"no":"08","title":"A Corrupting Influence","titleCN":"祸根：侵蚀制度的有害因素","definition":"a harmful influence that spreads inside an institution or a society","definitionCN":"在制度或社会内部扩散的有害影响","example":"Corruption acted as a virus on the whole customs service.","exampleCN":"腐败像病毒一样侵蚀着整个海关系统。","why":"This is the darkest extension of the metaphor: the agent does not merely spread, it damages the host from within. It differs from S4 by stressing harm to an institution rather than contagion of a mood.","whyCN":"这是该隐喻最阴暗的引申：这个因子不只是扩散，还从内部损害宿主；它与第 4 个义项不同，强调的是对制度的伤害，而不是情绪的传染。"}],"etymology":{"intro":{"en":"Virus began as a Latin word for poison and slime. For five centuries English used it for pus, venom and contagion before science narrowed it, in the late nineteenth century, to the submicroscopic agent we now call a virus.","cn":"virus 原本是拉丁语中表示毒与黏液的词。英语用了五个多世纪来指脓、毒液与传染物，直到十九世纪末，科学才把它收窄为今天我们称为病毒的那种亚微观因子。"},"items":[{"era":"LATIN VIRUS","en":"Latin virus meant 'poison, poisonous liquid, sap of plants, slimy liquid, a potent juice'. It was a neuter noun of the second declension, and it named both venom and the sap that gives a plant its force.","cn":"拉丁语 virus 意为「毒、有毒液体、植物汁液、黏稠液体、有强效作用的汁」，是第二变格法的中性名词，既指毒液，也指赋予植物力量的汁液。"},{"era":"PROTO-ITALIC AND PIE","en":"The Latin word is traced to Proto-Italic *weis-o-(s-) 'poison', probably from a PIE root *ueis- perhaps meaning 'to melt away, to flow', used of foul fluids. This is a reconstructed root, and the semantic bridge to 'poison' is inferred rather than attested.","cn":"这个拉丁词被追溯到原始意大利语 *weis-o-(s-)「毒」，可能来自印欧词根 *ueis-（以上带星号的形式均为重构形式），或指「融化、流动」，用于恶臭液体。词根存疑：通向「毒」的意义桥梁属于推论，而非有直接书证。"},{"era":"ENGLISH, LATE 14TH CENTURY","en":"English borrowed virus in the late fourteenth century as a medical term for pus or a thin discharge from a wound. By the eighteenth century it could mean the contagion of a disease.","cn":"英语在十四世纪末借入 virus，作为指伤口脓液或稀薄分泌物的医学词；到十八世纪，它可以指疾病的传染物。"},{"era":"THE MODERN SENSE","en":"The scientific sense 'contagium of an infectious disease' is recorded from the 1790s. The use for disease-causing submicroscopic agents dates from the 1870s and was fixed when such agents began to be discovered in the late 1890s.","cn":"「传染病传染物」的科学义项记录于十八世纪九十年代；用于指致病的亚微观因子则始于十九世纪七十年代，并在十九世纪九十年代末这类因子被发现后固定下来。"},{"era":"COMPUTER VIRUS, 1972","en":"The computing sense is recorded by 1972. It maps the biological cycle, entry, copying and spread, onto executable code.","cn":"计算机义项于 1972 年有记录；它把生物学的循环——进入、复制、扩散——映射到可执行的代码上。"},{"era":"THE PLURAL","en":"The English plural is viruses, not the Latin viri. The Latin plural would suggest men, because vir means 'man', so English avoids a confusing form.","cn":"英语复数是 viruses，而不是拉丁语 viri；拉丁复数会让人想到「男人们」，因为 vir 意为「男人」，所以英语避开了这个易混形式。"}]},"similar":{"note":{"en":"The first group separates words from the same Latin root that have drifted apart. The second group holds agents and terms often mistaken for viruses.","cn":"第一组区分同一拉丁词根上已经分道扬镳的词；第二组是常被误当成病毒的因子与术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"virion","ipa":"/ˈvɪriən/","tag":"noun, the particle","definition":"One complete virus particle outside a cell: the genetic material plus its protein coat. Virus names the agent; virion names the thing you could count.","definitionCN":"细胞外的一个完整病毒颗粒，即遗传物质加蛋白质外壳；virus 命名的是因子，virion 命名的是可以计数的颗粒。"},{"word":"virulent","ipa":"/vɪˈruːlənt/","tag":"adjective, poisonous","definition":"Extremely harmful or infectious, from Latin virulentus 'poisonous'. It describes strength of harm, not the kind of agent.","definitionCN":"指极具危害性或传染性的，来自拉丁 virulentus「有毒的」；描述危害的强度，而不是因子种类。"},{"word":"viral","ipa":"/ˈvaɪrəl/","tag":"adjective","definition":"Of or caused by a virus. It is the adjective, never the noun; the noun remains virus.","definitionCN":"指病毒的或由病毒引起的；它是形容词，不能作名词，名词仍是 virus。"}]},{"heading":"NEAR-SYNONYMS","entries":[{"word":"pathogen","ipa":"/ˈpæθədʒən/","tag":"noun, disease agent","definition":"Any agent that causes disease, including bacteria and fungi. A virus is one kind of pathogen, but most pathogens are not viruses.","definitionCN":"任何引起疾病的因子，包括细菌与真菌；病毒是病原的一种，但大多数病原并非病毒。"},{"word":"microbe","ipa":"/ˈmaɪkrəʊb/","tag":"popular noun","definition":"A popular word for very small living things. Viruses are often called microbes in everyday speech, though they are not cells and many scientists exclude them.","definitionCN":"指极小生物的通俗词；日常语言常把病毒叫作微生物，尽管它不是细胞，许多科学家也把它排除在外。"},{"word":"bacterium","ipa":"/bækˈtɪəriəm/","tag":"noun, a cell","definition":"A single-celled organism that can live and divide on its own. It is larger than a virus and is treatable with antibiotics, which viruses are not.","definitionCN":"能独立生存分裂的单细胞生物；比病毒大，可用抗生素治疗，而病毒不能。"},{"word":"contagion","ipa":"/kənˈteɪdʒən/","tag":"noun, spread of disease","definition":"The spread of disease from one person to another, or the agent that spreads it. It names transmission, while virus names the agent.","definitionCN":"疾病在人与人之间的传播，或造成传播的因子；它命名传播过程，而 virus 命名因子。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin virus was 'poison'; the modern word narrowed the poison to an agent that copies itself in a cell.","cn":"拉丁语 virus 是「毒」；现代词把毒收窄为一种在细胞内自我复制的因子。"},{"en":"The plural is viruses, never viri, because viri would mean 'men' in Latin.","cn":"复数是 viruses，绝不是 viri，因为 viri 在拉丁语里意为「男人们」。"},{"en":"The family runs virus, viruses, viral, virology, virologist, virion, antiviral and virulent.","cn":"同族词包括 virus、viruses、viral、virology、virologist、virion、antiviral、virulent。"},{"en":"A virus is not a cell: it has no metabolism and must borrow one.","cn":"病毒不是细胞：它没有代谢，必须借用别人的。"},{"en":"The computing sense keeps the same script: entry, copying, spread, damage.","cn":"计算机义项沿用同一剧本：进入、复制、扩散、破坏。"}],"abstract":[{"en":"Picture a sealed capsule that cannot open itself and must persuade a cell to open it.","cn":"想象一个封死的胶囊，自己打不开，必须说服一个细胞替它打开。"},{"en":"Picture a rumour with a protein coat, copying itself in every ear it enters.","cn":"想象一则披着蛋白质外壳的传言，每进入一只耳朵就复制一次。"},{"en":"Picture a poison so patient that it waits for a host instead of acting at once.","cn":"想象一种极有耐心的毒，它不立刻发作，而是等待一个宿主。"}]},"examples":[{"en":"The virus was isolated from the patient's throat swab.","cn":"这种病毒从病人的咽拭子中被分离出来。"},{"en":"A virus disabled the hospital's records system for two days.","cn":"一个病毒让医院的记录系统瘫痪了两天。"},{"en":"The vaccine carries a weakened virus that cannot cause the disease.","cn":"这种疫苗携带一种不会引起该病的减毒病毒。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"拉丁 virus（毒、黏液）→ 一种极小的感染因子 → virus 病毒；计算机义沿用「进入宿主、自我复制」的画面","word":"virus"},"root":"拉丁 virus「毒、有毒液体、植物汁液、黏液」→ 原始意大利语 *weis-o-(s-)「毒」→ 可能来自印欧词根 *ueis-「融化、流动」（重构形式）→ 英语 virus（十四世纪末，指脓与毒液；十九世纪末收窄为病毒）。","sensesIntro":{"en":"Eight senses follow one small copier from Latin poison to a biological agent, an illness, a computer program, a contagious idea, a lab strain, a vaccine ingredient and a corrupting influence.","cn":"八个义项追随着同一个微小的复制者：从拉丁语的毒，到生物因子、疾病、计算机程序、传染性观念、实验室毒株、疫苗原料与侵蚀性影响。"},"semanticMap":{"core":{"en":"CORE IMAGE: a tiny capsule injecting its own code into a host cell.","cn":"核心意象：一个微小胶囊把自己的代码注入宿主细胞。"},"chain":["THE AGENT","THE ILLNESS","THE MACHINE","THE MIND","THE OLD POISON","THE LAB OBJECT"],"branches":[{"senses":"S1","en":"DEFINITION: the biological agent, defined by dependence on a host cell.","cn":"定义：生物因子，以依赖宿主细胞来定义。"},{"senses":"S2","en":"METONYMY: the cause stands for the illness in everyday speech.","cn":"转喻：日常语言里病因代替了疾病。"},{"senses":"S3 · S4 · S8","en":"METAPHOR: the same script runs in software, in minds and in institutions, with damage growing each time.","cn":"隐喻：同一剧本在软件、心智与制度中运行，破坏性逐步加重。"},{"senses":"S5","en":"HISTORY: the old sense of poison and slime survives in technical and archaic writing.","cn":"历史：毒与黏液的古义仍留在技术文字与古旧文字中。"},{"senses":"S6 · S7","en":"OBJECT AND TOOL: a strain is a virus you can store, and a vaccine virus is one you can use.","cn":"对象与工具：毒株是可以保存的病毒，疫苗病毒是可以使用的病毒。"}]},"affixes":{"intro":{"en":"Virus is a whole Latin noun rather than a built form. Its family grows by adding Greek and Latin endings that turn it into an adjective, a science, a particle and a drug.","cn":"virus 是一个完整的拉丁名词，而不是拼合形式；它的词族靠添加希腊与拉丁词尾生长，把它变成形容词、学科、颗粒与药物。"},"latinIntro":{"en":"Latin virus is the direct source. The adjective endings -al and -ic, the noun ending -ion and the Greek suffix -logy were attached later in English and Modern Latin.","cn":"拉丁 virus 是直接来源；形容词词尾 -al 与 -ic、名词词尾 -ion，以及希腊后缀 -logy，都是后来在英语与现代拉丁语中加上的。"},"items":[{"word":"virus","structure":"Latin virus (poison, slime)","meaning":"an infectious agent that copies itself in cells","meaningCN":"在细胞内自我复制的感染因子","example":"The virus entered through the nose.","exampleCN":"病毒通过鼻腔进入。"},{"word":"viruses","structure":"virus + English plural -es","meaning":"more than one virus","meaningCN":"不止一种病毒","example":"Several viruses circulate each winter.","exampleCN":"每年冬天都有几种病毒流行。"},{"word":"viral","structure":"virus + -al (relation)","meaning":"of or caused by a virus","meaningCN":"病毒的或由病毒引起的","example":"Viral shedding begins before symptoms.","exampleCN":"病毒排出在症状出现前就开始了。"},{"word":"virology","structure":"virus + -logy (study)","meaning":"the science of viruses","meaningCN":"研究病毒的学科","example":"Virology grew fast after 1935.","exampleCN":"病毒学在 1935 年之后迅速发展。"},{"word":"virologist","structure":"virology + -ist (person)","meaning":"a specialist in viruses","meaningCN":"研究病毒的专家","example":"The virologist mapped the genome.","exampleCN":"病毒学家绘制了基因组图谱。"},{"word":"virion","structure":"virus + -on (particle)","meaning":"one complete virus particle","meaningCN":"一个完整的病毒颗粒","example":"Each virion carries one copy of RNA.","exampleCN":"每个病毒颗粒携带一份 RNA。"},{"word":"antiviral","structure":"anti- (against) + viral","meaning":"acting against viruses","meaningCN":"对抗病毒的","example":"The antiviral drug blocks entry.","exampleCN":"这种抗病毒药物阻断进入。"},{"word":"virulent","structure":"Latin virulentus (poisonous) + -ent","meaning":"strongly harmful","meaningCN":"危害性强的","example":"A virulent strain filled the ward.","exampleCN":"一种毒力强的毒株住满了病房。"}],"latinEntries":[{"word":"virus","structure":"virus, -i (n., second declension)","meaning":"poison, venom, sap, slimy liquid","meaningCN":"毒；毒液；汁液；黏液"},{"word":"virulentus","structure":"virulentus, -a, -um (adj., from virus)","meaning":"full of poison, poisonous","meaningCN":"充满毒的；有毒的"}]}},{"word":"viral","ipa_uk":"/ˈvaɪrəl/","ipa_us":"/ˈvaɪrəl/","definition_zh":"病毒的；由病毒引起的；像病毒一样迅速传播的","definition_en":"of, caused by, or spreading like a virus","core_image":"一个人把手机递给旁边的人，屏幕上的同一条内容在人群里一圈圈亮起","scene":"The viral infection cleared after two weeks of rest.","sceneCN":"这里 viral 是「由病毒引起的」（第 2 个义项：病因来自病毒）；句意：休息两周后，这场病毒性感染消退了。图中可辨识物件：病床、病历上的病毒标记、逐渐恢复的体温曲线。","pos":[{"tag":"adj.","zh":"病毒的；由病毒引起的；像病毒一样迅速传播的（由名词 virus 加 -al 构成）"}],"collocations":[{"phrase":"viral infection","zh":"病毒感染"},{"phrase":"viral load","zh":"病毒载量"},{"phrase":"viral replication","zh":"病毒复制"},{"phrase":"viral marketing","zh":"病毒式营销"},{"phrase":"viral video","zh":"爆款视频；病毒式传播的视频"},{"phrase":"viral shedding","zh":"病毒排出"}],"forms":[{"label":"原级（形容词）","form":"viral（病毒的）"},{"label":"副词形式","form":"virally（以病毒方式地；经病毒传播地）"},{"label":"名词单数","form":"virus（病毒）"},{"label":"名词复数","form":"viruses（病毒，复数）"},{"label":"相关抽象名词","form":"virality（病毒式传播性；传播力）"}],"derivatives":[{"word":"virus","pos":"n.","zh":"病毒"},{"word":"viruses","pos":"n.","zh":"病毒（复数）"},{"word":"virally","pos":"adv.","zh":"以病毒方式地；经病毒传播地"},{"word":"virality","pos":"n.","zh":"病毒式传播性；传播力（网络内容用语）"},{"word":"virology","pos":"n.","zh":"病毒学"},{"word":"antiviral","pos":"adj./n.","zh":"抗病毒的；抗病毒药物"},{"word":"viralize","pos":"v.","zh":"使病毒式传播（近年口语用法）"}],"senses":[{"no":"01","title":"Of Viruses","titleCN":"病毒的：与病毒这一类相关","definition":"relating to viruses as a class of agents","definitionCN":"与病毒这一类因子有关的","example":"Viral structures vary widely from one family to another.","exampleCN":"不同科的病毒结构差异很大。","why":"The suffix -al makes a relational adjective from the noun virus: 'having to do with viruses'. This is the bare sense from which the others narrow or extend.","whyCN":"后缀 -al 把名词 virus 变成关系形容词，意为「与病毒有关」；这是最朴素的义项，其他义项都由它收窄或引申而来。"},{"no":"02","title":"Caused by a Virus","titleCN":"病毒引起的：病因来自病毒","definition":"caused by a virus rather than by bacteria or another agent","definitionCN":"由病毒而非细菌或其他因子引起的","example":"The doctor said the sore throat was viral and gave no antibiotic.","exampleCN":"医生说咽喉痛是病毒引起的，没有开抗生素。","why":"Here the adjective answers 'what caused it'. The contrast with bacterial is clinically decisive, because antibiotics work on bacteria and not on viruses.","whyCN":"这里形容词回答的是「什么引起的」；与 bacterial 的对立在临床上具有决定性，因为抗生素作用于细菌而非病毒。"},{"no":"03","title":"A Viral Infection","titleCN":"病毒感染：疾病过程的名称","definition":"an infection produced by a virus that has entered the body","definitionCN":"病毒进入人体后造成的感染","example":"A viral infection spread through the dormitory in a week.","exampleCN":"一场病毒感染在一周内传遍了宿舍。","why":"Infection names the process, and the adjective names its cause. The phrase is the neutral medical label for illnesses ranging from a cold to hepatitis.","whyCN":"infection 命名过程，形容词命名病因；这个短语是从感冒到肝炎等一系列疾病的中性医学标签。"},{"no":"04","title":"Spreading Like a Virus","titleCN":"病毒式传播的：在人群中迅速扩散","definition":"spreading very quickly from person to person, as if by infection","definitionCN":"像感染一样在人与人之间迅速扩散的","example":"The campaign went viral before the company had planned a second phase.","exampleCN":"这场活动病毒式传播开来，公司还没来得及规划第二阶段。","why":"The internet sense, recorded by 1999, borrows the speed and person-to-person path of infection. The adjective now describes distribution rather than disease.","whyCN":"网络义项于 1999 年有记录，它借用了感染的传播速度与人对人的路径；这个形容词现在描述的是分发方式，而不是疾病。"},{"no":"05","title":"A Viral Video","titleCN":"爆款视频：被大量转发的作品","definition":"a piece of content that has been shared so widely that it becomes famous","definitionCN":"被广泛转发而成名的内容作品","example":"The viral video was a ten-second clip of a cat opening a door.","exampleCN":"那段爆款视频只有十秒，是一只手开门的猫。","why":"Here the adjective modifies the object rather than the process: the clip itself is called viral because it has completed the spread. The sense is a result label, not a cause label.","whyCN":"这里形容词修饰对象而不是过程：这段短片被称为爆款，是因为它已经完成了扩散；该义项是结果标签，而不是原因标签。"},{"no":"06","title":"Viral Load","titleCN":"病毒载量：体内病毒的数量","definition":"the amount of virus present in a patient's blood or other fluid","definitionCN":"病人血液或其他体液中存在的病毒数量","example":"The viral load fell below detection after six months of treatment.","exampleCN":"治疗六个月后，病毒载量降到检测不到的水平。","why":"Load is a measured quantity; viral specifies what is being counted. The phrase belongs to clinical monitoring, where the number guides treatment.","whyCN":"load 是被测量的量，viral 指明所数的是什么；这个短语属于临床监测，数字用来指导治疗。"},{"no":"07","title":"Viral Replication","titleCN":"病毒复制：借用细胞机器增殖","definition":"the process by which a virus copies its genome and assembles new particles","definitionCN":"病毒复制基因组并组装新颗粒的过程","example":"Viral replication stopped when the enzyme was blocked.","exampleCN":"酶被阻断后，病毒复制停止了。","why":"Replication is the defining activity of a virus, the step that requires a host. The adjective marks whose replication is meant, since cells replicate too.","whyCN":"复制是病毒的决定性活动，也是必须依赖宿主的那一步；形容词指明是谁在复制，因为细胞也会复制。"},{"no":"08","title":"Viral Shedding","titleCN":"病毒排出：把病毒传给他人的环节","definition":"the release of virus particles from an infected person into the environment","definitionCN":"感染者把病毒颗粒释放到环境中的过程","example":"Viral shedding can begin before the first symptom appears.","exampleCN":"病毒排出可能在第一个症状出现之前就开始。","why":"Shedding is the exit step that makes transmission possible. The adjective attaches the act to the virus rather than to the host's cells, which is why it is not called bacterial shedding in this context.","whyCN":"排出是使传播成为可能的那一步「离开」；形容词把这个动作归属于病毒，而不是宿主的细胞，因此这里不会说细菌排出。"}],"etymology":{"intro":{"en":"Viral is a twentieth-century adjective made from virus by adding -al. Its medical sense and its internet sense are only half a century apart, and the second grew directly out of the first.","cn":"viral 是二十世纪由 virus 加 -al 构成的形容词；它的医学义与网络义只相隔半个世纪，而后者正是从前者直接生长出来的。"},"items":[{"era":"LATIN VIRUS","en":"Latin virus meant 'poison, venom, sap, slimy liquid'. English took the noun in the late fourteenth century for pus and contagion.","cn":"拉丁语 virus 意为「毒、毒液、汁液、黏液」；英语在十四世纪末借入该名词，用来指脓与传染物。"},{"era":"VIRAL, 1944","en":"Viral is recorded from 1944, formed from virus plus the adjective ending -al. It entered use just as virology was becoming a distinct discipline.","cn":"viral 记录于 1944 年，由 virus 加形容词词尾 -al 构成；它出现时，病毒学正逐渐成为一门独立学科。"},{"era":"THE MEDICAL PAIR","en":"After antibiotics became common, medicine needed a quick way to say 'not bacterial'. Viral supplied it, and the pair bacterial versus viral became a standard diagnostic distinction.","cn":"抗生素普及之后，医学需要一个快速表达「不是细菌」的词，viral 正好补上；bacterial 与 viral 的成对用法成为标准的诊断区分。"},{"era":"THE INTERNET SENSE","en":"The sense 'suddenly widely popular through internet sharing' is recorded by 1999, first in marketing. It rests on the same person-to-person path as an infection, not on any technical property of the content.","cn":"「经网络分享而突然广泛流行」这一义项记录于 1999 年，最早见于营销领域；它依据的是与感染相同的人对人路径，而不是内容的技术属性。"},{"era":"VIRALITY AND VIRALIZE","en":"Virality and viralize followed in the twenty-first century as the marketing sense matured. These are new English formations, not Latin words.","cn":"随着营销义成熟，virality 与 viralize 在二十一世纪相继出现；这些是英语新造形式，不是拉丁词。"},{"era":"ONE WORD, TWO REGISTERS","en":"The same adjective now appears in a clinical chart and in a social-media report. Context, not etymology, decides whether it means 'caused by a virus' or 'spread by sharing'.","cn":"同一个形容词现在既出现在病历上，也出现在社交媒体报告里；决定它表示「由病毒引起」还是「靠分享传播」的，是语境而不是词源。"}]},"similar":{"note":{"en":"The first group separates the adjective from its noun and adverb. The second group holds terms that describe cause, spread or popularity but are not interchangeable with viral.","cn":"第一组区分这个形容词与它的名词、副词；第二组是描述病因、传播或流行度、但不能与 viral 互换的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"virus","ipa":"/ˈvaɪrəs/","tag":"noun","definition":"The agent itself. Viral is the adjective; using virus as an adjective is non-standard in careful writing.","definitionCN":"指病毒本身；viral 才是形容词，在严谨写作中把 virus 当形容词用不合规范。"},{"word":"virally","ipa":"/ˈvaɪrəli/","tag":"adverb","definition":"The adverb, meaning 'by a virus' or 'through viral spread'. It modifies a verb, as in 'the clip spread virally'.","definitionCN":"副词，意为「经病毒地」或「以病毒式传播地」；修饰动词，如「短片病毒式地传播」。"},{"word":"virality","ipa":"/vaɪˈræləti/","tag":"noun, the quality","definition":"The quality of spreading quickly through sharing. It is a modern marketing noun, not a medical one.","definitionCN":"指通过分享迅速扩散的性质；这是现代营销名词，不是医学名词。"}]},{"heading":"NEAR-SYNONYMS","entries":[{"word":"bacterial","ipa":"/bækˈtɪəriəl/","tag":"adjective, contrasting cause","definition":"Caused by bacteria. It is the clinical opposite of viral and decides whether antibiotics can help.","definitionCN":"由细菌引起的；它是 viral 的临床对立面，决定抗生素是否有用。"},{"word":"infectious","ipa":"/ɪnˈfekʃəs/","tag":"adjective, transmissible","definition":"Capable of being transmitted to others. It names transmissibility, not the kind of agent, so a bacterial disease can also be infectious.","definitionCN":"指能够传染给他人的；命名的是可传播性，而不是因子种类，因此细菌性疾病也可以是 infectious。"},{"word":"contagious","ipa":"/kənˈteɪdʒəs/","tag":"adjective, easily spread","definition":"Easily spread from person to person, especially by contact. It stresses ease of spread and is often used of behaviour as well as disease.","definitionCN":"指容易在人与人之间传播的，尤指经接触；强调传播的容易程度，也常用于形容行为。"},{"word":"epidemic","ipa":"/ɪˈpemɪk/","tag":"adjective/noun, wide spread","definition":"Affecting many people at once in a region. It describes the scale of an outbreak, not its cause.","definitionCN":"指在一地区同时影响许多人的；描述疫情规模，而不是病因。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"virus + -al: 'having to do with a virus', and by extension 'spreading like one'.","cn":"virus + -al：意为「与病毒有关」，引申为「像病毒一样传播」。"},{"en":"Bacterial answers antibiotics; viral does not. The pair is a clinical fork in the road.","cn":"细菌性可用抗生素，病毒性不行；这一对词是临床上的一条分岔路。"},{"en":"The internet sense arrived in 1999 and keeps the person-to-person path of infection.","cn":"网络义项于 1999 年出现，保留了感染的人对人路径。"},{"en":"The family runs virus, viruses, viral, virally, virality, virology and antiviral.","cn":"同族词包括 virus、viruses、viral、virally、virality、virology、antiviral。"},{"en":"Viral load counts virus in the body; viral shedding counts virus leaving it.","cn":"病毒载量数的是体内的病毒；病毒排出数的是离开身体的病毒。"}],"abstract":[{"en":"Picture a clip that behaves like a cough: one screen, then ten, then everyone.","cn":"想象一段短片像咳嗽一样行事：一块屏幕，然后十块，然后所有人。"},{"en":"Picture a chart line that falls as the medicine works, labelled with one adjective.","cn":"想象一条随药物起效而下降的曲线，旁边只标着一个形容词。"},{"en":"Picture a crowd passing a single sentence from hand to hand until it is famous.","cn":"想象人群把一句话一手传一手，直到它变得人尽皆知。"}]},"examples":[{"en":"The viral outbreak closed the school for a week.","cn":"这场病毒性疫情使学校停课一周。"},{"en":"Her short film went viral within a single night.","cn":"她的短片在一夜之间爆红。"},{"en":"Viral replication depends on enzymes supplied by the host.","cn":"病毒复制依赖宿主提供的酶。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"virus（病毒）+ -al（与……有关的）→ 与病毒有关的 → viral 病毒的；网络义引申为「像病毒一样传播的」","word":"viral"},"root":"拉丁 virus「毒、黏液」→ 英语 virus（十四世纪末）→ viral（virus + -al，1944 年）；网络义「病毒式传播」1999 年出现。","sensesIntro":{"en":"Eight senses split into two families: five medical senses about cause, infection, quantity, replication and release, and three extension senses about rapid spread and popularity.","cn":"八个义项分成两族：五个医学义项谈病因、感染、数量、复制与排出，三个引申义项谈迅速扩散与流行。"},"semanticMap":{"core":{"en":"CORE IMAGE: one screen passing the same content to another screen, as a cough passes to another chest.","cn":"核心意象：一块屏幕把同一内容传给另一块屏幕，正如咳嗽传给另一副胸膛。"},"chain":["OF THE AGENT","CAUSED BY IT","THE INFECTION","COUNTED IN THE BODY","SPREADING FAST","BECOMING FAMOUS"],"branches":[{"senses":"S1","en":"RELATION: the bare adjective of virus, with no claim about cause or spread.","cn":"关联：最朴素的病毒形容词，不涉及病因或传播。"},{"senses":"S2 · S3","en":"MEDICAL CAUSE: the adjective answers what caused the illness and names the process.","cn":"医学病因：形容词回答疾病由何引起，并命名该过程。"},{"senses":"S6 · S7 · S8","en":"MEASURE AND MECHANISM: load counts the virus, replication copies it, shedding releases it.","cn":"测量与机制：载量在数病毒，复制在抄病毒，排出在放病毒。"},{"senses":"S4","en":"METAPHOR OF SPREAD: the person-to-person path is borrowed for ideas and content.","cn":"传播隐喻：人对人的路径被借用于观念与内容。"},{"senses":"S5","en":"RESULT: an object becomes viral once the spread is complete, so the adjective labels an outcome.","cn":"结果：扩散完成后对象才成为爆款，因此形容词标的是一个结果。"}]},"affixes":{"intro":{"en":"Viral is a Latin noun with a Latin adjective ending. Its modern derivatives are English or Neo-Latin additions, which is why the family contains both old and very new words.","cn":"viral 是拉丁名词加拉丁形容词词尾；它的现代派生词是英语或新拉丁语的附加物，因此这个词族里既有很旧的词，也有很新的词。"},"latinIntro":{"en":"Latin supplied virus and the adjectival pattern -alis. It did not supply virality or viralize, which are modern English formations from the adjective.","cn":"拉丁语提供了 virus 与形容词模式 -alis；它没有提供 virality 或 viralize，那两个词是由该形容词构成的现代英语新词。"},"items":[{"word":"viral","structure":"virus + -al (relation)","meaning":"of or caused by a virus","meaningCN":"病毒的或由病毒引起的","example":"Viral infection needs no antibiotic.","exampleCN":"病毒感染不需要抗生素。"},{"word":"virus","structure":"Latin virus (poison)","meaning":"the infectious agent","meaningCN":"感染因子","example":"The virus was sequenced.","exampleCN":"该病毒已被测序。"},{"word":"viruses","structure":"virus + English plural -es","meaning":"several kinds of virus","meaningCN":"多种病毒","example":"Viruses mutate as they copy.","exampleCN":"病毒在复制时发生突变。"},{"word":"virally","structure":"viral + -ly (adverb)","meaning":"through viral spread","meaningCN":"以病毒式传播地","example":"The post spread virally.","exampleCN":"该帖子病毒式传播开来。"},{"word":"virality","structure":"viral + -ity (quality noun)","meaning":"the capacity to spread widely","meaningCN":"广泛传播的能力","example":"The agency measured virality.","exampleCN":"该机构衡量了传播力。"},{"word":"viralize","structure":"viral + -ize (make)","meaning":"to make something spread widely","meaningCN":"使某物广泛传播","example":"The team tried to viralize the clip.","exampleCN":"团队试图让短片病毒式传播。"},{"word":"virology","structure":"virus + -logy (study)","meaning":"the science of viruses","meaningCN":"研究病毒的学科","example":"Virology tracks new variants.","exampleCN":"病毒学追踪新变种。"},{"word":"antiviral","structure":"anti- + viral","meaning":"working against viruses","meaningCN":"对抗病毒的","example":"Antiviral treatment began at once.","exampleCN":"抗病毒治疗立即开始。"}],"latinEntries":[{"word":"virus","structure":"virus, -i (n., second declension)","meaning":"poison, venom, slimy liquid","meaningCN":"毒；毒液；黏液"},{"word":"viralis","structure":"viralis, -e (adj., Modern Latin, from virus)","meaning":"of a virus","meaningCN":"病毒的"}]}},{"word":"virology","ipa_uk":"/vaɪˈrɒlədʒi/","ipa_us":"/vaɪˈrɑːlədʒi/","definition_zh":"病毒学；研究病毒及其复制、传播与致病的学科","definition_en":"the science that studies viruses, their replication, spread, and effects","core_image":"高等级实验室里成排的密封操作箱，屏幕上显示着一段段病毒基因组序列","scene":"The department of virology traced the outbreak to a single bat colony.","sceneCN":"这里 virology 是「病毒学」（第 2 个义项：作为院系建制）；句意：病毒学系把这次疫情追溯到一个蝙蝠群落。图中可辨识物件：密封操作箱、基因序列屏幕、采样记录。","pos":[{"tag":"n.","zh":"病毒学（不可数名词）；指学科或某一分支，也可指院系建制"}],"collocations":[{"phrase":"clinical virology","zh":"临床病毒学"},{"phrase":"molecular virology","zh":"分子病毒学"},{"phrase":"diagnostic virology","zh":"诊断病毒学"},{"phrase":"plant virology","zh":"植物病毒学"},{"phrase":"virology laboratory","zh":"病毒学实验室"},{"phrase":"virology department","zh":"病毒学系"}],"forms":[{"label":"学科名词","form":"virology（病毒学，不可数）"},{"label":"从业者","form":"virologist（病毒学家）"},{"label":"形容词形式","form":"virological（病毒学的）"},{"label":"副词形式","form":"virologically（从病毒学角度地）"},{"label":"研究对象","form":"virus（病毒）"}],"derivatives":[{"word":"virologist","pos":"n.","zh":"病毒学家"},{"word":"virological","pos":"adj.","zh":"病毒学的；病毒学方法的"},{"word":"virologically","pos":"adv.","zh":"从病毒学角度地"},{"word":"virus","pos":"n.","zh":"病毒"},{"word":"viral","pos":"adj.","zh":"病毒的"},{"word":"virion","pos":"n.","zh":"病毒颗粒"},{"word":"antiviral","pos":"adj./n.","zh":"抗病毒的；抗病毒药物"}],"senses":[{"no":"01","title":"The Science of Viruses","titleCN":"病毒学：研究病毒的科学","definition":"the branch of biology that studies viruses","definitionCN":"生物学中研究病毒的分支","example":"Virology asks how a particle with no cell of its own can copy itself.","exampleCN":"病毒学追问一个没有自己细胞的颗粒如何复制自身。","why":"Virology joins virus to -logy, the Greek suffix for a disciplined study. Its object is unusual because viruses are not cells, so the science sits at the border of biology.","whyCN":"virology 把 virus 与表示系统研究的希腊后缀 -logy 结合；它的对象很特殊，因为病毒不是细胞，所以这门科学处在生物学的边界上。"},{"no":"02","title":"A Discipline and a Department","titleCN":"学科与院系：作为建制单位","definition":"the academic field or institutional unit devoted to viruses","definitionCN":"专门研究病毒的学术领域或建制单位","example":"The virology department moved into the new safety building.","exampleCN":"病毒学系搬进了新的安全大楼。","why":"A field becomes visible when it has a department, a budget and a building. The uncountable name can therefore stand for the institution that practises it.","whyCN":"一个领域有了院系、预算与大楼，才变得可见；因此这个不可数名词可以代指从事它的建制单位。"},{"no":"03","title":"Clinical Virology","titleCN":"临床病毒学：为诊断与治疗服务","definition":"the branch that identifies viruses causing human disease","definitionCN":"鉴定引起人类疾病的病毒的分支","example":"Clinical virology reported the virus within four hours.","exampleCN":"临床病毒学在四小时内报告了该病毒。","why":"In the hospital the science narrows to speed and accuracy: which virus, how much, and which drug. The adjective clinical marks that practical setting.","whyCN":"在医院里，这门科学收窄为速度与准确度：是哪种病毒、有多少、用哪种药；形容词 clinical 标出这一实用场景。"},{"no":"04","title":"Molecular Virology","titleCN":"分子病毒学：研究基因与蛋白机制","definition":"the branch that studies viral genomes, proteins and replication at the molecular level","definitionCN":"在分子层面研究病毒基因组、蛋白质与复制的分支","example":"Molecular virology explained how the virus enters the cell.","exampleCN":"分子病毒学解释了这种病毒如何进入细胞。","why":"The adjective molecular names the level of analysis, not the setting. The same virus can be studied clinically at the bedside or molecularly at the bench.","whyCN":"形容词 molecular 命名的是分析层次，而不是场景；同一种病毒既可在床边做临床研究，也可在实验台上做分子研究。"},{"no":"05","title":"Diagnostic Virology","titleCN":"诊断病毒学：检测与分型","definition":"the branch concerned with detecting and typing viruses in samples","definitionCN":"负责在样本中检测病毒并分型的分支","example":"Diagnostic virology turned the swab into a typed result.","exampleCN":"诊断病毒学把拭子变成了分型结果。","why":"Diagnosis is a distinct job: it does not explain mechanism or treat disease, it answers 'which agent is here'. The adjective isolates that function.","whyCN":"诊断是一项独立工作：它不解释机制，也不治疗疾病，只回答「这里是什么因子」；形容词把这一职能单独标出。"},{"no":"06","title":"Plant and Environmental Virology","titleCN":"植物与环境病毒学：非医学对象","definition":"the branches that study viruses of plants or of ecosystems","definitionCN":"研究植物病毒或生态系统中病毒的分支","example":"Plant virology saved the orchard by identifying the mosaic virus.","exampleCN":"植物病毒学通过鉴定花叶病毒挽救了果园。","why":"Viruses infect far more than humans. The adjective before the field name marks which host group or setting is being studied, and the methods change accordingly.","whyCN":"病毒感染的对象远不止人类；学科名前的形容词标出所研究的宿主群或场景，方法也随之改变。"},{"no":"07","title":"Laboratory Methods","titleCN":"实验室方法：培养、测序与隔离","definition":"the practical techniques of culturing, sequencing and handling viruses","definitionCN":"培养、测序与操作病毒的实用技术","example":"The course teaches the virology of safe sample handling first.","exampleCN":"这门课首先教授安全处理样本的病毒学操作。","why":"Because viruses need living cells, their laboratory handling is unusually demanding. The name can denote that body of technique, not only the theoretical field.","whyCN":"由于病毒需要活细胞，实验室操作的要求异常高；这个名称可以指这套技术本身，而不只是理论领域。"},{"no":"08","title":"The Viruses of a Sample","titleCN":"样本的病毒组成：转喻用法","definition":"the viral content or profile found in a sample or a site","definitionCN":"某样本或某地点检出的病毒组成或图谱","example":"The virology of the sewage sample matched the clinical cases.","exampleCN":"污水样本的病毒组成与临床病例相符。","why":"Specialists say the virology of a sample when they mean the viruses in it. The discipline name stands for its object, the same metonymy seen in microbiology.","whyCN":"专家说某样本的「病毒学」，实际指的是其中的病毒；学科名代替了它的对象，这与微生物学中的转喻相同。"}],"etymology":{"intro":{"en":"Virology is a twentieth-century compound: virus plus -logy, the Greek suffix for a field of study. It became a named science only after viruses could be seen and grown.","cn":"virology 是二十世纪的复合词：virus 加 -logy，即表示研究领域的希腊后缀。直到病毒能被看见、能被培养，它才成为一门有名字的科学。"},"items":[{"era":"LATIN VIRUS","en":"Latin virus meant 'poison, venom, sap, slimy liquid'. English borrowed it in the late fourteenth century, and the modern sense of a submicroscopic agent was fixed in the 1890s.","cn":"拉丁语 virus 意为「毒、毒液、汁液、黏液」；英语于十四世纪末借入，而「亚微观感染因子」的现代义在十九世纪九十年代固定下来。"},{"era":"GREEK -LOGIA","en":"Greek -logia came from -log-, the combining form of legein 'to speak, tell', from a root meaning 'to gather, pick out'. The suffix names a disciplined way of speaking about a subject, hence a science.","cn":"希腊 -logia 来自 -log-，即 legein「说、讲述」的组合形式，其词根意为「收集、拣选」；该后缀命名关于某主题的一套有纪律的论述方式，因此指一门科学。"},{"era":"VIROLOGY, 1935","en":"Virology is recorded from 1935, formed from the combining form of virus plus -logy. It arrived after the tobacco mosaic virus and other agents had been isolated and shown to be filterable.","cn":"virology 记录于 1935 年，由 virus 的组合形式加 -logy 构成；它出现于烟草花叶病毒等因子已被分离、并被证明可通过滤器之后。"},{"era":"THE PRACTITIONER","en":"Virologist is recorded from 1946, eleven years later. The delay is typical: a science is named before the people who practise it are named.","cn":"virologist 记录于 1946 年，晚了十一年；这种滞后很典型：学科先获得名字，从业者随后才有称呼。"},{"era":"THE ELECTRON MICROSCOPE","en":"Viruses are smaller than the wavelength of visible light, so they became visible only with the electron microscope. That instrument turned virology from inference into observation.","cn":"病毒小于可见光的波长，因此只有电子显微镜才能让它们显现；这件仪器把病毒学从推断变成了观察。"},{"era":"MODERN BRANCHES","en":"Molecular virology, diagnostic virology and clinical virology split off as methods matured. Each branch name adds a scope adjective to the same Greek suffix.","cn":"随着方法成熟，分子病毒学、诊断病毒学与临床病毒学相继分出；每个分支名都是在同一个希腊后缀前加一个限定范围的形容词。"}]},"similar":{"note":{"en":"The first group separates the field from its practitioner and adjective. The second group holds neighbouring sciences whose objects differ by kind.","cn":"第一组区分学科本身与其从业者、形容词；第二组是研究对象按类别相邻的科学。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"virologist","ipa":"/vaɪˈrɒlədʒɪst/","tag":"noun, person","definition":"A person who practises virology. The ending -ist marks the practitioner rather than the field.","definitionCN":"从事病毒学的人；词尾 -ist 标记从业者，而不是学科。"},{"word":"virological","ipa":"/vaɪrəˈlɒdʒɪkəl/","tag":"adjective","definition":"Relating to virology or its methods, as in virological testing. It describes the discipline's procedures, not the virus itself.","definitionCN":"与病毒学或其方法有关的，如病毒学检测；描述的是学科程序，而不是病毒本身。"},{"word":"viral","ipa":"/ˈvaɪrəl/","tag":"adjective, of viruses","definition":"Of or caused by a virus. It is object-level, while virological is discipline-level.","definitionCN":"指病毒的或由病毒引起的；它是对象层面的形容词，而 virological 是学科层面的。"}]},{"heading":"NEAR-SYNONYMS","entries":[{"word":"microbiology","ipa":"/ˌmaɪkrəʊbaɪˈɒlədʒi/","tag":"noun, wider field","definition":"The study of microorganisms. It often includes viruses by convention, though viruses are not cells, so the two fields overlap at the border.","definitionCN":"研究微生物的学科；按惯例常把病毒算在内，但病毒不是细胞，因此两个领域在边界处重叠。"},{"word":"bacteriology","ipa":"/bækˌtɪəriˈɒlədʒi/","tag":"noun, bacteria only","definition":"The study of bacteria, which are cells and can be treated with antibiotics. It is not a branch of virology.","definitionCN":"研究细菌的学科；细菌是细胞，可用抗生素治疗，不属病毒学的分支。"},{"word":"epidemiology","ipa":"/ˌepɪdiːmiˈɒlədʒi/","tag":"noun, spread in populations","definition":"The study of how diseases spread through populations. It asks who, where and when, while virology asks what the agent is.","definitionCN":"研究疾病在人群中如何传播的学科；它问的是谁、何处、何时，而病毒学问的是因子是什么。"},{"word":"immunology","ipa":"/ˌɪmjʊˈnɒlədʒi/","tag":"noun, host defence","definition":"The study of the immune system. It studies the host's response to viruses rather than the viruses themselves.","definitionCN":"研究免疫系统的学科；它研究宿主对病毒的反应，而不是病毒本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"virus + -logy: the study of viruses, a science named in 1935.","cn":"virus + -logy：研究病毒的学问，这门学科于 1935 年得名。"},{"en":"The practitioner followed in 1946: first the field, then the virologist.","cn":"从业者的称呼 1946 年才出现：先有领域，后有病毒学家。"},{"en":"The family runs virology, virologist, virological, virologically, virus, viral and virion.","cn":"同族词包括 virology、virologist、virological、virologically、virus、viral、virion。"},{"en":"Scope adjectives mark the branch: clinical, molecular, diagnostic, plant and environmental virology.","cn":"限定形容词标出分支：临床、分子、诊断、植物与环境病毒学。"},{"en":"Viruses are not cells, so virology sits at the edge of biology and often partners with immunology.","cn":"病毒不是细胞，因此病毒学处在生物学边缘，并常与免疫学合作。"}],"abstract":[{"en":"Picture a sealed box where a thing smaller than light is grown on purpose.","cn":"想象一个密封箱，里面故意培养着一种比光波长还小的东西。"},{"en":"Picture a genome printed as letters on a screen, and a scientist reading it like a map.","cn":"想象一份基因组像字母一样印在屏幕上，科学家像读地图一样读它。"},{"en":"Picture a bat colony and a hospital ward linked by one line on a map.","cn":"想象地图上一条线，把一个蝙蝠群落和一间医院病房连起来。"}]},"examples":[{"en":"Virology has identified the family to which the new agent belongs.","cn":"病毒学已经鉴定出这种新因子所属的科。"},{"en":"She moved from clinical medicine into virology.","cn":"她从临床医学转入病毒学。"},{"en":"Molecular virology explained why the drug no longer worked.","cn":"分子病毒学解释了为什么这种药不再有效。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"virus（病毒）+ -logy（……学）→ 研究病毒的学科 → virology 病毒学","word":"virology"},"root":"拉丁 virus「毒、黏液」→ 英语 virus；希腊 -logia「研究、论述」→ -logy；1935 年英语合成 virus + -logy = virology；virologist 出现于 1946 年。","sensesIntro":{"en":"Eight senses move from the science itself to its institution, clinical, molecular, diagnostic, botanical and practical branches, and finally to its metonymic use for a sample's viral content.","cn":"八个义项从这门科学本身，走向它的建制、临床、分子、诊断、植物与实践分支，最后落到用学科名转指样本中的病毒组成。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sealed cabinet and a genome on screen, with a sample log beside them.","cn":"核心意象：密封操作箱与屏幕上的基因组，旁边放着样本记录。"},"chain":["THE SCIENCE","THE DEPARTMENT","THE CLINIC","THE MOLECULE","THE DIAGNOSIS","THE OTHER HOSTS"],"branches":[{"senses":"S1","en":"KNOWLEDGE: the organised study of viruses is the root sense.","cn":"知识：对病毒的系统研究是根义。"},{"senses":"S2","en":"INSTITUTION: a department with a building makes the field visible as an organisation.","cn":"建制：有楼有人的院系让这个领域作为组织变得可见。"},{"senses":"S3 · S5","en":"CLINICAL PATH: the clinic identifies the agent, and diagnostics types it for treatment.","cn":"临床路径：诊所鉴定因子，诊断部门为治疗而分型。"},{"senses":"S4 · S7","en":"MECHANISM AND HANDS: molecular work explains entry and copying, while laboratory methods make the work safe.","cn":"机制与双手：分子工作解释进入与复制，实验室方法让工作安全。"},{"senses":"S6 · S8","en":"WIDER OBJECT: plants and ecosystems are studied too, and 'the virology of a sample' is the object standing in for the field.","cn":"更宽的对象：植物与生态系统也在研究之列，而「样本的病毒学」是对象代学科出场。"}]},"affixes":{"intro":{"en":"Virology is two elements: a Latin noun for poison and a Greek suffix for study, joined in English in the twentieth century.","cn":"virology 由两个成分构成：表示「毒」的拉丁名词与表示「研究」的希腊后缀，二十世纪在英语中组合。"},"latinIntro":{"en":"Latin gave virus; Greek gave -logia through Latin -logia. The compound is modern, so there is no single classical Latin word behind it.","cn":"拉丁语提供了 virus，希腊语经拉丁 -logia 提供了后缀；这个复合词是现代的，因此背后没有单一的古典拉丁词。"},"items":[{"word":"virology","structure":"virus + -logy (study)","meaning":"the science of viruses","meaningCN":"研究病毒的学科","example":"Virology dates from 1935.","exampleCN":"病毒学始于 1935 年。"},{"word":"virologist","structure":"virology + -ist (person)","meaning":"a practitioner of virology","meaningCN":"病毒学的从业者","example":"The virologist handled the sample.","exampleCN":"病毒学家处理了这份样本。"},{"word":"virological","structure":"virology + -ical (relation)","meaning":"relating to virology","meaningCN":"与病毒学有关的","example":"Virological testing confirmed the case.","exampleCN":"病毒学检测确认了该病例。"},{"word":"virologically","structure":"virological + -ly (adverb)","meaning":"from a virological standpoint","meaningCN":"从病毒学角度地","example":"The sample was virologically negative.","exampleCN":"该样本在病毒学上为阴性。"},{"word":"virus","structure":"Latin virus (poison)","meaning":"the object of the science","meaningCN":"这门学科的研究对象","example":"The virus was grown in cells.","exampleCN":"该病毒在细胞中培养。"},{"word":"viral","structure":"virus + -al","meaning":"of viruses","meaningCN":"病毒的","example":"Viral genomes are compact.","exampleCN":"病毒基因组很紧凑。"},{"word":"virion","structure":"virus + -on (particle)","meaning":"one virus particle","meaningCN":"一个病毒颗粒","example":"Each virion is a delivery device.","exampleCN":"每个病毒颗粒都是一台投送装置。"},{"word":"antiviral","structure":"anti- + viral","meaning":"against viruses","meaningCN":"对抗病毒的","example":"Antiviral therapy was started early.","exampleCN":"抗病毒治疗很早就开始了。"},{"word":"epidemiology","structure":"epi- + demos + -logy","meaning":"the study of disease spread in populations","meaningCN":"研究疾病在人群中传播的学科","example":"Epidemiology joined the virology team.","exampleCN":"流行病学加入了病毒学团队。"}],"latinEntries":[{"word":"virus","structure":"virus, -i (n., second declension)","meaning":"poison, venom, sap","meaningCN":"毒；毒液；汁液"},{"word":"virologia","structure":"virologia, -ae (f., Modern Latin, 20th century)","meaning":"the study of viruses","meaningCN":"研究病毒的学科"}]}},{"word":"parasite","ipa_uk":"/ˈpærəsaɪt/","ipa_us":"/ˈpærəsaɪt/","definition_zh":"寄生物；寄生虫；靠他人养活的人","definition_en":"an organism that lives on or in another organism and feeds at its expense, or a person who lives at others' expense","core_image":"一条细长的蠕虫钩在宿主肠壁上，宿主的血流在旁边经过","scene":"The parasite feeds on the host's blood without killing it at once.","sceneCN":"这里 parasite 是「寄生物」（第 1 个义项：靠宿主供养的生物）；句意：这种寄生物吸食宿主的血，却不立即杀死宿主。图中可辨识物件：钩在肠壁上的蠕虫、流经的血管、宿主的身体轮廓。","pos":[{"tag":"n.","zh":"寄生物；寄生虫（可数名词，复数 parasites）；也指靠他人供养的人（贬义）"}],"collocations":[{"phrase":"human parasite","zh":"人体寄生虫"},{"phrase":"parasite load","zh":"寄生虫负荷"},{"phrase":"obligate parasite","zh":"专性寄生物"},{"phrase":"brood parasite","zh":"巢寄生鸟"},{"phrase":"parasite species","zh":"寄生物物种"},{"phrase":"intestinal parasite","zh":"肠道寄生虫"}],"forms":[{"label":"单数","form":"parasite（一个寄生物）"},{"label":"复数","form":"parasites（多个寄生物）"},{"label":"形容词形式","form":"parasitic（寄生的）"},{"label":"抽象名词","form":"parasitism（寄生；寄生关系）"},{"label":"动词形式","form":"parasitize（寄生于）"}],"derivatives":[{"word":"parasites","pos":"n.","zh":"寄生物（复数）"},{"word":"parasitic","pos":"adj.","zh":"寄生的；寄生性的"},{"word":"parasitism","pos":"n.","zh":"寄生；寄生关系"},{"word":"parasitize","pos":"v.","zh":"寄生于；寄生侵袭"},{"word":"parasitology","pos":"n.","zh":"寄生虫学"},{"word":"parasitologist","pos":"n.","zh":"寄生虫学家"},{"word":"superparasite","pos":"n.","zh":"超寄生物（寄生于寄生物的生物）"}],"senses":[{"no":"01","title":"The Biological Parasite","titleCN":"寄生物：靠宿主供养的另一种生物","definition":"an organism that lives on or in a host and obtains nutrients from it","definitionCN":"生活在宿主体表或体内、从宿主获取养分的生物","example":"The parasite draws nutrients from the host without contributing any.","exampleCN":"这种寄生物从宿主身上吸取养分，却没有任何贡献。","why":"Greek parasitos meant 'one who eats at another's table'. Biology kept the table metaphor: the parasite takes food from a host that pays for it.","whyCN":"希腊语 parasitos 意为「在别人餐桌上吃饭的人」；生物学保留了这个餐桌隐喻：寄生物从付账的宿主那里取食。"},{"no":"02","title":"A Human Parasite","titleCN":"人体寄生虫：感染人的蠕虫与原虫","definition":"a parasite that infects human beings, such as a tapeworm or a protozoan","definitionCN":"感染人类的寄生物，如绦虫或原虫","example":"The child was treated for an intestinal parasite.","exampleCN":"这个孩子因肠道寄生虫接受了治疗。","why":"In medicine the word usually names a worm or a protozoan, not a bacterium or a virus. The host is specified as human, and the sense becomes a clinical category.","whyCN":"在医学中这个词通常指蠕虫或原虫，而不是细菌或病毒；宿主被限定为人类，该义项成为一个临床类别。"},{"no":"03","title":"A Plant Parasite","titleCN":"植物寄生物：附着在其他植物上","definition":"a plant that lives on another plant and takes water or nutrients from it","definitionCN":"附着在另一种植物上、从中获取水分或养分的植物","example":"Mistletoe is a plant parasite that draws water from its tree.","exampleCN":"槲寄生是一种植物寄生物，从树上吸取水分。","why":"Plants can parasitise too. The technical sense extends the table metaphor to a tree as host, and the feeding organ replaces the gut.","whyCN":"植物也会寄生；这一技术义把餐桌隐喻扩展到树木作宿主，吸器取代了肠道。"},{"no":"04","title":"A Social Parasite","titleCN":"社会寄生虫：靠他人生活的人","definition":"a person who lives at the expense of others without contributing","definitionCN":"靠他人供养而自己不付出的人","example":"He called his brother-in-law a parasite for never paying rent.","exampleCN":"他从不付房租的姐夫为寄生虫。","why":"This is the oldest sense: the Greek word described a flatterer who ate at rich tables. The modern insult keeps the same image, now with moral disapproval.","whyCN":"这是最古老的义项：希腊词描述的是在富人餐桌上蹭饭的奉承者；现代骂人话保留了同一画面，只是加了道德谴责。"},{"no":"05","title":"A Brood Parasite","titleCN":"巢寄生鸟：让别人代养幼鸟","definition":"a bird that lays its eggs in another species' nest","definitionCN":"把蛋产在另一种鸟巢中、由对方代养的鸟","example":"The brood parasite's chick pushed the host's eggs out of the nest.","exampleCN":"这只巢寄生鸟的雏鸟把宿主的蛋挤出了巢。","why":"Here the host is a parent, not a body. The sense shows that parasitism is about transferred cost, not necessarily about feeding on tissue.","whyCN":"这里的宿主是亲鸟，而不是身体；这个义项说明寄生的本质是成本转移，而不一定是取食组织。"},{"no":"06","title":"Obligate and Facultative","titleCN":"专性与兼性：依赖程度的分型","definition":"a parasite classified by whether it cannot survive without a host","definitionCN":"按是否离开宿主便无法生存而划分的寄生物类型","example":"An obligate parasite dies when separated from its host.","exampleCN":"专性寄生物一旦离开宿主就会死亡。","why":"The word can carry a subtype label. Obligate means the host is a necessity; facultative means the parasite can also live freely. The distinction measures dependence, the core of S1.","whyCN":"这个词可以带亚型标签：专性表示宿主是必需品，兼性表示它也能自由生活；这一区分衡量的正是第 1 个义项的核心——依赖程度。"},{"no":"07","title":"Parasite Load","titleCN":"寄生虫负荷：体内寄生物的数量","definition":"the number of parasites carried by one host","definitionCN":"一个宿主身上携带的寄生物数量","example":"A high parasite load weakened the herd.","exampleCN":"较高的寄生虫负荷削弱了兽群。","why":"Load makes the parasite countable. The phrase shifts from the organism to the burden it places on a host, which is the quantity clinicians and ecologists actually measure.","whyCN":"「负荷」使寄生物变得可计数；这个短语从生物体转向它加在宿主身上的负担，而这一数量才是临床医生与生态学家真正测量的东西。"},{"no":"08","title":"A Parasite on the Economy","titleCN":"经济寄生虫：依附于系统获利","definition":"an entity or activity that drains a system without producing value","definitionCN":"只消耗系统而不创造价值的实体或活动","example":"The report described the shell companies as parasites on the tax system.","exampleCN":"报告把那些空壳公司称为税收系统的寄生虫。","why":"The metaphor moves from a person to an institution: something attaches to a system and takes from it. It differs from S4 by scale and by the abstraction of the host.","whyCN":"这个隐喻从个人移到机构：某物附着在系统上并从中索取；它与第 4 个义项的区别在于尺度，以及宿主被抽象化。"}],"etymology":{"intro":{"en":"Parasite came from a Greek word for a dinner guest who paid nothing. Science adopted it in the seventeenth century for a creature that lives at a host's expense, and the insult travelled alongside the biology.","cn":"parasite 来自一个希腊词，指不付钱的白食客人。科学在十七世纪采用它，指靠宿主供养的生物，而骂人的用法一直与生物学用法并行。"},"items":[{"era":"GREEK PARASITOS","en":"Greek parasitos meant 'one who lives at another's expense, person who eats at the table of another', especially a flatterer who earned his dinner by praise. It was a noun use of an adjective meaning 'feeding beside'.","cn":"希腊语 parasitos 意为「靠他人供养的人、在别人餐桌上吃饭的人」，尤指靠奉承换取晚餐的人；它是由意为「在旁边取食」的形容词转成的名词。"},{"era":"PARA- AND SITOS","en":"The first element is para- 'beside'. The second is sitos 'grain, bread, food', a word of unknown origin. It also appears in syssitos 'table companion'. Sitos is often explained as a loanword or substrate word; Beekes suggests a link to a root meaning 'to strike', but this is disputed, so the origin of the second element is uncertain.","cn":"第一个成分是 para-「在旁边」，第二个是 sitos「谷物、面包、食物」，其来源不确定。它也出现在 syssitos「同桌吃饭的人」中。sitos 常被解释为借词或底层词；Beekes 提出可能与意为「击打」的词根有关，但这仍有争议，因此第二成分的来源不确定。"},{"era":"ENGLISH, 1530s","en":"English borrowed parasite in the 1530s for a hanger-on or toady, a social meaning that came straight from Greek comedy. The scientific sense appears in the 1640s.","cn":"英语于十六世纪三十年代借入 parasite，指攀附者或马屁精，这一社会义直接来自希腊喜剧；科学义则在十七世纪四十年代出现。"},{"era":"THE BIOLOGICAL SENSE","en":"The sense 'animal or plant that lives on or in and at the expense of another' is recorded from the 1640s, implied in parasitical. It kept the Greek picture of eating at someone else's table.","cn":"「生活在他者体表或体内、靠他者供养的动物或植物」这一义项记录于十七世纪四十年代，在 parasitical 中已有体现；它保留了希腊语「在别人桌上吃饭」的画面。"},{"era":"THE FAMILY","en":"Parasitic is recorded from the 1620s, parasitism from the 1610s, and the biological senses of both followed in the eighteenth and nineteenth centuries. The words existed first as social labels.","cn":"parasitic 记录于十七世纪二十年代，parasitism 记录于十七世纪十年代，两者的生物学义则分别到十八、十九世纪才出现；这些词最初都是社会标签。"},{"era":"MODERN PARASITOLOGY","en":"Parasitology grew as a medical and veterinary field once the life cycles of worms and protozoa were worked out. The word now spans everything from malaria to brood parasitism in birds.","cn":"当蠕虫与原虫的生活史被弄清之后，寄生虫学作为医学与兽医学领域发展起来；这个词现在涵盖从疟疾到鸟类巢寄生的广泛现象。"}]},"similar":{"note":{"en":"The first group separates the noun from its adjective and abstract noun. The second group holds ecological roles and everyday insults that are often confused with parasite.","cn":"第一组区分名词与其形容词、抽象名词；第二组是常与 parasite 混淆的生态角色与日常贬义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"parasitic","ipa":"/ˌpærəˈsɪtɪk/","tag":"adjective","definition":"The adjective meaning 'living as a parasite'. It describes the mode of life, not the organism itself.","definitionCN":"意为「以寄生方式生活的」形容词；描述生活方式，而不是生物体本身。"},{"word":"parasitism","ipa":"/ˈpærəsaɪtɪzəm/","tag":"noun, the relationship","definition":"The relationship between parasite and host. It names the arrangement, while parasite names one partner.","definitionCN":"寄生物与宿主之间的关系；它命名这种安排，而 parasite 命名其中一方。"},{"word":"parasitize","ipa":"/ˈpærəsaɪtɪz/","tag":"verb","definition":"To live on or in a host as a parasite. It is the action verb, not a noun for the actor.","definitionCN":"指以寄生物方式生活在宿主身上或体内；它是动作动词，不是施动者的名词。"}]},{"heading":"NEAR-SYNONYMS","entries":[{"word":"pathogen","ipa":"/ˈpæθədʒən/","tag":"noun, disease agent","definition":"Any agent that causes disease. A parasite may be a pathogen, but many parasites cause little or no disease, and bacteria are pathogens without being parasites.","definitionCN":"任何引起疾病的因子；寄生物可能是病原，但许多寄生物几乎不致病，而细菌可以是病原却不是寄生物。"},{"word":"symbiont","ipa":"/sɪmˈbaɪɒnt/","tag":"noun, partner","definition":"An organism living in close association with another. The term is neutral, while parasite names a cost to the host.","definitionCN":"与其他生物密切共同生活的生物；这个术语是中性的，而 parasite 命名的是宿主付出的代价。"},{"word":"commensal","ipa":"/kəˈmensəl/","tag":"noun/adjective, one who shares a table","definition":"An organism that lives with a host and takes food from it without harming it. It is literally 'at the same table', a milder version of parasite.","definitionCN":"与宿主共同生活、从其处取食却不伤害它的生物；字面意为「同桌吃饭」，是 parasite 的温和版本。"},{"word":"freeloader","ipa":"/ˈfriːləʊdə/","tag":"noun, social insult","definition":"An informal word for a person who takes without paying. It is the everyday equivalent of the social sense, with less bite than parasite.","definitionCN":"指只索取不付钱的人的非正式词；它是社会义项的日常对应词，语气比 parasite 稍轻。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"para- 'beside' + sitos 'food': one who eats beside another's table, and pays nothing.","cn":"para-「在旁边」+ sitos「食物」：在别人餐桌旁吃饭而不付钱的人。"},{"en":"The insult came first in English, in the 1530s; the biological sense followed in the 1640s.","cn":"英语里骂人的用法先出现，在十六世纪三十年代；生物学义到十七世纪四十年代才跟上。"},{"en":"The family runs parasite, parasites, parasitic, parasitism, parasitize, parasitology and parasitologist.","cn":"同族词包括 parasite、parasites、parasitic、parasitism、parasitize、parasitology、parasitologist。"},{"en":"Obligate means it cannot leave the host; facultative means it can.","cn":"专性表示离不开宿主，兼性表示可以离开。"},{"en":"A parasite takes; a commensal shares; a mutualist gives back.","cn":"寄生物索取，共栖者同吃，互利者回报。"}],"abstract":[{"en":"Picture a guest who arrives for dinner and never leaves, and never brings anything.","cn":"想象一位来吃晚饭的客人，从此不走，也从不带任何东西。"},{"en":"Picture a hook sunk into a wall that draws water from the other side.","cn":"想象一只钩子扎进墙里，从另一边抽水。"},{"en":"Picture a company with no product, only a claim on the public purse.","cn":"想象一家没有产品、只对公共财政伸手的公司。"}]},"examples":[{"en":"The parasite completes its life cycle inside two different hosts.","cn":"这种寄生物在两个不同的宿主体内完成生活史。"},{"en":"Researchers measured the parasite load in each fish.","cn":"研究者测量了每条鱼的寄生虫负荷。"},{"en":"He was a parasite on his friends' generosity for years.","cn":"多年来他一直靠朋友们的慷慨过活，是个寄生虫。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"para-（在旁边）+ sitos（食物）→ 在旁边吃别人的饭 → parasite 寄生物；靠他人供养的人","word":"parasite"},"root":"希腊 para-「在旁边」+ sitos「谷物、食物」（来源不明，可能为借词或底层词）→ parasitos「在别人餐桌上吃饭的人」→ 拉丁 parasitus → 法语 parasite → 英语 parasite（1530s 指攀附者；1640s 出现生物学义）。","sensesIntro":{"en":"Eight senses follow the table metaphor outward: a biological freeloader, a human infection, a plant, a social hanger-on, a nest usurper, a dependence type, a measured burden and an institution draining a system.","cn":"八个义项沿着餐桌隐喻向外扩展：生物学白食者、人体感染、植物、社会攀附者、占巢者、依赖类型、可测量的负担，以及吸干系统的机构。"},"semanticMap":{"core":{"en":"CORE IMAGE: a small body attached to a larger one, drawing food through a hook.","cn":"核心意象：一个小身体附着在更大的身体上，通过钩子抽取食物。"},"chain":["EATS AT YOUR TABLE","LIVES IN YOUR BODY","CLINGS TO YOUR PLANT","USES YOUR HOUSE","USES YOUR NEST","DRAINS YOUR SYSTEM"],"branches":[{"senses":"S1","en":"DEFINITION: the biological core, feeding at a host's expense.","cn":"定义：生物学核心，靠宿主付账取食。"},{"senses":"S2 · S3","en":"HOST KINDS: the host can be a human body or a plant, and the feeding organ changes with it.","cn":"宿主种类：宿主可以是人体或植物，取食器官也随之改变。"},{"senses":"S4 · S5","en":"SOCIAL AND NEST COST: the cost can be rent-free living or childcare, not only food.","cn":"社会与巢中的代价：代价可以是白住或代养，而不只是食物。"},{"senses":"S6 · S7","en":"DEGREE AND MEASURE: dependence can be obligate or facultative, and the burden can be counted as a load.","cn":"程度与测量：依赖可以是专性或兼性，负担可以按负荷计数。"},{"senses":"S8","en":"ABSTRACT HOST: the metaphor can attach a company or an activity to an economy.","cn":"抽象宿主：这个隐喻可以把一家公司或一项活动附着到经济体上。"}]},"affixes":{"intro":{"en":"Parasite is a Greek compound borrowed through Latin and French. Its family grows with Greek and Latin suffixes that turn the noun into an adjective, a relationship, a verb and a science.","cn":"parasite 是经拉丁语与法语借入的希腊复合词；它的词族靠希腊与拉丁后缀生长，把名词变成形容词、关系名词、动词与学科名。"},"latinIntro":{"en":"Latin parasitus meant 'toady, sponger', a direct borrowing from Greek parasitos. The suffix -ic, -ism and -ize were added in English and French rather than in classical Latin.","cn":"拉丁 parasitus 意为「马屁精、白食者」，直接借自希腊 parasitos；后缀 -ic、-ism 与 -ize 是在英语与法语中加上的，而非古典拉丁语。"},"items":[{"word":"parasite","structure":"Greek para- (beside) + sitos (food)","meaning":"one who feeds at another's expense","meaningCN":"靠他人供养取食者","example":"The parasite attached to the gut wall.","exampleCN":"寄生物附着在肠壁上。"},{"word":"parasites","structure":"parasite + plural -s","meaning":"more than one parasite","meaningCN":"不止一个寄生物","example":"Parasites can alter host behaviour.","exampleCN":"寄生物能改变宿主行为。"},{"word":"parasitic","structure":"parasite + -ic (relation)","meaning":"living as a parasite","meaningCN":"以寄生方式生活的","example":"A parasitic wasp lays eggs in a caterpillar.","exampleCN":"寄生蜂把卵产在毛虫体内。"},{"word":"parasitism","structure":"parasite + -ism (system or practice)","meaning":"the parasite-host relationship","meaningCN":"寄生物与宿主的关系","example":"Parasitism benefits one side only.","exampleCN":"寄生只对一方有利。"},{"word":"parasitize","structure":"parasite + -ize (verb)","meaning":"to infest as a parasite","meaningCN":"以寄生物方式侵染","example":"The mite parasitizes the bee.","exampleCN":"这种螨寄生于蜜蜂。"},{"word":"parasitology","structure":"parasite + -logy (study)","meaning":"the science of parasites","meaningCN":"研究寄生物的科学","example":"Parasitology tracks worm life cycles.","exampleCN":"寄生虫学追踪蠕虫生活史。"},{"word":"parasitologist","structure":"parasitology + -ist (person)","meaning":"a specialist in parasites","meaningCN":"研究寄生物的专家","example":"The parasitologist identified the worm.","exampleCN":"寄生虫学家鉴定了这种蠕虫。"},{"word":"superparasite","structure":"super- (above) + parasite","meaning":"a parasite of a parasite","meaningCN":"寄生于寄生物的寄生物","example":"A superparasite infested the wasp.","exampleCN":"一种超寄生物侵染了这只蜂。"}],"latinEntries":[{"word":"parasitus","structure":"parasitus, -i (m., Latin loan from Greek parasitos)","meaning":"toady, sponger, one who eats at another's table","meaningCN":"马屁精；白食者；在别人桌上吃饭的人"},{"word":"parasiticus","structure":"parasiticus, -a, -um (adj., from Greek parasitikos)","meaning":"of a parasite","meaningCN":"寄生物的"}]}},{"word":"parasitic","ipa_uk":"/ˌpærəˈsɪtɪk/","ipa_us":"/ˌpærəˈsɪtɪk/","definition_zh":"寄生的；寄生物引起的；依附他人而生的","definition_en":"living as a parasite, caused by parasites, or dependent on others at their expense","core_image":"一条丝状的寄生植物缠绕在树干上，细根扎进树皮深处","scene":"A parasitic worm was found in the fish's muscle.","sceneCN":"这里 parasitic 是「寄生的」（第 1 个义项：以寄生方式生活）；句意：在鱼的肌肉里发现了一条寄生蠕虫。图中可辨识物件：鱼体剖面、肌肉中的蠕虫、取样镊子。","pos":[{"tag":"adj.","zh":"寄生的；寄生物引起的；依附他人而生的（由名词 parasite 加 -ic 构成）"}],"collocations":[{"phrase":"parasitic disease","zh":"寄生虫病"},{"phrase":"parasitic worm","zh":"寄生蠕虫"},{"phrase":"parasitic plant","zh":"寄生植物"},{"phrase":"parasitic infection","zh":"寄生虫感染"},{"phrase":"parasitic capacitance","zh":"寄生电容（电子学）"},{"phrase":"parasitic loss","zh":"寄生损耗（工程学）"}],"forms":[{"label":"原级（形容词）","form":"parasitic（寄生的）"},{"label":"另一形容词形式","form":"parasitical（寄生的；旧式变体）"},{"label":"副词形式","form":"parasitically（以寄生方式地）"},{"label":"名词单数","form":"parasite（寄生物）"},{"label":"抽象名词","form":"parasitism（寄生；寄生关系）"}],"derivatives":[{"word":"parasite","pos":"n.","zh":"寄生物；寄生虫"},{"word":"parasitical","pos":"adj.","zh":"寄生的（旧式同义变体）"},{"word":"parasitically","pos":"adv.","zh":"以寄生方式地"},{"word":"parasitism","pos":"n.","zh":"寄生；寄生关系"},{"word":"parasitize","pos":"v.","zh":"寄生于"},{"word":"parasitology","pos":"n.","zh":"寄生虫学"},{"word":"nonparasitic","pos":"adj.","zh":"非寄生的"}],"senses":[{"no":"01","title":"Living as a Parasite","titleCN":"寄生的：以寄生物方式生活","definition":"living on or in a host and feeding at its expense","definitionCN":"生活在宿主体表或体内、靠其供养的","example":"The parasitic plant has no leaves for photosynthesis.","exampleCN":"这种寄生植物没有用于光合作用的叶片。","why":"The suffix -ic turns parasite into a mode-of-life adjective. The question it answers is not 'what is it' but 'how does it live', and the answer is: by taking from a host.","whyCN":"后缀 -ic 把 parasite 变成表示生活方式的形容词；它回答的不是「它是什么」，而是「它怎么活」，答案是：靠从宿主索取。"},{"no":"02","title":"Caused by Parasites","titleCN":"寄生物引起的：病因来自寄生物","definition":"caused by parasites, as a disease or an infection","definitionCN":"由寄生物引起的（如疾病或感染）","example":"The region suffers from several parasitic diseases.","exampleCN":"该地区遭受着好几种寄生虫病的困扰。","why":"Here the adjective names a cause, like bacterial or viral. The difference is the kind of agent: a worm or a protozoan rather than a cell or a virus particle.","whyCN":"这里形容词命名病因，与 bacterial、viral 同类；区别在于因子种类：是蠕虫或原虫，而不是细菌细胞或病毒颗粒。"},{"no":"03","title":"A Parasitic Worm","titleCN":"寄生蠕虫：多细胞寄生物","definition":"a worm that lives as a parasite, especially in an animal or human host","definitionCN":"以寄生方式生活的蠕虫，尤指寄生于动物或人体内者","example":"The parasitic worm can grow to several metres inside the gut.","exampleCN":"这种寄生蠕虫在肠道内能长到数米长。","why":"A worm is a multicellular animal, so the phrase shows that parasites are not all microbes. The adjective marks the feeding habit, not the size or the kingdom.","whyCN":"蠕虫是多细胞动物，因此这个短语说明寄生物并不都是微生物；形容词标出取食习性，而不是大小或生物界。"},{"no":"04","title":"A Parasitic Plant","titleCN":"寄生植物：附着在寄主植物上","definition":"a plant that draws water or nutrients from another plant","definitionCN":"从另一种植物获取水分或养分的植物","example":"Dodder is a parasitic plant that wraps around the stem of its host.","exampleCN":"菟丝子是一种寄生植物，缠绕在寄主植物的茎上。","why":"In botany the host is a plant and the feeding organ is a haustorium. The adjective still means the same: one partner pays, the other takes.","whyCN":"在植物学中，宿主是植物，取食器官是吸器；形容词含义不变：一方付账，另一方索取。"},{"no":"05","title":"Parasitic Dependence","titleCN":"寄生性依赖：人与人之间的依附","definition":"depending on another person or group in a way that costs them without return","definitionCN":"以只索取不回报的方式依赖他人或群体","example":"The relationship had become parasitic rather than mutual.","exampleCN":"这段关系已变成寄生性的，而不再是互利的。","why":"The metaphor moves from organisms to relationships. What is kept is the one-way flow of benefit; what is dropped is the biological host.","whyCN":"这个隐喻从生物体移到了人际关系；保留的是一边倒的利益流向，丢掉的则是生物学宿主。"},{"no":"06","title":"Parasitic Capacitance","titleCN":"寄生电容：电路中非计划内的电容","definition":"unwanted capacitance that arises between parts of a circuit","definitionCN":"电路各部分之间意外产生的、不需要的电容","example":"Parasitic capacitance slowed the signal at high frequency.","exampleCN":"高频下寄生电容使信号变慢。","why":"Electronics borrows the word for an effect that comes along uninvited with the parts you wanted. It is a cost paid by the circuit, exactly the parasitic pattern.","whyCN":"电子学借用这个词，指伴随所需元件不请自来的效应；这是电路付出的代价，正是寄生的模式。"},{"no":"07","title":"A Parasitic Gap","titleCN":"寄生空位：语言学中的依附结构","definition":"an empty position in a sentence that is licensed by another empty position","definitionCN":"句子中被另一个空位允准的空缺位置","example":"The parasitic gap in the relative clause depended on the first gap.","exampleCN":"关系从句中的寄生空位依赖第一个空位。","why":"Linguists use the image of one structure living off another. The second gap cannot stand alone; it exists only because the first one does.","whyCN":"语言学家用「一个结构靠另一个结构存活」的画面；第二个空位不能独立存在，只因为第一个空位存在它才存在。"},{"no":"08","title":"Parasitic Loss","titleCN":"寄生损耗：系统中被白白消耗的部分","definition":"energy or efficiency lost to unwanted effects in a system","definitionCN":"系统中被非预期效应白白消耗的能量或效率","example":"Parasitic loss in the converter reduced the range of the vehicle.","exampleCN":"变换器中的寄生损耗缩短了车辆的续航。","why":"Engineering extends the metaphor to efficiency: some output is eaten by side effects that serve no purpose. The host is the machine, and the parasite is the loss.","whyCN":"工程学把这个隐喻扩展到效率：一部分输出被无用的副作用吃掉；宿主是机器，寄生物就是损耗。"}],"etymology":{"intro":{"en":"Parasitic entered English in the 1620s from Latin parasiticus, which came from Greek parasitikos. Its social sense came first; the biological sense is recorded from 1731.","cn":"parasitic 于十七世纪二十年代从拉丁 parasiticus 进入英语，而后者来自希腊 parasitikos；社会义先出现，生物学义记录于 1731 年。"},"items":[{"era":"GREEK PARASITOS","en":"Greek parasitos meant 'one who eats at another's table', from para- 'beside' and sitos 'food'. The word described a flatterer who lived at a rich man's expense.","cn":"希腊 parasitos 意为「在别人餐桌上吃饭的人」，由 para-「在旁边」与 sitos「食物」构成；这个词描述靠富人供养的奉承者。"},{"era":"GREEK PARASITIKOS","en":"The adjective parasitikos meant 'of or pertaining to a parasite; the trade of a parasite'. Greek thus had the adjective before English borrowed either form.","cn":"形容词 parasitikos 意为「寄生物的；寄生这一行当的」；因此在英语借入任一形式之前，希腊语已经有了形容词。"},{"era":"LATIN AND ENGLISH","en":"Latin parasiticus was borrowed into English as parasitic in the 1620s. The older adjective parasitical also exists, formed with -al on the same stem.","cn":"拉丁 parasiticus 于十七世纪二十年代借入英语作 parasitic；另有一个更旧的形容词 parasitical，是在同一词干上加 -al 构成。"},{"era":"THE BIOLOGICAL SENSE, 1731","en":"The biological sense is recorded from 1731. Before that date the adjective described people, not worms, so the scientific use is a later narrowing of an insult.","cn":"生物学义记录于 1731 年；在此之前的形容词描述的是人而不是蠕虫，因此科学用法是一个骂人词的后来收窄。"},{"era":"ELECTRONICS AND LINGUISTICS","en":"Parasitic capacitance and parasitic loss entered electrical engineering in the twentieth century, and parasitic gap entered linguistics in the 1970s. Each keeps the one-way cost structure.","cn":"寄生电容与寄生损耗在二十世纪进入电气工程，寄生空位在二十世纪七十年代进入语言学；每一处用法都保留了一边倒的成本结构。"},{"era":"THE SECOND ELEMENT","en":"Greek sitos 'grain, food' is of unknown origin, possibly a loanword or substrate word; Beekes's suggestion of a link to a root meaning 'to strike' is disputed. The first element, para-, is clear, so only the second is uncertain.","cn":"希腊 sitos「谷物、食物」来源不确定，可能是借词或底层词；Beekes 提出与意为「击打」的词根有关，但仍有争议。第一个成分 para- 是清楚的，因此只有第二个成分存疑。"}]},"similar":{"note":{"en":"The first group separates the adjective from its rare variant and from the noun. The second group holds adjectives that describe neighbouring ecological or engineering relations.","cn":"第一组区分这个形容词与它的罕用变体及名词；第二组是描述相邻生态关系或工程关系的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"parasitical","ipa":"/ˌpærəˈsɪtɪkəl/","tag":"adjective, older variant","definition":"An older synonym of parasitic, formed with -al. It survives in some nineteenth-century and technical writing.","definitionCN":"parasitic 的旧式同义词，用 -al 构成；仍见于部分十九世纪与技术性文字。"},{"word":"parasitically","ipa":"/ˌpærəˈsɪtɪkli/","tag":"adverb","definition":"The adverb, meaning 'in a parasitic way'. It modifies a verb, as in 'the plant grows parasitically'.","definitionCN":"副词，意为「以寄生方式地」；修饰动词，如「这株植物以寄生方式生长」。"},{"word":"parasite","ipa":"/ˈpærəsaɪt/","tag":"noun","definition":"The organism itself. Parasitic is the adjective describing its way of life.","definitionCN":"指生物体本身；parasitic 是描述其生活方式的形容词。"}]},{"heading":"NEAR-SYNONYMS","entries":[{"word":"symbiotic","ipa":"/ˌsɪmbaɪˈɒtɪk/","tag":"adjective, living together","definition":"Living in close association, usually with benefit to both. It is the neutral or positive counterpart of parasitic, not a synonym.","definitionCN":"指密切共同生活的，通常双方受益；它是 parasitic 的中性或正面对应词，并非同义。"},{"word":"commensal","ipa":"/kəˈmensəl/","tag":"adjective/noun, sharing a table","definition":"Living with a host and taking food without harming it. It is a milder relation than parasitic, which implies a cost.","definitionCN":"与宿主共同生活、取食而不伤害它；比 parasitic 温和，后者意味着代价。"},{"word":"infectious","ipa":"/ɪnˈfekʃəs/","tag":"adjective, transmissible","definition":"Capable of being transmitted. Parasitic diseases may be infectious, but the adjective describes transmission, not the mode of feeding.","definitionCN":"指可传播的；寄生虫病可能具有传染性，但该形容词描述传播，而不是取食方式。"},{"word":"dependent","ipa":"/dɪˈpendənt/","tag":"adjective, relying on another","definition":"Relying on someone or something for support. In the social sense it is close to parasitic, but it carries no judgment of exploitation.","definitionCN":"指依靠他人或他物支持的；在社会义上接近 parasitic，但不含「剥削」的评判。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"parasite + -ic: 'living in the parasite way', the adjective of mode rather than of object.","cn":"parasite + -ic：意为「以寄生方式生活的」，是生活方式形容词，而不是对象名词。"},{"en":"The social sense came first (1620s); the biological sense is recorded only from 1731.","cn":"社会义先出现（十七世纪二十年代），生物学义到 1731 年才有记录。"},{"en":"The family runs parasite, parasitic, parasitical, parasitically, parasitism and parasitology.","cn":"同族词包括 parasite、parasitic、parasitical、parasitically、parasitism、parasitology。"},{"en":"The word crosses kingdoms: a worm, a plant and a wasp can all be parasitic.","cn":"这个词跨越生物界：蠕虫、植物与蜂都可以是寄生的。"},{"en":"Engineering borrows it for costs that arrive uninvited: parasitic capacitance, parasitic loss.","cn":"工程学借用它指不请自来的成本：寄生电容、寄生损耗。"}],"abstract":[{"en":"Picture a vine that has forgotten how to make its own food and lives on the tree instead.","cn":"想象一株藤忘了如何自己制造食物，改靠那棵树过活。"},{"en":"Picture a circuit where the wires themselves steal a little of the signal.","cn":"想象一个电路，连导线本身都偷走一点信号。"},{"en":"Picture a sentence with a hole that exists only because another hole exists.","cn":"想象一个句子，其中一个空洞只因为另一个空洞存在才存在。"}]},"examples":[{"en":"Parasitic infections are common where clean water is scarce.","cn":"在清洁水源稀缺的地方，寄生虫感染很常见。"},{"en":"The parasitic wasp lays its eggs inside a living caterpillar.","cn":"寄生蜂把卵产在活毛虫体内。"},{"en":"Engineers reduced parasitic capacitance by shortening the leads.","cn":"工程师通过缩短引线来降低寄生电容。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"parasite（寄生物）+ -ic（……的）→ 寄生物的 → parasitic 寄生的","word":"parasitic"},"root":"希腊 para-「在旁边」+ sitos「食物」→ parasitos「在别人桌上吃饭的人」→ 希腊 parasitikos「寄生物的」→ 拉丁 parasiticus → 英语 parasitic（1620s，社会义；1731 年出现生物学义）。","sensesIntro":{"en":"Eight senses follow the adjective from biology into medicine, botany, social judgment, electronics, linguistics and engineering, keeping the same one-way flow of cost.","cn":"八个义项让这个形容词从生物学走向医学、植物学、社会评判、电子学、语言学与工程学，始终保留同一条一边倒的成本流向。"},"semanticMap":{"core":{"en":"CORE IMAGE: a thread-like plant wrapping a trunk, its roots sunk into the bark.","cn":"核心意象：一条丝状植物缠住树干，细根扎进树皮。"},"chain":["LIVING BY TAKING","MAKING DISEASE","A WORM IN FLESH","A VINE ON A TREE","A PERSON ON A FRIEND","A COST IN A MACHINE"],"branches":[{"senses":"S1","en":"MODE OF LIFE: the core adjective describes how the organism lives, not what it is.","cn":"生活方式：核心形容词描述生物如何生活，而不是它是什么。"},{"senses":"S2 · S3","en":"MEDICAL CAUSE: the parasitic agent can be a worm or a protozoan, and the adjective names it as the cause.","cn":"医学病因：寄生因子可以是蠕虫或原虫，形容词把它标为病因。"},{"senses":"S4","en":"BOTANY: the host becomes a plant and the feeding organ becomes a haustorium.","cn":"植物学：宿主变成植物，取食器官变成吸器。"},{"senses":"S5 · S7 · S8","en":"TRANSFERRED COST: people, sentences and machines can all host a one-way drain.","cn":"转移的成本：人、句子与机器都可以承载一边倒的消耗。"},{"senses":"S6","en":"ENGINEERING: unwanted capacitance is the clearest non-living parasite.","cn":"工程学：不需要的电容是最清楚的非生命「寄生物」。"}]},"affixes":{"intro":{"en":"Parasitic is a Greek compound with a Greek adjective ending, borrowed through Latin: beside, food, and 'of the kind of'.","cn":"parasitic 是带希腊形容词词尾的希腊复合词，经拉丁语借入：旁边、食物，以及「属于这一类」。"},"latinIntro":{"en":"Latin parasiticus came from Greek parasitikos and supplied the English adjective. The variant parasitical adds Latin -alis to the same stem.","cn":"拉丁 parasiticus 来自希腊 parasitikos，提供了英语形容词；变体 parasitical 是在同一词干上加拉丁 -alis。"},"items":[{"word":"parasitic","structure":"parasite + -ic (relation)","meaning":"living at a host's expense","meaningCN":"靠宿主供养生活","example":"A parasitic fungus attacked the crop.","exampleCN":"一种寄生真菌侵袭了庄稼。"},{"word":"parasitical","structure":"parasite + -ical (relation)","meaning":"older variant of parasitic","meaningCN":"parasitic 的旧式变体","example":"Victorian writers preferred parasitical.","exampleCN":"维多利亚时代作者更爱用 parasitical。"},{"word":"parasitically","structure":"parasitic + -ly (adverb)","meaning":"in a parasitic manner","meaningCN":"以寄生方式地","example":"The plant lives parasitically on roots.","exampleCN":"这株植物寄生在根上生活。"},{"word":"parasite","structure":"Greek para- + sitos","meaning":"the organism itself","meaningCN":"寄生物本身","example":"The parasite left the host weak.","exampleCN":"寄生物让宿主变得虚弱。"},{"word":"parasitism","structure":"parasite + -ism","meaning":"the relationship","meaningCN":"寄生关系","example":"Parasitism shaped the bird's nesting habit.","exampleCN":"寄生关系塑造了这种鸟的筑巢习性。"},{"word":"parasitize","structure":"parasite + -ize","meaning":"to infest as a parasite","meaningCN":"以寄生物方式侵染","example":"The larva parasitizes the ant.","exampleCN":"幼虫寄生于蚂蚁。"},{"word":"parasitology","structure":"parasite + -logy","meaning":"the study of parasites","meaningCN":"研究寄生物的学科","example":"Parasitology explains the worm's cycle.","exampleCN":"寄生虫学解释了这种蠕虫的生活史。"},{"word":"nonparasitic","structure":"non- (not) + parasitic","meaning":"not living as a parasite","meaningCN":"非寄生的","example":"The nonparasitic species lives in soil.","exampleCN":"这个非寄生种生活在土壤中。"},{"word":"endoparasitic","structure":"endo- (within) + parasitic","meaning":"living inside a host","meaningCN":"生活在宿主体内的","example":"An endoparasitic worm filled the intestine.","exampleCN":"一条体内寄生蠕虫充满了肠道。"}],"latinEntries":[{"word":"parasiticus","structure":"parasiticus, -a, -um (adj., from Greek parasitikos)","meaning":"of or belonging to a parasite","meaningCN":"寄生物的；属于寄生物的"},{"word":"parasitus","structure":"parasitus, -i (m., from Greek parasitos)","meaning":"toady, sponger","meaningCN":"马屁精；白食者"}]}},{"word":"parasitism","ipa_uk":"/ˈpærəsaɪtɪzəm/","ipa_us":"/ˈpærəsaɪtɪzəm/","definition_zh":"寄生；寄生关系；靠他人供养的生存方式","definition_en":"the relationship or way of life in which one organism lives at the expense of another","core_image":"两种生物并列：一方贴附在另一方身上，养分的箭头只朝一个方向流动","scene":"Parasitism keeps the worm alive while slowly weakening the host.","sceneCN":"这里 parasitism 是「寄生关系」（第 1 个义项：一方受益、一方受损的种间关系）；句意：寄生关系让蠕虫存活，同时慢慢削弱宿主。图中可辨识物件：两种生物、单向的养分箭头、逐渐虚弱的宿主轮廓。","pos":[{"tag":"n.","zh":"寄生；寄生关系（不可数名词，也可加限定语指某一种寄生类型）"}],"collocations":[{"phrase":"obligate parasitism","zh":"专性寄生"},{"phrase":"facultative parasitism","zh":"兼性寄生"},{"phrase":"brood parasitism","zh":"巢寄生"},{"phrase":"social parasitism","zh":"社会寄生"},{"phrase":"hyperparasitism","zh":"超寄生"},{"phrase":"parasitism rate","zh":"寄生率；感染率"}],"forms":[{"label":"抽象名词","form":"parasitism（寄生；寄生关系，不可数）"},{"label":"施动者名词","form":"parasite（寄生物）"},{"label":"形容词形式","form":"parasitic（寄生的）"},{"label":"动词形式","form":"parasitize（寄生于）"},{"label":"学科名称","form":"parasitology（寄生虫学）"}],"derivatives":[{"word":"parasite","pos":"n.","zh":"寄生物；寄生虫"},{"word":"parasitic","pos":"adj.","zh":"寄生的"},{"word":"parasitize","pos":"v.","zh":"寄生于；寄生侵袭"},{"word":"parasitology","pos":"n.","zh":"寄生虫学"},{"word":"parasitologist","pos":"n.","zh":"寄生虫学家"},{"word":"hyperparasitism","pos":"n.","zh":"超寄生（寄生物又被寄生的现象）"},{"word":"endoparasitism","pos":"n.","zh":"体内寄生"}],"senses":[{"no":"01","title":"The Biological Relationship","titleCN":"寄生关系：一方受益、一方受损","definition":"a close relationship in which one organism benefits and the other is harmed","definitionCN":"一种一方获益、另一方受损的密切种间关系","example":"Parasitism differs from mutualism because only one partner gains.","exampleCN":"寄生与互利共生不同，因为只有一方获益。","why":"The suffix -ism names a system or relationship rather than an actor. Parasitism is the arrangement itself: one lives in or on the other and takes from it, while the host pays a cost.","whyCN":"后缀 -ism 命名的是制度或关系，而不是行动者；parasitism 指这种安排本身：一方生活在他者体表或体内并从中索取，而宿主付出代价。"},{"no":"02","title":"Social Parasitism","titleCN":"社会寄生：人与人之间的单向索取","definition":"a social pattern in which one person lives at others' expense","definitionCN":"一个人靠他人供养而生活的社会模式","example":"The novel treats parasitism among relatives as a quiet form of violence.","exampleCN":"这部小说把亲属间的社会寄生当作一种无声的暴力。","why":"The oldest English sense of parasite was a social one, a flatterer at a rich man's table. Parasitism extends that picture from a body to a household or a class.","whyCN":"parasite 在英语中最古老的义项是社会性的，指在富人家桌旁蹭饭的奉承者；parasitism 把这个画面从身体扩展到家庭或阶层。"},{"no":"03","title":"Brood Parasitism","titleCN":"巢寄生：把养育成本转给别的鸟","definition":"the habit of laying eggs in another bird's nest so that the host raises the young","definitionCN":"把蛋产进别的鸟巢、让宿主代为育雏的习性","example":"Brood parasitism lets the female avoid all parental care.","exampleCN":"巢寄生让雌鸟完全免去育雏之责。","why":"Here the cost transferred is parental care, not food from a body. The relationship is still parasitic because one side pays and the other takes, which is why it is named after the same root.","whyCN":"这里转移的成本是育雏，而不是从身体取食；这段关系仍属寄生，因为一方付账、一方索取，所以沿用同一个词根来命名。"},{"no":"04","title":"Obligate Parasitism","titleCN":"专性寄生：离开宿主就活不了","definition":"a form of parasitism in which the parasite cannot complete its life cycle without a host","definitionCN":"寄生物离开宿主便无法完成生活史的寄生形式","example":"Obligate parasitism ties the worm's entire cycle to a single host species.","exampleCN":"专性寄生把这种蠕虫的整个生活史绑在单一宿主物种上。","why":"Obligate marks necessity. The parasite has lost the ability to live freely, so the host is not an option but a condition of existence. The word measures how deep the dependence has gone.","whyCN":"专性标记「必需」：寄生物已失去自由生活的能力，宿主不是可选项，而是存在的条件；这个词衡量的是依赖深到了什么程度。"},{"no":"05","title":"Facultative Parasitism","titleCN":"兼性寄生：可以寄生，也可以自活","definition":"a form of parasitism in which the organism can also live freely","definitionCN":"生物既能寄生、也能自由生活的寄生形式","example":"Facultative parasitism allows the fungus to survive in soil between infections.","exampleCN":"兼性寄生让这种真菌在两次感染之间能在土壤中存活。","why":"Facultative means optional. The same organism may take a host when it suits it and live independently otherwise, so the relationship is real but not mandatory.","whyCN":"兼性意味着可选：同一生物在合适时可以利用宿主，否则独立生活；因此这段关系真实存在，但不是必需的。"},{"no":"06","title":"Hyperparasitism","titleCN":"超寄生：寄生物又被寄生","definition":"the condition in which a parasite is itself parasitised by another organism","definitionCN":"寄生物本身又被另一种生物寄生的状态","example":"Hyperparasitism adds a third level to the food chain.","exampleCN":"超寄生给食物链又加上了第三层。","why":"Hyper- means 'above, beyond'. The prefix stacks one parasitic relationship on another, producing a chain of hosts in which each level lives at the expense of the one below.","whyCN":"hyper- 意为「在上、超出」；这个前缀把一段寄生关系叠在另一段之上，形成一条宿主链，每一层都靠下面一层供养。"},{"no":"07","title":"The Rate of Infection","titleCN":"寄生率：被寄生的比例","definition":"the proportion of hosts in a population that carry parasites","definitionCN":"一个种群中携带寄生物的宿主所占比例","example":"Parasitism reached eighty percent in the sampled snails.","exampleCN":"在抽样的螺中，寄生率达到百分之八十。","why":"In ecology the abstract noun can be measured: how many hosts are infected. The sense shifts from the relationship to its frequency, which is what a field study reports.","whyCN":"在生态学中，这个抽象名词可以被测量：有多少宿主被感染；义项从关系本身转向它的出现频率，这正是野外研究要报告的东西。"},{"no":"08","title":"An Evolutionary Strategy","titleCN":"演化策略：一种生存路线","definition":"parasitism viewed as an evolutionary strategy for obtaining resources","definitionCN":"把寄生视为获取资源的一种演化策略","example":"Parasitism evolved independently in many unrelated groups.","exampleCN":"寄生在许多互不相关的类群中独立演化出来。","why":"Evolutionary biology treats parasitism as a route, not only a state: giving up independent resource use can be a successful way to survive. The word then names a strategy rather than a single relationship.","whyCN":"演化生物学把寄生当作一条路线，而不只是一种状态：放弃独立获取资源，可能是一种成功的生存方式；此时这个词命名的是一种策略，而不是某段具体关系。"}],"etymology":{"intro":{"en":"Parasitism is the abstract noun of parasite, formed with -ism. English used it of people for two centuries before biology gave it a precise meaning in the nineteenth century.","cn":"parasitism 是 parasite 的抽象名词，由 -ism 构成；英语把它用于人长达两个世纪，直到十九世纪生物学才赋予它精确含义。"},"items":[{"era":"GREEK PARASITOS","en":"Greek parasitos meant 'one who eats at another's table', from para- 'beside' and sitos 'food'. The word named a flatterer who lived at a rich man's expense.","cn":"希腊 parasitos 意为「在别人餐桌上吃饭的人」，由 para-「在旁边」与 sitos「食物」构成；这个词指靠富人供养的奉承者。"},{"era":"THE -ISM SUFFIX","en":"Greek -ismos and Latin -ismus formed nouns for practices, systems and doctrines. Added to parasite, it creates the name of the practice rather than the name of the practitioner.","cn":"希腊 -ismos 与拉丁 -ismus 构成表示做法、制度与学说的名词；加在 parasite 上，它造出做法之名，而不是从业者之名。"},{"era":"ENGLISH, 1610s","en":"Parasitism is recorded from the 1610s with the sense 'a habitual living on or at the expense of another'. The first users were describing people, not worms.","cn":"parasitism 记录于十七世纪十年代，义为「习惯性地靠他人供养生活」；最早的使用者描述的是人，不是蠕虫。"},{"era":"THE BIOLOGICAL SENSE, 1840","en":"The biological sense 'vital relation of a parasite to a host' is recorded by 1840. It arrived when naturalists began to classify the many ways in which one organism can live off another.","cn":"「寄生物与宿主的生命关系」这一生物学义项记录于 1840 年；它出现于博物学者开始对「一种生物靠另一种生物生活」的多种方式进行分类之时。"},{"era":"THE SECOND ELEMENT","en":"Greek sitos 'grain, food' is of unknown origin, possibly a loanword or substrate word. Beekes's suggestion of a link to a root meaning 'to strike' is disputed. The prefix para- is clear; only the food element is uncertain.","cn":"希腊 sitos「谷物、食物」来源不确定，可能是借词或底层词；Beekes 提出与意为「击打」的词根有关，但仍有争议。前缀 para- 是清楚的，只有「食物」这一成分存疑。"},{"era":"MODERN TYPES","en":"Obligate, facultative, brood and hyperparasitism are later technical compounds. Each adds a Latin or Greek modifier to the same abstract noun, marking degree, host or level.","cn":"专性、兼性、巢与超寄生都是后来形成的技术复合词；每个词都在同一个抽象名词前加拉丁或希腊修饰语，标出程度、宿主或层级。"}]},"similar":{"note":{"en":"The first group separates the abstract noun from the actor and the adjective. The second group holds other ecological relationships that differ in who pays and who benefits.","cn":"第一组区分抽象名词与行动者、形容词；第二组是其他生态关系，区别在于谁付账、谁受益。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"parasite","ipa":"/ˈpærəsaɪt/","tag":"noun, the actor","definition":"The organism that lives at the host's expense. Parasitism names the relationship, parasite names one partner.","definitionCN":"靠宿主供养的生物；parasitism 命名关系，parasite 命名其中一方。"},{"word":"parasitic","ipa":"/ˌpærəˈsɪtɪk/","tag":"adjective","definition":"Describing a way of life. It can modify disease, worm or plant, while parasitism is the abstract noun.","definitionCN":"描述生活方式的形容词，可修饰疾病、蠕虫或植物；而 parasitism 是抽象名词。"},{"word":"parasitize","ipa":"/ˈpærəsaɪtɪz/","tag":"verb","definition":"To infest a host as a parasite. It is the action, not the relationship seen as a whole.","definitionCN":"指以寄生物方式侵染宿主；它是动作，而不是被整体看待的关系。"}]},{"heading":"NEAR-SYNONYMS","entries":[{"word":"mutualism","ipa":"/mjuːˈtjuːəlɪzəm/","tag":"noun, both benefit","definition":"A relationship in which both partners gain. It is the positive counterpart of parasitism, not a variant of it.","definitionCN":"双方都获益的关系；它是 parasitism 的正面对应，而不是其变体。"},{"word":"commensalism","ipa":"/kəˈmensəlɪzəm/","tag":"noun, one gains, one unaffected","definition":"A relationship in which one partner gains and the other is neither helped nor harmed. It is milder than parasitism because the host pays no cost.","definitionCN":"一方获益、另一方既不受益也不受损的关系；它比 parasitism 温和，因为宿主不付代价。"},{"word":"exploitation","ipa":"/ɪkˈsplɔɪˈteɪʃən/","tag":"noun, using another","definition":"The act of using another for one's own advantage. It is the general social meaning that parasitism narrows to a way of life.","definitionCN":"为自身利益利用他者的行为；它是泛指的社会含义，parasitism 则把它收窄为一种生活方式。"},{"word":"parasitosis","ipa":"/ˌpærəsaɪˈtəʊsɪs/","tag":"noun, the disease","definition":"A disease caused by parasites. It names the medical condition, while parasitism names the relationship.","definitionCN":"由寄生物引起的疾病；它命名医学状况，而 parasitism 命名关系。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"parasite + -ism: the practice, not the practitioner; the relationship, not the organism.","cn":"parasite + -ism：指做法，不指从业者；指关系，不指生物。"},{"en":"The human sense arrived in the 1610s; the biological sense only by 1840.","cn":"指人的义项在十七世纪十年代出现，生物学义到 1840 年才有。"},{"en":"The family runs parasite, parasitic, parasitism, parasitize, parasitology and hyperparasitism.","cn":"同族词包括 parasite、parasitic、parasitism、parasitize、parasitology、hyperparasitism。"},{"en":"Obligate means the host is required; facultative means the host is optional.","cn":"专性表示宿主是必需的，兼性表示宿主是可选的。"},{"en":"Three costs can be transferred: food from a body, care for young, and rent for a life.","cn":"可转移的成本有三种：身体里的食物、对幼崽的照料，以及生活的房租。"}],"abstract":[{"en":"Picture an arrow that only points one way, from host to guest.","cn":"想象一支只朝一个方向的箭头，从宿主指向来客。"},{"en":"Picture a nest where the real mother never returns.","cn":"想象一个巢，真正的母亲再也不回来。"},{"en":"Picture a ladder of hosts, each carrying the one above it.","cn":"想象一架宿主叠成的梯子，每一层都背着上面一层。"}]},"examples":[{"en":"Parasitism can drive the evolution of new defences in hosts.","cn":"寄生关系能推动宿主演化出新的防御。"},{"en":"Brood parasitism is common among certain warblers and cowbirds.","cn":"巢寄生在某些莺类与灶巢鸟中很常见。"},{"en":"The study measured parasitism across twelve lakes.","cn":"这项研究测量了十二个湖泊中的寄生率。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"parasite（寄生物）+ -ism（……主义、……关系）→ 寄生的关系 → parasitism 寄生","word":"parasitism"},"root":"希腊 para-「在旁边」+ sitos「食物」→ parasitos「在别人桌上吃饭的人」→ 英语 parasite（1530s）→ parasite + -ism → parasitism（1610s 社会义；1840 年出现生物学义）。","sensesIntro":{"en":"Eight senses move from the biological relationship to its social form, its nest form, its two dependence types, its stacked form, its measured rate and its status as an evolutionary strategy.","cn":"八个义项从生物学关系出发，走向它的社会形式、巢中形式、两种依赖类型、叠层形式、可测比率，以及作为演化策略的地位。"},"semanticMap":{"core":{"en":"CORE IMAGE: two bodies side by side, with a one-way arrow of nutrients between them.","cn":"核心意象：并排的两个身体，中间一支单向的养分箭头。"},"chain":["ONE SIDE PAYS","A PERSON PAYS","A PARENT PAYS","THE HOST IS REQUIRED","THE HOST IS OPTIONAL","A HOST CARRIES A HOST"],"branches":[{"senses":"S1","en":"RELATIONSHIP: the core abstract sense, one benefits and one is harmed.","cn":"关系：核心抽象义，一方获益、一方受损。"},{"senses":"S2 · S3","en":"TRANSFERRED COST: the cost can be food, rent or parental care, and the host can be a household or a nest.","cn":"转移的成本：成本可以是食物、房租或育雏，宿主可以是家庭或鸟巢。"},{"senses":"S4 · S5","en":"DEGREE: obligate and facultative measure whether the host is a necessity or an option.","cn":"程度：专性与兼性衡量宿主是必需还是可选。"},{"senses":"S6","en":"LEVEL: hyperparasitism stacks the relationship so that a parasite becomes a host.","cn":"层级：超寄生把关系叠起来，使寄生物反过来成为宿主。"},{"senses":"S7 · S8","en":"MEASURE AND STRATEGY: ecology counts how often it happens, and evolution treats it as a route to survival.","cn":"测量与策略：生态学数它发生的频率，演化论把它当作一条生存路线。"}]},"affixes":{"intro":{"en":"Parasitism is a Greek compound noun with a Greek abstract suffix: beside, food, and the name of a practice.","cn":"parasitism 是带希腊抽象后缀的希腊复合名词：旁边、食物，以及一种做法的名称。"},"latinIntro":{"en":"Latin parasitus supplied the base noun, and Latin -ismus supplied the abstract ending. The word is English, but both parts reached it through Latinized forms of Greek.","cn":"拉丁 parasitus 提供了基础名词，拉丁 -ismus 提供了抽象词尾；这个词是英语词，但两个部分都经希腊语的拉丁化形式传入。"},"items":[{"word":"parasitism","structure":"parasite + -ism (system or practice)","meaning":"the parasite-host relationship","meaningCN":"寄生物与宿主的关系","example":"Parasitism shaped the host's defences.","exampleCN":"寄生关系塑造了宿主的防御。"},{"word":"parasite","structure":"Greek para- + sitos","meaning":"one who lives at another's expense","meaningCN":"靠他者供养生活者","example":"The parasite left the host alive.","exampleCN":"寄生物让宿主活着。"},{"word":"parasitic","structure":"parasite + -ic","meaning":"living as a parasite","meaningCN":"以寄生方式生活的","example":"A parasitic insect fed on the bird.","exampleCN":"一种寄生昆虫以这只鸟为食。"},{"word":"parasitize","structure":"parasite + -ize","meaning":"to infest as a parasite","meaningCN":"以寄生物方式侵染","example":"The wasp parasitizes the grub.","exampleCN":"这种蜂寄生于蛴螬。"},{"word":"parasitology","structure":"parasite + -logy","meaning":"the study of parasites","meaningCN":"研究寄生物的学科","example":"Parasitology explains host specificity.","exampleCN":"寄生虫学解释了宿主专一性。"},{"word":"hyperparasitism","structure":"hyper- (above) + parasitism","meaning":"a parasite parasitised by another","meaningCN":"寄生物又被另一种生物寄生","example":"Hyperparasitism controls some pest populations.","exampleCN":"超寄生控制着某些害虫种群。"},{"word":"endoparasitism","structure":"endo- (within) + parasitism","meaning":"parasitism inside a host","meaningCN":"在宿主体内的寄生","example":"Endoparasitism requires tolerance of host defences.","exampleCN":"体内寄生需要耐受宿主的防御。"},{"word":"ectoparasitism","structure":"ecto- (outside) + parasitism","meaning":"parasitism on the surface of a host","meaningCN":"在宿主体表的寄生","example":"Ectoparasitism spreads easily between hosts.","exampleCN":"体表寄生在宿主之间易于传播。"},{"word":"brood parasitism","structure":"brood (young) + parasitism","meaning":"laying eggs for another bird to raise","meaningCN":"把蛋交给别的鸟代养","example":"Brood parasitism saves the female time.","exampleCN":"巢寄生为雌鸟节省时间。"}],"latinEntries":[{"word":"parasitus","structure":"parasitus, -i (m., from Greek parasitos)","meaning":"toady, sponger","meaningCN":"马屁精；白食者"},{"word":"parasiticus","structure":"parasiticus, -a, -um (adj., from Greek parasitikos)","meaning":"of a parasite","meaningCN":"寄生物的"}]}},{"word":"host","ipa_uk":"/həʊst/","ipa_us":"/hoʊst/","definition_zh":"主人；宿主；（活动的）主办方；主持人；主机","definition_en":"a person who receives guests, an organism that harbours another, the organiser of an event, or a computer that serves others","core_image":"一扇打开的门，主人站在门内迎接客人，屋内为客人留着一间房","scene":"The host offered the guests a room for the night.","sceneCN":"这里 host 是「主人」（第 1 个义项：接待客人的人）；句意：主人为客人们提供了一间过夜用的房间。图中可辨识物件：打开的门、站在门内的主人、为客人准备的房间。","pos":[{"tag":"n.","zh":"主人；东道主；宿主；主办方；主持人；（计算机）主机（可数名词，复数 hosts）"},{"tag":"v.","zh":"主办；主持；做东接待（及物动词，hosted, hosting）"}],"collocations":[{"phrase":"host a conference","zh":"主办会议"},{"phrase":"host a show","zh":"主持节目"},{"phrase":"host country","zh":"主办国；东道国"},{"phrase":"host cell","zh":"宿主细胞"},{"phrase":"web host","zh":"网络主机；网站托管商"},{"phrase":"a host of","zh":"大量的；一大群"}],"forms":[{"label":"单数","form":"host（一位主人；一个宿主）"},{"label":"复数","form":"hosts（多位主人；多个宿主）"},{"label":"动词原形","form":"host（主办；主持）"},{"label":"动词三单","form":"hosts（主办；主持，第三人称单数）"},{"label":"动词过去式","form":"hosted（主办了；主持了）"},{"label":"动词现在分词","form":"hosting（主办中；主持中）"},{"label":"阴性名词","form":"hostess（女主人；女主持人）"}],"derivatives":[{"word":"hosts","pos":"n./v.","zh":"主人（复数）；主办（第三人称单数）"},{"word":"hostess","pos":"n.","zh":"女主人；女主持人；空乘服务员"},{"word":"hosting","pos":"n.","zh":"托管；主办；主持"},{"word":"hosted","pos":"adj.","zh":"托管的；由他人主办或提供的"},{"word":"cohost","pos":"n./v.","zh":"共同主持人；共同主办"},{"word":"hostname","pos":"n.","zh":"主机名（计算机网络用语）"},{"word":"hostel","pos":"n.","zh":"旅舍；青年旅社（与 host 同一拉丁词源）"}],"senses":[{"no":"01","title":"The Person Who Receives Guests","titleCN":"主人：接待客人的人","definition":"a person who receives and entertains guests","definitionCN":"接待并款待客人的人","example":"The host greeted each guest at the door.","exampleCN":"主人在门口迎接每一位客人。","why":"Latin hospes meant both 'guest' and 'host', because one person in the pair holds the duty of hospitality. English kept the receiving side and called that person the host.","whyCN":"拉丁 hospes 同时指「客人」与「主人」，因为这对关系中有一方承担待客之责；英语保留了接待的一方，称此人为 host。"},{"no":"02","title":"The Biological Host","titleCN":"宿主：寄生物或共生体所依附的生物","definition":"an organism on or in which a parasite or symbiont lives","definitionCN":"寄生物或共生体在其体表或体内生活的生物","example":"The host provides the parasite with food and shelter.","exampleCN":"宿主为寄生物提供食物与庇护。","why":"The biological sense, recorded from 1857, keeps the hospitality image but removes the choice: the host receives an uninvited guest and pays for it.","whyCN":"生物学义项记录于 1857 年，它保留待客画面，却去掉了自愿成分：宿主接待一位不请自来的客人，并为此付出代价。"},{"no":"03","title":"The Organiser of an Event","titleCN":"主办方：举办活动的一方","definition":"a person, city or organisation that stages an event","definitionCN":"举办活动的人、城市或组织","example":"The city will host the games next summer.","exampleCN":"这座城市将在明年夏天主办这届运动会。","why":"To host an event is to be the place or the body that receives it. The sense extends the household picture to a city or an institution, which provides the setting for others.","whyCN":"主办活动，就是成为接待活动的场所或机构；这个义项把家庭画面扩展到城市或机构，由它们为他人提供场地。"},{"no":"04","title":"The Presenter","titleCN":"主持人：节目或活动的引导者","definition":"a person who introduces guests and guides a broadcast or a live event","definitionCN":"介绍嘉宾、引导节目或现场活动的人","example":"The host kept the conversation moving for an hour.","exampleCN":"主持人让谈话持续进行了一个小时。","why":"A presenter performs the same social act as a household host: welcoming, introducing, keeping things comfortable. The sense moves from the home to the studio.","whyCN":"主持人和家庭主人做的是同一种社交行为：迎接、介绍、让场面舒适；这个义项从家里移到了演播室。"},{"no":"05","title":"The Computer Host","titleCN":"主机：为其他设备提供服务的计算机","definition":"a computer or server that provides services or resources to other devices","definitionCN":"为其他设备提供服务或资源的计算机或服务器","example":"The database runs on a separate host.","exampleCN":"数据库运行在一台独立的主机上。","why":"In computing the host is the machine that receives the connection and supplies the resource. The hospitality metaphor survives: the host has the room, the client asks for it.","whyCN":"在计算领域，主机是接受连接并提供资源的机器；待客隐喻仍在：主机动有房间，客户端来请求。"},{"no":"06","title":"An Army or a Multitude","titleCN":"军队；大军：古义与宗教用语","definition":"a large organised body, especially an army, in older and biblical usage","definitionCN":"庞大的有组织群体，尤指军队，见于古旧与圣经用法","example":"The old hymn speaks of the heavenly host.","exampleCN":"那首古老赞美诗说到天上的众军。","why":"This host is a different word in origin: it came through Old French from Latin hostis 'stranger, enemy', not from hospes. The two look identical but belong to separate source lines.","whyCN":"这个 host 在词源上是另一个词：它经古法语来自拉丁 hostis「陌生人、敌人」，而不是 hospes；两者外形相同，却属于不同的来源线。"},{"no":"07","title":"A Large Number","titleCN":"大量：a host of 的用法","definition":"a great number of people or things, in the phrase 'a host of'","definitionCN":"大量的人或物，用于 a host of 这一短语","example":"A host of small problems delayed the launch.","exampleCN":"大量小问题延误了发射。","why":"The 'multitude' sense weakened from 'army' to 'a great number'. It is the same source as S6, and it survives mainly inside the fixed phrase.","whyCN":"「众多」义从「军队」弱化而来；它与第 6 个义项同源，主要存活在固定短语中。"},{"no":"08","title":"The Sacramental Wafer","titleCN":"圣体面饼：宗教仪式用语","definition":"the consecrated bread of the Eucharist, usually written with a capital H","definitionCN":"圣餐礼中祝圣过的面饼，通常首字母大写","example":"The priest elevated the Host before the congregation.","exampleCN":"神父在会众面前举起了圣体。","why":"This is a third homograph, from Latin hostia 'sacrifice, victim'. It is unrelated to hospitality and to armies, which is why the capital letter helps readers separate it.","whyCN":"这是第三个同形异源词，来自拉丁 hostia「祭品、牺牲」；它与待客义、军队义都无关，因此首字母大写有助于读者区分。"}],"etymology":{"intro":{"en":"Host looks like one word but is three. The guest-receiver came from Latin hospes; the army came from Latin hostis; the sacramental wafer came from Latin hostia. Only the first supplied the biological and computing senses.","cn":"host 看似一个词，实则有三个来源：接待客人的义来自拉丁 hospes，军队义来自拉丁 hostis，圣体义来自拉丁 hostia；只有第一个来源衍生出生物学与计算机义。"},"items":[{"era":"LATIN HOSPES","en":"Latin hospes (genitive hospitis) meant 'guest, stranger, sojourner, visitor', and also 'host, one bound by ties of hospitality'. The same word covered both sides of the relationship.","cn":"拉丁 hospes（属格 hospitis）意为「客人、陌生人、寄居者、来访者」，也指「主人、受待客义务约束的人」；同一个词覆盖了这段关系的双方。"},{"era":"PIE *GHOS-POT-","en":"Hospes appears to come from a compound *ghos-pot- 'guest-master', joining *ghos-ti- 'stranger, guest, host' with *poti- 'powerful, lord'. The etymological idea is reciprocal duties of hospitality. This is a reconstruction.","cn":"hospes 似来自复合词 *ghos-pot-「客人之主」，由 *ghos-ti-「陌生人、客人、主人」与 *poti-「有权者、主人」组合而成；其词源观念是相互的待客义务。这是重构形式。"},{"era":"ENGLISH, LATE 13TH CENTURY","en":"English host for a person who receives guests is recorded from the late thirteenth century, through Old French oste, hoste. Modern French hôte still means both 'host' and 'guest'.","cn":"英语中「接待客人者」的 host 记录于十三世纪末，经古法语 oste、hoste 传入；现代法语 hôte 仍同时表示「主人」与「客人」。"},{"era":"THE BIOLOGICAL SENSE, 1857","en":"The sense 'animal or plant having a parasite' is recorded from 1857. It was coined when parasitology needed a word for the partner that pays, and it reused the hospitality image.","cn":"「带有寄生物的动物或植物」这一义项记录于 1857 年；寄生虫学需要一个词指付账的一方，于是重新使用了待客画面。"},{"era":"HOST THE ARMY","en":"Host meaning 'a multitude, especially an army' came separately from Old French ost and Latin hostis 'stranger, enemy'. Both roots descend from PIE *ghos-ti-, but through different Latin words, so the two English nouns are not the same word.","cn":"表示「大军、众多」的 host 另经古法语 ost 与拉丁 hostis「陌生人、敌人」传入；两个词根都源自印欧 *ghos-ti-，但经过不同的拉丁词，因此两个英语名词并不是同一个词。"},{"era":"HOST THE WAFER","en":"The Eucharistic Host is recorded from about 1300, from Latin hostia 'sacrifice, victim'. It is a third, unrelated homograph and is usually capitalised in liturgical writing.","cn":"圣餐中的 Host 约 1300 年有记录，来自拉丁 hostia「祭品、牺牲」；这是第三个无关的同形异源词，在礼仪文字中通常大写。"}]},"similar":{"note":{"en":"The first group holds look-alike nouns that belong to different source lines or different roles. The second group holds near-synonyms for the human senses.","cn":"第一组是同形但来源线或角色不同的名词；第二组是人类义项上的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hostess","ipa":"/ˈhəʊstəs/","tag":"noun, feminine","definition":"A female host, or a woman employed to welcome guests. It shares the hospitality root and is not a separate source word.","definitionCN":"女主人，或受雇迎接客人的女性；它与待客词根同源，并非另一个来源词。"},{"word":"hostage","ipa":"/ˈhɒstɪdʒ/","tag":"noun, captive","definition":"A person held as security for another's promise. It comes through the same hospitality root, historically from the idea of a guest handed over as a pledge.","definitionCN":"被扣押以保证他人履约的人；它经同一待客词根而来，历史上源于把客人交作担保的观念。"},{"word":"host (army)","ipa":"/həʊst/","tag":"homograph, different source","definition":"A multitude or army, from Latin hostis 'enemy'. It looks identical to the hospitality host but descends from a different Latin word and must not be confused with it.","definitionCN":"指大军或众多，来自拉丁 hostis「敌人」；它与待客义的 host 外形完全相同，却源自另一个拉丁词，不可混为一谈。"}]},{"heading":"NEAR-SYNONYMS","entries":[{"word":"landlord","ipa":"/ˈlændlɔːd/","tag":"noun, owner who receives","definition":"The owner of a house or room who receives paying tenants. It is narrower than host and involves rent.","definitionCN":"拥有房屋或房间、接待付费租客的人；比 host 窄，且涉及租金。"},{"word":"presenter","ipa":"/prɪˈzentə/","tag":"noun, broadcast host","definition":"A person who introduces and guides a programme. It is the British equivalent of the broadcast sense of host.","definitionCN":"介绍并引导节目的人；在广播义上相当于英式的 host。"},{"word":"server","ipa":"/ˈsɜːvə/","tag":"noun, computing","definition":"A computer or program that provides services to clients. In computing it overlaps with host, though host stresses the machine and server stresses the service.","definitionCN":"为客户端提供服务的计算机或程序；在计算领域与 host 重叠，但 host 强调机器，server 强调服务。"},{"word":"emcee","ipa":"/ˌemˈsiː/","tag":"noun, event host","definition":"An informal word for a master of ceremonies, the person who keeps a live event moving. It is narrower than host and belongs to entertainment.","definitionCN":"指司仪的非正式词，即让现场活动顺畅进行的人；比 host 窄，属于娱乐语境。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin hospes covered both guest and host; English chose the receiving side for host.","cn":"拉丁 hospes 同时指客人与主人；英语为主人这一方选了 host。"},{"en":"The biological host was named in 1857, when parasitology needed a word for the paying partner.","cn":"生物学上的宿主于 1857 年得名，当时寄生虫学需要一个词指付账的一方。"},{"en":"Three homographs: hospitality host, army host, sacramental Host.","cn":"三个同形异源词：待客的主人、军队的大军、圣餐的圣体。"},{"en":"The family runs host, hosts, hostess, hosting, hosted, cohost and hostel.","cn":"同族词包括 host、hosts、hostess、hosting、hosted、cohost、hostel。"},{"en":"The computing host has the room; the client asks for it.","cn":"计算机主机有房间，客户端来请求。"}],"abstract":[{"en":"Picture a door held open, and the cost of the meal falling on the one who holds it.","cn":"想象一扇被扶开的门，而饭钱落在扶门的那个人身上。"},{"en":"Picture a body that did not invite its guest but must still feed it.","cn":"想象一个身体，没有邀请客人，却仍必须供养它。"},{"en":"Picture an old army and a modern server sharing one spelling.","cn":"想象一支古老的军队和一台现代服务器共用一个拼写。"}]},"examples":[{"en":"The host introduced each speaker before the panel began.","cn":"主持人在讨论开始前介绍了每位发言人。"},{"en":"The virus needs a host to copy its genetic material.","cn":"病毒需要宿主来复制它的遗传物质。"},{"en":"A single host can support dozens of parasites.","cn":"一个宿主可以承载数十种寄生物。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"拉丁 hospes（客人／主人）→ 接待客人的一方 → host 主人；引申为宿主、主办方、主持人、主机","word":"host"},"root":"拉丁 hospes（属格 hospitis）「客人、陌生人；主人」→ 古法语 oste/hoste → 英语 host（十三世纪末，指接待客人者）；生物学「宿主」义 1857 年出现；另有两个同形异源词：拉丁 hostis「敌人」→ 大军，拉丁 hostia「祭品」→ 圣体。","sensesIntro":{"en":"Eight senses follow hospitality outward: a person, a body, a city, a studio, a machine, and then two separate homographs, the army and the wafer.","cn":"八个义项沿着待客向外扩展：一个人、一个身体、一座城市、一间演播室、一台机器，最后是两个独立的同形异源词——大军与圣体。"},"semanticMap":{"core":{"en":"CORE IMAGE: an open door and a room kept ready for a guest.","cn":"核心意象：一扇敞开的门，以及为客人备好的房间。"},"chain":["RECEIVE A GUEST","SHELTER A PARASITE","STAGE AN EVENT","GUIDE A PROGRAMME","SERVE A CLIENT","AN ARMY, A WAFER"],"branches":[{"senses":"S1","en":"HOSPITALITY: the root social sense, a person who receives guests.","cn":"待客：根本的社会义，接待客人的人。"},{"senses":"S2","en":"BIOLOGY: the guest is uninvited and the cost is paid by the host's body.","cn":"生物学：客人不请自来，代价由宿主的身体支付。"},{"senses":"S3 · S4","en":"PUBLIC RECEPTION: a city or an institution stages an event, a presenter guides it.","cn":"公共接待：城市或机构举办活动，主持人引导活动。"},{"senses":"S5","en":"MACHINE: a host computer keeps the resource and answers requests.","cn":"机器：主机保存资源并回答请求。"},{"senses":"S6 · S7 · S8","en":"OTHER SOURCES: the army and the multitude come from hostis, and the wafer comes from hostia; all three merely share a spelling.","cn":"其他来源：大军与众多来自 hostis，圣体来自 hostia；三者只是共用拼写。"}]},"affixes":{"intro":{"en":"Host is a borrowed Latin noun, not a built form. Its derivatives come from English endings or from compounds with other nouns.","cn":"host 是借入的拉丁名词，不是拼合形式；它的派生词来自英语词尾，或与其他名词的复合。"},"latinIntro":{"en":"Latin supplied hospes for the hospitality word and hostis for the army word. The identity of spelling is historical accident, not shared etymology.","cn":"拉丁语为待客义提供了 hospes，为军队义提供了 hostis；拼写相同是历史偶然，不是共同词源。"},"items":[{"word":"host","structure":"Latin hospes (guest/host) through Old French hoste","meaning":"one who receives guests","meaningCN":"接待客人者","example":"The host welcomed the guests.","exampleCN":"主人欢迎了客人。"},{"word":"hosts","structure":"host + plural -s","meaning":"more than one host","meaningCN":"不止一位主人或一个宿主","example":"The hosts shared the cost.","exampleCN":"主人们分担了费用。"},{"word":"hostess","structure":"host + -ess (feminine)","meaning":"a female host","meaningCN":"女主人","example":"The hostess showed us to the table.","exampleCN":"女主人把我们引到桌边。"},{"word":"hosting","structure":"host + -ing (action noun)","meaning":"the act of receiving or providing","meaningCN":"接待或提供的动作","example":"Hosting the event cost the city millions.","exampleCN":"主办这次活动花了城市数百万。"},{"word":"hosted","structure":"host + -ed (past participle)","meaning":"received or provided by a host","meaningCN":"由主人接待或由主机提供的","example":"The service is hosted abroad.","exampleCN":"该服务托管在海外。"},{"word":"cohost","structure":"co- (together) + host","meaning":"one who hosts with another","meaningCN":"与他人共同主持或主办者","example":"She cohosted the evening show.","exampleCN":"她共同主持了晚间节目。"},{"word":"hostname","structure":"host + name","meaning":"the name of a networked machine","meaningCN":"联网机器的名称","example":"The hostname resolved in a second.","exampleCN":"主机名在一秒内解析完成。"},{"word":"hostel","structure":"Old French hostel < Latin hospitale (guest-house)","meaning":"a lodging for travellers","meaningCN":"供旅人住宿的旅舍","example":"The hostel was full of students.","exampleCN":"旅舍里住满了学生。"}],"latinEntries":[{"word":"hospes","structure":"hospes, hospitis (m., third declension)","meaning":"guest, stranger; host bound by hospitality","meaningCN":"客人、陌生人；受待客义务约束的主人"},{"word":"hostis","structure":"hostis, -is (m./f., third declension)","meaning":"stranger, foreigner; enemy","meaningCN":"陌生人、外国人；敌人"},{"word":"hostia","structure":"hostia, -ae (f., first declension)","meaning":"sacrifice, victim; the consecrated wafer","meaningCN":"祭品、牺牲；祝圣的面饼"}]}},{"word":"host organism","ipa_uk":"/ˌhəʊst ˈɔːɡənɪzəm/","ipa_us":"/ˌhoʊst ˈɔːrɡənɪzəm/","definition_zh":"宿主生物；寄生物或共生体所依附、并在其中生活的那一个生物","definition_en":"the organism in or on which a parasite, symbiont or research agent lives","core_image":"培养皿中央一只小鼠，体内标出寄生物的路径，周围是记录宿主状态的仪器","scene":"Researchers used a mouse as the host organism for the parasite.","sceneCN":"这里 host organism 是「宿主生物」（第 1 个义项：寄生物所依附的生物）；句意：研究者用小鼠作为这种寄生物的宿主生物。图中可辨识物件：小鼠、体内寄生物路径的标记、监测仪器。","pos":[{"tag":"n.","zh":"宿主生物（可数名词短语，复数 host organisms）；由 host「宿主」与 organism「生物体」组合而成"}],"collocations":[{"phrase":"natural host organism","zh":"天然宿主生物"},{"phrase":"model host organism","zh":"模式宿主生物"},{"phrase":"host organism range","zh":"宿主生物范围"},{"phrase":"genetically modified host organism","zh":"转基因宿主生物"},{"phrase":"host organism immune response","zh":"宿主生物免疫应答"},{"phrase":"host organism and parasite","zh":"宿主生物与寄生物"}],"forms":[{"label":"单数","form":"host organism（一个宿主生物）"},{"label":"复数","form":"host organisms（多个宿主生物）"},{"label":"组成词一","form":"host（宿主；主人）"},{"label":"组成词二","form":"organism（生物体）"},{"label":"形容词形式","form":"host-organism（作定语时用连字符，如 host-organism specificity）"}],"derivatives":[{"word":"host","pos":"n.","zh":"宿主；主人"},{"word":"organism","pos":"n.","zh":"生物体；有机体"},{"word":"host organisms","pos":"n.","zh":"宿主生物（复数）"},{"word":"host cell","pos":"n.","zh":"宿主细胞（比宿主生物更具体的层次）"},{"word":"host range","pos":"n.","zh":"宿主范围"},{"word":"host specificity","pos":"n.","zh":"宿主专一性"},{"word":"model organism","pos":"n.","zh":"模式生物（用于研究的代表性物种）"}],"senses":[{"no":"01","title":"The Organism That Shelters a Parasite","titleCN":"寄主生物：寄生物所依附的生物","definition":"the organism in or on which a parasite lives and feeds","definitionCN":"寄生物在其体内或体表生活取食的生物","example":"The host organism showed no symptoms for the first week.","exampleCN":"宿主生物在第一周没有表现出症状。","why":"Host organism adds organism to host to make clear that a whole living body, not a cell or a tissue, is the partner. The phrase is used when the biological unit matters.","whyCN":"host organism 在 host 后加上 organism，以明确作为伙伴的是一个完整生物体，而不是一个细胞或组织；当生物学单位很重要时就用这个短语。"},{"no":"02","title":"The Partner of a Symbiont","titleCN":"共生宿主生物：互利或共栖的一方","definition":"the larger partner that houses a symbiont, whether the relation is mutual or one-sided","definitionCN":"容纳共生体的较大一方，不论关系是互利还是单向","example":"The coral is the host organism for the algae that live in its tissue.","exampleCN":"珊瑚是生活在其组织中的藻类的宿主生物。","why":"Symbiosis is neutral about benefit, so host organism can name the sheltering side even when no harm occurs. This keeps the term wider than 'host of a parasite'.","whyCN":"共生关系对益处保持中立，因此即使没有伤害，host organism 也可以命名提供居所的一方；这使该术语比「寄生物的宿主」更宽。"},{"no":"03","title":"The Model Host in Research","titleCN":"模式宿主生物：实验中的代表物种","definition":"a standard organism used in the laboratory to study a parasite or a symbiont","definitionCN":"实验室中用来研究寄生物或共生体的标准生物","example":"The mouse is a model host organism for malaria research.","exampleCN":"小鼠是疟疾研究中的模式宿主生物。","why":"Model marks a research role: the organism stands in for humans or for a wild species. The phrase then names a tool, not a natural relationship.","whyCN":"「模式」标记一种研究角色：这个生物替人类或野生种出场；此时该短语命名的是工具，而不是自然关系。"},{"no":"04","title":"Host Range","titleCN":"宿主生物范围：能感染哪些物种","definition":"the set of species that a parasite or pathogen can use as a host","definitionCN":"寄生物或病原能够利用为宿主的物种集合","example":"The host organism range of the fungus includes three tree families.","exampleCN":"这种真菌的宿主生物范围包括三个树科。","why":"Range turns the phrase into a measurable property: narrow or broad. A parasite that can use many host organisms is a generalist; one that cannot is a specialist.","whyCN":"「范围」把该短语变成可测量的属性：窄或宽；能利用许多宿主生物的寄生物是泛化种，不能的是专化种。"},{"no":"05","title":"The Host Immune Response","titleCN":"宿主生物免疫应答：宿主的防御","definition":"the immune reaction of the host organism against an invader","definitionCN":"宿主生物对入侵者的免疫反应","example":"The host organism immune response cleared the infection in ten days.","exampleCN":"宿主生物的免疫应答在十天内清除了感染。","why":"Here the phrase marks which side of the relationship is acting: the host organism defends, the parasite attacks. It is the standard way to avoid saying 'the host's response' in ambiguous prose.","whyCN":"这里该短语标出关系中正在行动的一方：宿主生物防御，寄生物进攻；在容易歧义的文字中，它可避免使用「宿主的反应」这一含糊说法。"},{"no":"06","title":"The Host as Habitat","titleCN":"宿主生物作为生境：寄生物的家","definition":"the host organism considered as the physical habitat of its residents","definitionCN":"把宿主生物视为其居住者的物理生境","example":"For the gut worm, the host organism is a warm, food-rich habitat.","exampleCN":"对肠道蠕虫来说，宿主生物就是一个温暖、食物丰富的生境。","why":"Ecology treats the host body as a place with zones, resources and competitors. The phrase thus shifts from partner to landscape, which is why parasitologists speak of microhabitats.","whyCN":"生态学把宿主身体视为一个有分区、有资源、有竞争者的场所；该短语于是从伙伴转为景观，这也是寄生虫学家会讨论微生境的原因。"},{"no":"07","title":"A Modified Host","titleCN":"转基因宿主生物：被改造的宿主","definition":"a host organism whose genome has been altered for research or production","definitionCN":"基因组为研究或生产而被改造的宿主生物","example":"The modified host organism produced the viral protein on demand.","exampleCN":"这种改造过的宿主生物可以按需生产病毒蛋白。","why":"Biotechnology edits the host rather than the parasite. The phrase marks that the receiving body has been engineered, so the relationship is now partly designed.","whyCN":"生物技术改造的是宿主而不是寄生物；该短语标出这个接受方的身体已被工程化，因此这段关系现在部分是被设计出来的。"},{"no":"08","title":"The Production Host","titleCN":"发酵宿主生物：工业生产的载体","definition":"an organism used as the host for fermentation or for making a product","definitionCN":"被用作发酵或生产产品载体的生物","example":"The company chose a yeast as the host organism for the new process.","exampleCN":"公司选择一种酵母作为新工艺的宿主生物。","why":"In industry the host is the cell or body that carries the introduced genes or the fermentation. The hospitality picture returns in a technical form: the host provides the machinery, the product is the guest.","whyCN":"在工业中，宿主是携带导入基因或承担发酵的细胞或生物体；待客画面以技术形式回归：宿主提供机器，产品是客人。"}],"etymology":{"intro":{"en":"Host organism is not an inherited word but a modern English compound of two borrowed nouns. Its history is the joining of a hospitality word to a word for a living body.","cn":"host organism 不是承袭下来的词，而是两个借入名词组成的现代英语复合短语；它的历史，就是「待客之词」与「生物体之词」的结合。"},"items":[{"era":"HOST, FROM HOSPES","en":"Host came through Old French from Latin hospes 'guest, host'. The biological sense 'animal or plant having a parasite' is recorded from 1857.","cn":"host 经古法语来自拉丁 hospes「客人、主人」；其「带有寄生物的动物或植物」这一生物学义项记录于 1857 年。"},{"era":"ORGANISM, FROM ORGANON","en":"Organism is recorded from the 1660s for 'organic structure'; the sense 'living animal or plant' appears by 1825, translating German Organismus. It rests on Greek organon 'tool, instrument'.","cn":"organism 于十七世纪六十年代记录为「有机结构」，到 1825 年才出现「活的动物或植物」义，译自德语 Organismus；其基础是希腊 organon「工具、器具」。"},{"era":"THE COMPOUND","en":"The phrase host organism is a later scientific combination of these two nouns. It has no classical etymon: the words were joined in modern technical English to make the unit of the relationship explicit.","cn":"host organism 是这两个名词后来在科学英语中的组合；它没有古典词源：这两个词是在现代技术英语中并置，以明确这段关系的单位。"},{"era":"WHY THE PHRASE EXISTS","en":"Host alone can mean a person or a computer. Adding organism restricts the reading to a living body, which matters when a paper compares a host cell, a host tissue and a whole host organism.","cn":"单说 host 可以指人或计算机；加上 organism 就把读法限制为生物体，这在论文比较宿主细胞、宿主组织与整个宿主生物时很重要。"},{"era":"THE MODEL HOST","en":"Twentieth-century laboratory science made model host organism a standard phrase, naming species such as mice, flies and zebrafish that stand in for others in experiments.","cn":"二十世纪实验室科学使「模式宿主生物」成为标准短语，指小鼠、果蝇、斑马鱼等实验中的代表物种。"},{"era":"THE INDUSTRIAL HOST","en":"Biotechnology extended the phrase to production: a yeast or a bacterium can be a host organism for an introduced gene. The hospitality metaphor survives in a purely technical register.","cn":"生物技术把该短语扩展到生产：酵母或细菌可以是导入基因的宿主生物；待客隐喻在纯技术语域中继续存在。"}]},"similar":{"note":{"en":"The first group separates the phrase from its two parts and from a narrower unit. The second group holds technical host roles that are often confused in parasitology.","cn":"第一组区分该短语与其两个组成词，以及一个更窄的单位；第二组是寄生虫学中常被混淆的宿主角色术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"host cell","ipa":"/həʊst sel/","tag":"noun, narrower unit","definition":"The single cell in which a virus or intracellular parasite replicates. It is a level below the whole host organism.","definitionCN":"病毒或胞内寄生物在其中复制的单个细胞；它是比整个宿主生物低一层的单位。"},{"word":"organism","ipa":"/ˈɔːɡənɪzəm/","tag":"noun, living body","definition":"Any living body. It says nothing about hosting, so the phrase needs host to mark the role.","definitionCN":"任何活的生物体；它不涉及宿主角色，因此必须加 host 才能标出这一角色。"},{"word":"host","ipa":"/həʊst/","tag":"noun, the role","definition":"The receiving partner. Alone it can also mean a person or a computer, which is why organism is added for clarity.","definitionCN":"指接受的一方；单独使用时也可指人或计算机，因此加上 organism 以求明确。"}]},{"heading":"NEAR-SYNONYMS","entries":[{"word":"reservoir host","ipa":"/rɪˈzɜːvɔɪə həʊst/","tag":"noun, long-term source","definition":"A host population in which a pathogen persists and from which it can spread. It is a role within the host category, not a synonym for any host organism.","definitionCN":"病原在其中长期存续、并可从中扩散的宿主种群；它是宿主类别中的一种角色，并不等于任意宿主生物。"},{"word":"definitive host","ipa":"/dɪˈfɪnɪtɪv həʊst/","tag":"noun, sexual stage","definition":"The host in which a parasite reaches sexual maturity. It is defined by the parasite's life cycle, not by size or immunity.","definitionCN":"寄生物在其中达到性成熟的宿主；它按寄生物生活史来定义，而不是按大小或免疫状态。"},{"word":"intermediate host","ipa":"/ɪnˈterəmediət həʊst/","tag":"noun, larval stage","definition":"The host in which a parasite passes its larval or asexual stage. It is the necessary middle of a multi-host cycle.","definitionCN":"寄生物在其中度过幼虫或无性阶段的宿主；它是多宿主生活史中必需的中间环节。"},{"word":"vector","ipa":"/ˈvektə/","tag":"noun, carrier","definition":"An organism that carries a pathogen from one host to another. It transmits rather than shelters the long-term relationship.","definitionCN":"把病原从一个宿主带到另一个宿主的生物；它负责传播，而不是长期容纳这段关系。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"host + organism: the receiving role plus a whole living body, joined for clarity.","cn":"host（接受角色）+ organism（完整生物体）：为明确而并置。"},{"en":"Host got its biological sense in 1857; organism got its living-body sense by 1825.","cn":"host 的生物学义 1857 年出现，organism 的生物体义 1825 年出现。"},{"en":"The phrase sits above host cell: a cell is a part, an organism is the whole.","cn":"该短语位于宿主细胞之上：细胞是部分，生物体是整体。"},{"en":"The family runs host organism, host, organism, host cell, host range and host specificity.","cn":"同族短语包括 host organism、host、organism、host cell、host range、host specificity。"},{"en":"In parasitology the roles are precise: reservoir, definitive, intermediate, vector.","cn":"在寄生虫学中角色很精确：储存宿主、终宿主、中间宿主、传播媒介。"}],"abstract":[{"en":"Picture a house with a guest inside, and a label on the house saying 'organism'.","cn":"想象一栋房子里住着一位客人，房子上贴着「生物体」的标签。"},{"en":"Picture a mouse standing in for a whole species in a laboratory cage.","cn":"想象一只小鼠在实验室笼子里代表整个物种。"},{"en":"Picture a yeast cell carrying a foreign gene like a suitcase.","cn":"想象一个酵母细胞像提着行李箱一样携带一段外源基因。"}]},"examples":[{"en":"The host organism must be kept alive for the parasite to complete its cycle.","cn":"必须让宿主生物存活，寄生物才能完成生活史。"},{"en":"A narrow host organism range makes a pathogen easier to contain.","cn":"宿主生物范围窄，使病原更容易被控制。"},{"en":"The engineered host organism secreted the enzyme into the broth.","cn":"改造过的宿主生物把这种酶分泌到培养液中。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"host（宿主）+ organism（生物体）→ 作为宿主的生物体 → host organism 宿主生物","word":"host organism"},"root":"拉丁 hospes「客人、主人」→ 古法语 hoste → 英语 host（十三世纪末）；希腊 organon「工具」→ 医学拉丁 organismus → 英语 organism（1660s 有机结构；1825 生物体）；host 的生物学义 1857 年出现，后与 organism 并置成 host organism。","sensesIntro":{"en":"Eight senses move from the parasite's partner to the symbiont's partner, the research model, the measurable range, the immune side, the habitat view, the edited host and the industrial host.","cn":"八个义项从寄生物的伙伴，走向共生体的伙伴、研究模型、可测范围、免疫一方、生境视角、被改造的宿主与工业宿主。"},"semanticMap":{"core":{"en":"CORE IMAGE: a whole living body with a smaller resident inside it.","cn":"核心意象：一个完整生物体，体内住着更小的居住者。"},"chain":["SHELTERS A PARASITE","SHELTERS A SYMBIONT","STANDS IN RESEARCH","HAS A RANGE","DEFENDS ITSELF","BECOMES A HABITAT"],"branches":[{"senses":"S1 · S2","en":"PARTNERSHIP: the same receiving body serves a parasite or a symbiont, and the phrase stays neutral about benefit.","cn":"伙伴关系：同一个接受方身体既可服务寄生物也可服务共生体，短语对益处保持中立。"},{"senses":"S3 · S7 · S8","en":"DESIGN: research, genetic editing and industry choose the host rather than merely finding it.","cn":"设计：研究、基因编辑与工业是选择宿主，而不只是发现宿主。"},{"senses":"S4","en":"MEASURE: host range turns the relationship into a countable set of species.","cn":"测量：宿主范围把这段关系变成可计数的物种集合。"},{"senses":"S5","en":"DEFENCE: the host organism is also an actor that fights back.","cn":"防御：宿主生物也是一个会反击的行动者。"},{"senses":"S6","en":"LANDSCAPE: ecology sees the host body as a habitat with zones and resources.","cn":"景观：生态学把宿主身体看作有分区与资源的生境。"}]},"affixes":{"intro":{"en":"Host organism is a two-noun compound. Neither part is a prefix or suffix; the interest lies in how the two borrowed nouns restrict each other.","cn":"host organism 是双名词复合短语；两部分都不是前缀或后缀，值得注意之处在于两个借入名词如何互相限定。"},"latinIntro":{"en":"Latin hospes supplied host and Greek organon, through Medical Latin organismus, supplied organism. The combination itself is modern English, so no single Latin phrase stands behind it.","cn":"拉丁 hospes 提供了 host，希腊 organon 经医学拉丁 organismus 提供了 organism；组合本身是现代英语，因此背后没有单一拉丁短语。"},"items":[{"word":"host organism","structure":"host (receiving body) + organism (living body)","meaning":"the living body that shelters a resident","meaningCN":"容纳居住者的生物体","example":"The host organism was monitored daily.","exampleCN":"宿主生物每天受到监测。"},{"word":"host","structure":"Latin hospes through Old French","meaning":"the receiving role","meaningCN":"接受角色","example":"The host provided the habitat.","exampleCN":"宿主提供了生境。"},{"word":"organism","structure":"Greek organon through Medical Latin organismus","meaning":"a living body","meaningCN":"活的生物体","example":"The organism weighed two grams.","exampleCN":"该生物体重两克。"},{"word":"host cell","structure":"host + cell (narrower unit)","meaning":"the cell that shelters a virus","meaningCN":"容纳病毒的细胞","example":"The host cell lysed within hours.","exampleCN":"宿主细胞在数小时内裂解。"},{"word":"host range","structure":"host + range (set of species)","meaning":"the species a parasite can use","meaningCN":"寄生物可利用的物种集合","example":"The host range includes rodents.","exampleCN":"宿主范围包括啮齿类。"},{"word":"host specificity","structure":"host + specificity (restriction)","meaning":"the degree to which a parasite is limited to certain hosts","meaningCN":"寄生物局限于某些宿主的程度","example":"Host specificity kept the fungus in one tree genus.","exampleCN":"宿主专一性使这种真菌局限于一个树属。"},{"word":"model organism","structure":"model + organism","meaning":"a species used to represent others in research","meaningCN":"研究中代表其他物种的物种","example":"The fly is a classic model organism.","exampleCN":"果蝇是经典的模式生物。"},{"word":"microbiome","structure":"micro- + biome","meaning":"the community living on or in a host","meaningCN":"生活在宿主体表或体内的群落","example":"The skin microbiome varies by site.","exampleCN":"皮肤微生物组因部位而异。"}],"latinEntries":[{"word":"hospes","structure":"hospes, hospitis (m., third declension)","meaning":"guest, stranger; host","meaningCN":"客人、陌生人；主人"},{"word":"organismus","structure":"organismus, -i (m., Medical Latin, from Greek organon)","meaning":"organized living body","meaningCN":"有组织的生物体"}]}},{"word":"symbiosis","ipa_uk":"/ˌsɪmbaɪˈəʊsɪs/","ipa_us":"/ˌsɪmbaɪˈoʊsɪs/","definition_zh":"共生；两种不同生物长期共同生活的状态或关系","definition_en":"a long-term living together of two different organisms, often with benefit to both","core_image":"珊瑚与体内的藻类并列，彼此交换养分，箭头双向流动","scene":"The symbiosis between the coral and its algae keeps both alive in poor water.","sceneCN":"这里 symbiosis 是「共生」（第 1 个义项：两种生物长期共同生活）；句意：珊瑚与其藻类的共生让两者在贫瘠的水中都能存活。图中可辨识物件：珊瑚、体内的藻类、双向的养分箭头。","pos":[{"tag":"n.","zh":"共生；共生关系（可数或不可数，复数 symbioses）"}],"collocations":[{"phrase":"symbiosis between","zh":"……之间的共生关系"},{"phrase":"mutual symbiosis","zh":"互利共生"},{"phrase":"obligate symbiosis","zh":"专性共生"},{"phrase":"gut symbiosis","zh":"肠道共生"},{"phrase":"industrial symbiosis","zh":"产业共生"},{"phrase":"symbiosis with","zh":"与……的共生"}],"forms":[{"label":"单数","form":"symbiosis（一种共生关系）"},{"label":"复数","form":"symbioses（多种共生关系）"},{"label":"形容词形式","form":"symbiotic（共生的）"},{"label":"参与方名词","form":"symbiont（共生体；共生双方之一）"},{"label":"副词形式","form":"symbiotically（以共生方式地）"},{"label":"动词形式（后构）","form":"symbiose（形成共生；1960 年后构）"}],"derivatives":[{"word":"symbioses","pos":"n.","zh":"共生关系（复数）"},{"word":"symbiotic","pos":"adj.","zh":"共生的"},{"word":"symbiont","pos":"n.","zh":"共生体；共生双方之一"},{"word":"symbiotically","pos":"adv.","zh":"以共生方式地"},{"word":"symbiose","pos":"v.","zh":"形成共生（后构动词）"},{"word":"endosymbiosis","pos":"n.","zh":"内共生（一种生物生活在另一种细胞内部）"},{"word":"mutualism","pos":"n.","zh":"互利共生（共生中的互利类型）"}],"senses":[{"no":"01","title":"Living Together","titleCN":"共生：两种生物长期共同生活","definition":"a close and long-term living together of two different organisms","definitionCN":"两种不同生物密切而长期地共同生活","example":"Symbiosis can last for the whole life of both partners.","exampleCN":"共生可以持续双方的一生。","why":"The word joins Greek syn- 'together' and bios 'life'. Its core is cohabitation, not benefit; benefit is a later refinement, which is why the term can cover several kinds of relationship.","whyCN":"这个词由希腊 syn-「一起」与 bios「生命」构成；核心是共同居住，而不是获益；获益是后来的细化，因此该术语能涵盖多种关系。"},{"no":"02","title":"Mutual Benefit","titleCN":"互利共生：双方都获益","definition":"a symbiotic relationship in which both partners benefit","definitionCN":"双方都从中获益的共生关系","example":"The symbiosis between the fig and its pollinator benefits both.","exampleCN":"无花果与其传粉者的共生使双方受益。","why":"In everyday biology symbiosis usually means mutualism: each side gives something the other needs. The word has narrowed from cohabitation to profitable cohabitation.","whyCN":"在日常生物学中，symbiosis 通常指互利共生：每一方都给出对方需要的东西；这个词已从「共同居住」收窄为「有利可图地共同居住」。"},{"no":"03","title":"One-Sided Cohabitation","titleCN":"偏利共生：一方获益、一方无碍","definition":"a loose use of symbiosis for a relationship in which one partner gains and the other is unaffected","definitionCN":"宽泛地用共生指一方获益、另一方不受影响的关系","example":"Some authors call the barnacle's ride a symbiosis, though only the barnacle gains.","exampleCN":"有些作者把藤壶的搭车称为共生，虽然只有藤壶获益。","why":"Because the root sense is only 'living together', the term can be stretched to commensalism. Careful writers then add a qualifier, such as commensal symbiosis, to avoid implying mutual gain.","whyCN":"由于词根义只是「共同生活」，该术语可以被扩展到偏利共生；严谨的作者会加限定语，如共栖共生，以免暗示双方获利。"},{"no":"04","title":"Parasitism as Cohabitation","titleCN":"寄生性共生：广义共生中的寄生","definition":"the broad sense of symbiosis that includes parasitism, since the partners still live together","definitionCN":"把寄生也纳入的广义共生，因为双方仍共同生活","example":"In the broad sense, symbiosis includes parasitism as one extreme.","exampleCN":"在广义上，共生把寄生作为其中一个极端包含在内。","why":"If symbiosis means only cohabitation, a parasite and its host qualify. This broad definition is common in ecology textbooks, while medical writing usually keeps the narrower mutual-benefit sense.","whyCN":"如果共生只指共同居住，寄生物与宿主也符合条件；这一广义定义在生态学教材中常见，而医学写作通常保留较窄的互利义。"},{"no":"05","title":"Social Symbiosis","titleCN":"社会共生：群体之间的相互依存","definition":"a mutually dependent relationship between social groups or institutions","definitionCN":"社会群体或机构之间相互依赖的关系","example":"The city describes the symbiosis between its universities and its industry.","exampleCN":"这座城市用「共生」来描述大学与产业之间的关系。","why":"The biological word was given a wider, non-biological sense by 1921. It keeps the picture of two parties living together and each supplying what the other lacks.","whyCN":"这个生物学词在 1921 年之后被赋予更宽的非生物学含义；它保留了双方共同生活、彼此补足所缺的画面。"},{"no":"06","title":"Industrial Symbiosis","titleCN":"产业共生：企业间交换废料与能源","definition":"a network in which firms use one another's waste, heat or by-products","definitionCN":"企业互相利用对方的废物、热能或副产品的网络","example":"Industrial symbiosis turned one factory's waste heat into another's power.","exampleCN":"产业共生把一家工厂的废热变成了另一家的动力。","why":"Here the partners are firms and the exchanged resource is matter or energy. The term is a deliberate ecological metaphor: what one organism excretes, another consumes.","whyCN":"这里伙伴是企业，交换的资源是物质或能量；这个术语是有意使用的生态隐喻：一个生物排出的，正是另一个生物摄入的。"},{"no":"07","title":"Ecological Partnership","titleCN":"生态伙伴关系：生态系统层面的互补","definition":"a partnership between species or processes that keeps an ecosystem functioning","definitionCN":"维持生态系统运转的物种或过程之间的伙伴关系","example":"The symbiosis of grazers and grasses keeps the savanna open.","exampleCN":"食草动物与草的共生让稀树草原保持开阔。","why":"The sense scales the relationship from two organisms to a whole system. It is still cohabitation, but the unit is now the ecosystem and the benefit is stability.","whyCN":"这个义项把关系从两个生物扩展到整个系统；它仍是共同生活，但单位变成了生态系统，收益变成了稳定性。"},{"no":"08","title":"Technology and Society","titleCN":"技术与社会的共生：相互塑造","definition":"a mutually shaping relationship between a technology and the society that uses it","definitionCN":"一项技术与其使用社会之间相互塑造的关系","example":"The book studies the symbiosis of mobile phones and urban life.","exampleCN":"这本书研究手机与城市生活的共生。","why":"This is the furthest extension: neither side merely hosts the other, each changes the other. It keeps the core idea of living together while dropping the biological host.","whyCN":"这是最远的引申：双方都不只是容纳对方，而是互相改变；它保留了共同生活的核心观念，却去掉了生物学宿主。"}],"etymology":{"intro":{"en":"Symbiosis was borrowed from Greek in 1876 as a biological term, after an earlier English sense of 'communal life'. Its meaning has oscillated between mere cohabitation and mutual benefit ever since.","cn":"symbiosis 于 1876 年作为生物学词从希腊语借入，而在此之前英语已有「共同生活」的旧义；此后它的含义便在「单纯同居」与「互利」之间摆动。"},"items":[{"era":"GREEK SYMBIOSIS","en":"Greek symbiosis meant 'a living together', from symbioun 'to live together' and symbios 'one living together, partner, companion, husband or wife'. The root idea is shared life, not necessarily shared benefit.","cn":"希腊 symbiosis 意为「共同生活」，来自 symbioun「一起生活」与 symbios「共同生活者、伙伴、同伴、丈夫或妻子」；其词根观念是共享生活，不一定是共享利益。"},{"era":"SYN- AND BIOS","en":"Syn- 'together' is the assimilated form of the prefix before labials, and bios means 'life, course of life'. The same bios underlies biology and microbe.","cn":"syn-「一起」是该前缀在唇音前发生同化的形式；bios 意为「生命、生命历程」。同一个 bios 也构成 biology 与 microbe。"},{"era":"EARLIER ENGLISH SENSE, 1620s","en":"An English sense 'communal or social life' is recorded in the 1620s, long before the biological use. It shows that the word's social application is not a modern metaphor but an old branch.","cn":"英语中「共同或社会生活」的义项记录于十七世纪二十年代，远早于生物学用法；这说明该词的社会用法不是现代隐喻，而是一条古老的支线。"},{"era":"BIOLOGICAL TERM, 1876","en":"The biological sense 'union for life of two different organisms based on mutual benefit' is recorded from 1876. The definition already included benefit, though later textbooks widened it again.","cn":"「两种不同生物基于互利而终身结合」的生物学义项记录于 1876 年；这个定义已经包含获益，尽管后来的教材又把它拓宽。"},{"era":"SYMBIONT AND SYMBIOTIC","en":"Symbiont, for either partner, is recorded from 1887, earlier in German. Symbiotic is recorded from 1882, formed with -ic; its use for human activities dates from 1951.","cn":"指任一方的 symbiont 记录于 1887 年，德语中更早；symbiotic 记录于 1882 年，由 -ic 构成，其用于人类活动则始于 1951 年。"},{"era":"THE MODERN SPECTRUM","en":"Ecology now places mutualism, commensalism and parasitism on a spectrum, sometimes calling all three symbiosis. The word's breadth is inherited from its Greek root, not invented by recent authors.","cn":"现代生态学把互利、偏利与寄生放在一个谱系上，有时把三者都称为共生；这个词的宽泛性承自希腊词根，而不是近代作者发明的。"}]},"similar":{"note":{"en":"The first group separates the relationship noun from its participants and adjective. The second group holds the three ecological relations that sit on the same spectrum.","cn":"第一组区分关系名词与参与方、形容词；第二组是同一谱系上的三种生态关系。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"symbiont","ipa":"/sɪmˈbaɪɒnt/","tag":"noun, participant","definition":"Either partner in a symbiosis. The relationship is symbiosis; the member is a symbiont.","definitionCN":"共生关系中的任一方；关系本身是 symbiosis，成员则是 symbiont。"},{"word":"symbiotic","ipa":"/ˌsɪmbaɪˈɒtɪk/","tag":"adjective","definition":"Of or relating to symbiosis. It describes the relationship, while symbiosis names it.","definitionCN":"指共生的或与共生有关的；它描述这种关系，而 symbiosis 命名这种关系。"},{"word":"symbiotically","ipa":"/ˌsɪmbaɪˈɒtɪkli/","tag":"adverb","definition":"In a symbiotic manner. It modifies a verb, as in 'the two species live symbiotically'.","definitionCN":"以共生方式地；修饰动词，如「两个物种以共生方式生活」。"}]},{"heading":"NEAR-SYNONYMS","entries":[{"word":"mutualism","ipa":"/mjuːˈtjuːəlɪzəm/","tag":"noun, both benefit","definition":"The type of symbiosis in which both partners gain. It is a narrower and more precise term than symbiosis.","definitionCN":"双方都获益的那一类共生；它比 symbiosis 更窄、更精确。"},{"word":"commensalism","ipa":"/kəˈmensəlɪzəm/","tag":"noun, one gains, one unaffected","definition":"A relationship in which one partner benefits and the other is neither helped nor harmed. It is one point on the symbiosis spectrum.","definitionCN":"一方获益、另一方既不受益也不受损的关系；它是共生谱系上的一个点。"},{"word":"parasitism","ipa":"/ˈpærəsaɪtɪzəm/","tag":"noun, one benefits, one harmed","definition":"A relationship in which one partner gains at the other's expense. In the broad definition it counts as symbiosis; in the narrow one it does not.","definitionCN":"一方以另一方为代价获益的关系；按广义定义它算共生，按狭义定义则不算。"},{"word":"cooperation","ipa":"/kəʊˌɒpəˈreɪʃən/","tag":"noun, working together","definition":"Working together for a shared aim. It describes behaviour and need not be a long-term biological union.","definitionCN":"为共同目标一起工作；它描述行为，不一定是长期的生物学结合。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"syn- 'together' + bios 'life': living together, before any question of profit.","cn":"syn-「一起」+ bios「生命」：先讲共同生活，再谈是否获利。"},{"en":"The biological term dates from 1876; the social sense is older, from the 1620s.","cn":"生物学义项始于 1876 年；社会义更早，可追到十七世纪二十年代。"},{"en":"The family runs symbiosis, symbioses, symbiotic, symbiotically, symbiont and endosymbiosis.","cn":"同族词包括 symbiosis、symbioses、symbiotic、symbiotically、symbiont、endosymbiosis。"},{"en":"The spectrum runs mutualism, commensalism, parasitism; symbiosis can name the whole range.","cn":"谱系依次为互利、偏利、寄生；symbiosis 可以命名整个范围。"},{"en":"The plural is symbioses, following the Greek pattern, not symbiosises.","cn":"复数是 symbioses，遵循希腊语模式，而不是 symbiosises。"}],"abstract":[{"en":"Picture two creatures sharing one room, each bringing something the other cannot make.","cn":"想象两个生物共用一间房，各自带来对方无法制造的东西。"},{"en":"Picture a factory's chimney feeding another factory's furnace.","cn":"想象一家工厂的烟囱为另一家工厂的炉子供热。"},{"en":"Picture a phone and a city changing each other until neither is the same.","cn":"想象手机与城市互相改变，直到两者都不再是原来的样子。"}]},"examples":[{"en":"Symbiosis allowed the plant to colonise dry ground.","cn":"共生让这种植物得以拓殖干旱土地。"},{"en":"The symbiosis of fungi and roots is older than trees.","cn":"真菌与根的共生比树木本身还要古老。"},{"en":"Industrial symbiosis cut both waste and cost in the park.","cn":"产业共生同时降低了园区内的废物与成本。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"syn-（一起）+ bios（生命）→ 共同生活 → symbiosis 共生","word":"symbiosis"},"root":"希腊 syn-「一起」（唇音前同化为 sym-）+ bios「生命」→ symbiosis「共同生活」→ 英语 symbiosis（1620s 有「社会生活」义；1876 年成为生物学词）。","sensesIntro":{"en":"Eight senses begin with cohabitation and then spread across the ecological spectrum, social partnership, industry, ecosystems and technology.","cn":"八个义项以共同居住为起点，随后铺展到生态谱系、社会伙伴、产业、生态系统与技术。"},"semanticMap":{"core":{"en":"CORE IMAGE: two organisms side by side, arrows of exchange running both ways.","cn":"核心意象：并排的两个生物，交换的箭头朝两个方向流动。"},"chain":["LIVE TOGETHER","BOTH GAIN","ONE GAINS ONLY","ONE PAYS","GROUPS DEPEND","SYSTEMS COUPLE"],"branches":[{"senses":"S1","en":"COHABITATION: the root sense, long-term living together with no claim about benefit.","cn":"共同居住：根义，长期共同生活，不宣称获益。"},{"senses":"S2 · S3 · S4","en":"THE SPECTRUM: mutualism, commensalism and parasitism are three points on the same axis.","cn":"谱系：互利、偏利与寄生是同一轴上的三个点。"},{"senses":"S5","en":"SOCIETY: groups and institutions can live together and supply each other's lacks.","cn":"社会：群体与机构可以共同生活，彼此补足所缺。"},{"senses":"S6 · S7","en":"INDUSTRY AND ECOSYSTEM: waste becomes input, and partnership keeps a system stable.","cn":"产业与生态系统：废物变成投入，伙伴关系维持系统稳定。"},{"senses":"S8","en":"MUTUAL SHAPING: technology and society change each other, the furthest extension of cohabitation.","cn":"相互塑造：技术与社会互相改变，这是共同居住最远的引申。"}]},"affixes":{"intro":{"en":"Symbiosis is a Greek compound borrowed whole: a prefix of union, a root of life, and a Greek noun ending.","cn":"symbiosis 是整体借入的希腊复合词：表示「结合」的前缀、表示「生命」的词根，以及希腊名词词尾。"},"latinIntro":{"en":"The word reached English through scientific Latin, but its parts are Greek. Latin has no native etymon for it; the Latin-looking ending -osis is a Greek transliteration.","cn":"这个词经科学拉丁语进入英语，但其成分是希腊语；拉丁语没有它的本族词源，看似拉丁的词尾 -osis 其实是希腊语的转写。"},"items":[{"word":"symbiosis","structure":"Greek syn- (together) + bios (life) + -osis (state)","meaning":"the state of living together","meaningCN":"共同生活的状态","example":"Symbiosis began in the shallow sea.","exampleCN":"共生始于浅海。"},{"word":"symbioses","structure":"Greek plural of symbiosis","meaning":"several symbiotic relationships","meaningCN":"多种共生关系","example":"Symbioses appear in many animal groups.","exampleCN":"共生出现在许多动物类群中。"},{"word":"symbiotic","structure":"symbiosis + -ic (relation)","meaning":"of symbiosis","meaningCN":"共生的","example":"A symbiotic alga lives inside the coral.","exampleCN":"一种共生藻生活在珊瑚体内。"},{"word":"symbiotically","structure":"symbiotic + -ally (adverb)","meaning":"in a symbiotic way","meaningCN":"以共生方式地","example":"The two species live symbiotically.","exampleCN":"这两个物种以共生方式生活。"},{"word":"symbiont","structure":"Greek symbiont- (one living with)","meaning":"a member of a symbiosis","meaningCN":"共生关系中的一方","example":"The smaller symbiont supplies nitrogen.","exampleCN":"较小的共生体提供氮。"},{"word":"endosymbiosis","structure":"endo- (within) + symbiosis","meaning":"one partner living inside the cells of the other","meaningCN":"一方生活在另一方细胞内部","example":"Endosymbiosis produced the first mitochondria.","exampleCN":"内共生产生了最早的线粒体。"},{"word":"ectosymbiosis","structure":"ecto- (outside) + symbiosis","meaning":"one partner living on the surface of the other","meaningCN":"一方生活在另一方体表","example":"Ectosymbiosis is common on coral reefs.","exampleCN":"体表共生在珊瑚礁上很常见。"},{"word":"mutualism","structure":"mutual + -ism","meaning":"the mutually beneficial type","meaningCN":"互利类型","example":"Mutualism is the best-known symbiosis.","exampleCN":"互利共生是最广为人知的共生。"},{"word":"parasitism","structure":"parasite + -ism","meaning":"the one-sided type","meaningCN":"单向获益的类型","example":"Parasitism sits at the other end.","exampleCN":"寄生处在另一端。"}],"latinEntries":[{"word":"symbiosis","structure":"symbiosis, -is (f., scientific Latin from Greek)","meaning":"a living together","meaningCN":"共同生活"},{"word":"symbioticus","structure":"symbioticus, -a, -um (adj., Modern Latin from Greek)","meaning":"of a living together","meaningCN":"共同生活的"}]}},{"word":"symbiotic","ipa_uk":"/ˌsɪmbaɪˈɒtɪk/","ipa_us":"/ˌsɪmbaɪˈɑːtɪk/","definition_zh":"共生的；与共生有关的；相互依赖的","definition_en":"of, relating to, or depending on a symbiosis","core_image":"树根与真菌菌丝交织成网，两端各有箭头交换水分与磷","scene":"The symbiotic partnership lets the tree obtain phosphorus from the fungus.","sceneCN":"这里 symbiotic 是「共生的」（第 1 个义项：与共生关系有关）；句意：这种共生伙伴关系让树木从真菌那里获得磷。图中可辨识物件：树根、菌丝网、双向交换的箭头。","pos":[{"tag":"adj.","zh":"共生的；与共生有关的；相互依赖的（由名词 symbiosis 加 -ic 构成）"}],"collocations":[{"phrase":"symbiotic relationship","zh":"共生关系"},{"phrase":"symbiotic bacteria","zh":"共生细菌"},{"phrase":"symbiotic association","zh":"共生联合"},{"phrase":"symbiotic partnership","zh":"共生伙伴关系"},{"phrase":"symbiotic dependence","zh":"共生性依赖"},{"phrase":"symbiotic network","zh":"共生网络"}],"forms":[{"label":"原级（形容词）","form":"symbiotic（共生的）"},{"label":"副词形式","form":"symbiotically（以共生方式地）"},{"label":"名词形式","form":"symbiosis（共生；共生关系）"},{"label":"参与方名词","form":"symbiont（共生体；共生双方之一）"},{"label":"名词复数","form":"symbioses（共生关系，复数）"}],"derivatives":[{"word":"symbiosis","pos":"n.","zh":"共生；共生关系"},{"word":"symbioses","pos":"n.","zh":"共生关系（复数）"},{"word":"symbiont","pos":"n.","zh":"共生体；共生双方之一"},{"word":"symbiotically","pos":"adv.","zh":"以共生方式地"},{"word":"endosymbiotic","pos":"adj.","zh":"内共生的"},{"word":"nonsymbiotic","pos":"adj.","zh":"非共生的"},{"word":"mutualistic","pos":"adj.","zh":"互利共生的（共生中互利类型的形容词）"}],"senses":[{"no":"01","title":"Of Symbiosis","titleCN":"共生的：与共生关系相关","definition":"relating to a symbiosis or to organisms that live in one","definitionCN":"与共生或生活在共生中的生物有关的","example":"The symbiotic state can persist for millions of years.","exampleCN":"这种共生状态可以持续数百万年。","why":"The suffix -ic turns the noun symbiosis into an adjective of relation. The bare sense simply marks the relationship, leaving open whether it is mutual, one-sided or harmful.","whyCN":"后缀 -ic 把名词 symbiosis 变成关系形容词；最朴素的义项只标记这种关系，不说明它是互利、偏利还是有害。"},{"no":"02","title":"A Symbiotic Relationship","titleCN":"共生关系：双方长期结合","definition":"describing a long-term relationship between two different organisms","definitionCN":"描述两种不同生物之间的长期关系","example":"The symbiotic relationship began when the ants started farming the fungus.","exampleCN":"当蚂蚁开始种植这种真菌时，这段共生关系就开始了。","why":"Relationship is the neutral word for the link, and symbiotic specifies its type. The phrase is the standard label before a researcher decides whether to call it mutualism or parasitism.","whyCN":"relationship 是对这种联系的中性词，symbiotic 指明其类型；在研究这一定性为互利还是寄生之前，该短语是标准的标签。"},{"no":"03","title":"Symbiotic Bacteria","titleCN":"共生细菌：与宿主共同生活的细菌","definition":"bacteria that live in a long-term association with a host","definitionCN":"与宿主长期共同生活的细菌","example":"Symbiotic bacteria in the gut help break down plant fibre.","exampleCN":"肠道中的共生细菌帮助分解植物纤维。","why":"Microbes are the most common symbionts. Adding symbiotic to bacteria distinguishes residents from passing contaminants, and the phrase usually implies benefit to the host.","whyCN":"微生物是最常见的共生体；在 bacteria 前加 symbiotic，可把常驻者与过路污染菌区分开，该短语通常暗示对宿主有益。"},{"no":"04","title":"Symbiotic Dependence","titleCN":"共生性依赖：离了对方就难以维持","definition":"a state in which two parties depend on each other for survival or function","definitionCN":"两方在生存或功能上互相依赖的状态","example":"Their symbiotic dependence made the split very costly.","exampleCN":"他们的共生性依赖使拆分代价极高。","why":"Dependence brings out the cost of the union. The adjective can describe people or institutions, and it stresses that neither side can function well alone.","whyCN":"dependence 凸显这种结合的成本；该形容词可以描述人或机构，强调任何一方都难以独自运转。"},{"no":"05","title":"Mutual Benefit","titleCN":"互利共生的：双方都得到好处","definition":"describing a relationship in which both partners gain","definitionCN":"描述双方都获益的关系","example":"The fig and the wasp have a strictly symbiotic exchange.","exampleCN":"无花果与榕小蜂之间有一种严格的互利共生交换。","why":"In everyday use symbiotic often implies mutual gain, even though the noun is broader. Context, especially in popular science, supplies the positive colouring.","whyCN":"在日常用法中，symbiotic 常暗示互利，尽管其名词形式范围更宽；语境，尤其是科普文字，提供了这种正面色彩。"},{"no":"06","title":"Root Symbiosis","titleCN":"根际共生：植物与真菌的结合","definition":"describing the association between plant roots and fungi or bacteria","definitionCN":"描述植物根与真菌或细菌之间的联合","example":"Symbiotic fungi extend the reach of the tree's roots.","exampleCN":"共生真菌扩展了树木根系的触及范围。","why":"In botany the adjective most often marks mycorrhiza or nitrogen-fixing nodules. The plant supplies sugar, the microbe supplies minerals, and the exchange is the point.","whyCN":"在植物学中，该形容词最常标记菌根或固氮根瘤；植物提供糖，微生物提供矿质，交换正是重点。"},{"no":"07","title":"An Industrial Network","titleCN":"产业共生的：企业间的资源循环","definition":"describing a network of firms that exchange waste, heat or by-products","definitionCN":"描述企业交换废物、热能或副产品的网络","example":"The symbiotic network saved the park a million litres of water.","exampleCN":"这个产业共生网络为园区节省了一百万升水。","why":"The ecological adjective is borrowed for industry, where one firm's output becomes another's input. It is a metaphor, but a deliberately engineered one.","whyCN":"生态学形容词被借用到工业：一家企业的产出成为另一家的投入；这是隐喻，但是被有意设计出来的隐喻。"},{"no":"08","title":"A Bond Between People","titleCN":"人际与机构间的共生纽带","definition":"describing a close, mutually sustaining bond between people or institutions","definitionCN":"描述人或机构之间密切、相互维持的纽带","example":"The two universities built a symbiotic bond over decades.","exampleCN":"两所大学在数十年间建立起一种共生纽带。","why":"This is the social extension recorded from 1951. The adjective keeps the image of two lives supporting each other, while the biology drops away.","whyCN":"这是 1951 年记录的社会引申；该形容词保留两个生命相互支撑的画面，而生物学内容退去。"}],"etymology":{"intro":{"en":"Symbiotic is the adjective of symbiosis, recorded from 1882, only six years after the noun. It began in biology and passed into social and industrial language in the twentieth century.","cn":"symbiotic 是 symbiosis 的形容词，记录于 1882 年，仅比名词晚六年；它始于生物学，二十世纪进入社会与工业语言。"},"items":[{"era":"GREEK SYMBIOSIS","en":"Greek symbiosis meant 'a living together', from syn- 'together' and bios 'life'. The noun entered English as a biological term in 1876.","cn":"希腊 symbiosis 意为「共同生活」，由 syn-「一起」与 bios「生命」构成；该名词于 1876 年作为生物学词进入英语。"},{"era":"THE -IC ENDING","en":"Greek -ikos and Latin -icus formed adjectives of relation. Added to the stem of symbiosis, they produced symbiotic in English in 1882.","cn":"希腊 -ikos 与拉丁 -icus 构成关系形容词；加在 symbiosis 的词干上，于 1882 年在英语中产生 symbiotic。"},{"era":"FIRST USE IN BIOLOGY","en":"Symbiotic is recorded from 1882 'in biology'. It described the relation between organisms before it described anything else.","cn":"symbiotic 记录于 1882 年，「用于生物学」；它先描述生物之间的关系，之后才用于其他事物。"},{"era":"THE SOCIAL EXTENSION, 1951","en":"Use of symbiotic for human activities is recorded from 1951. The adjective then began to describe partnerships between people, institutions and technologies.","cn":"symbiotic 用于人类活动的记录始于 1951 年；此后该形容词开始描述人、机构与技术之间的伙伴关系。"},{"era":"INDUSTRIAL ECOLOGY","en":"Late twentieth-century industrial ecology fixed phrases such as symbiotic network and symbiotic exchange, applying the biological image to material flows between firms.","cn":"二十世纪后期的产业生态学固定了「共生网络」「共生交换」等短语，把生物学画面应用于企业间的物质流。"},{"era":"THE BENEFIT SHADE","en":"The noun is neutral about benefit, but the adjective often implies mutual gain in popular use. The shade comes from context, not from the suffix, so careful writers add mutualistic when precision matters.","cn":"名词对获益保持中立，而形容词在通俗用法中常暗示互利；这层色彩来自语境而非后缀，因此严谨作者在需要精确时会加 mutualistic。"}]},"similar":{"note":{"en":"The first group separates the adjective from the noun and the participants. The second group holds adjectives for the three points of the symbiosis spectrum and for looser kinds of cooperation.","cn":"第一组区分形容词与名词、参与方；第二组是共生谱系三个点以及更宽泛合作的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"symbiosis","ipa":"/ˌsɪmbaɪˈəʊsɪs/","tag":"noun","definition":"The relationship itself. Symbiotic describes it; symbiosis names it.","definitionCN":"指关系本身；symbiotic 描述它，symbiosis 命名它。"},{"word":"symbiont","ipa":"/sɪmˈbaɪɒnt/","tag":"noun, participant","definition":"One of the organisms in the relationship. It is a member, not the relation or its adjective.","definitionCN":"关系中的一方生物；它是成员，不是关系本身或其形容词。"},{"word":"symbiotically","ipa":"/ˌsɪmbaɪˈɒtɪkli/","tag":"adverb","definition":"The adverb, describing how two organisms live. It modifies a verb rather than a noun.","definitionCN":"副词，描述两个生物如何生活；修饰动词而不是名词。"}]},{"heading":"NEAR-SYNONYMS","entries":[{"word":"mutualistic","ipa":"/ˌmjuːtjuəˈlɪstɪk/","tag":"adjective, both benefit","definition":"Describing a relationship in which both partners benefit. It is more precise than symbiotic when the benefit is known.","definitionCN":"描述双方都获益的关系；当已知双方获益时，它比 symbiotic 更精确。"},{"word":"commensal","ipa":"/kəˈmensəl/","tag":"adjective, one gains, one unaffected","definition":"Describing a relationship in which one partner gains and the other is unaffected. It marks a different point on the spectrum.","definitionCN":"描述一方获益、另一方不受影响的关系；它标记谱系上的另一个点。"},{"word":"parasitic","ipa":"/ˌpærəˈsɪtɪk/","tag":"adjective, one harmed","definition":"Describing a relationship in which one partner gains at the other's expense. It is the negative end of the same spectrum.","definitionCN":"描述一方以另一方为代价获益的关系；它是同一谱系的负端。"},{"word":"interdependent","ipa":"/ˌɪntədɪˈpendənt/","tag":"adjective, mutual reliance","definition":"Relying on each other. It describes the dependence that symbiosis often creates but says nothing about biology or benefit.","definitionCN":"指互相依赖的；它描述共生常造成的依赖，但不涉及生物学或获益。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"symbiosis + -ic: 'of living together', the adjective of the relationship.","cn":"symbiosis + -ic：意为「共同生活的」，是关系的形容词。"},{"en":"The adjective arrived in 1882, six years after the noun, and stayed in biology at first.","cn":"形容词 1882 年出现，比名词晚六年，起初只用于生物学。"},{"en":"The family runs symbiosis, symbioses, symbiotic, symbiotically, symbiont and endosymbiotic.","cn":"同族词包括 symbiosis、symbioses、symbiotic、symbiotically、symbiont、endosymbiotic。"},{"en":"The spectrum: mutualistic is both gain, commensal is one gain, parasitic is one harm.","cn":"谱系：mutualistic 双方获益，commensal 一方获益，parasitic 一方受损。"},{"en":"In popular use symbiotic usually means the good kind, but the noun is broader.","cn":"通俗用法中 symbiotic 通常指好的那一类，但其名词形式范围更宽。"}],"abstract":[{"en":"Picture roots and threads woven into one net, each side feeding the other.","cn":"想象根与丝织成一张网，两边互相供养。"},{"en":"Picture two universities that cannot succeed alone and know it.","cn":"想象两所大学各自无法成功，而且它们知道这一点。"},{"en":"Picture a factory's waste pipe leading straight into another factory's intake.","cn":"想象一家工厂的废料管直通另一家工厂的进料口。"}]},"examples":[{"en":"Symbiotic algae give the coral both colour and food.","cn":"共生藻为珊瑚提供颜色与食物。"},{"en":"The two industries formed a symbiotic exchange of heat and waste.","cn":"这两个行业形成了热能与废料之间的共生交换。"},{"en":"Their symbiotic partnership survived the downturn.","cn":"他们的共生伙伴关系挺过了低迷期。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"symbiosis（共生）+ -ic（……的）→ 共生的 → symbiotic 共生的","word":"symbiotic"},"root":"希腊 syn-「一起」+ bios「生命」→ symbiosis「共同生活」（1876 年成为生物学词）→ 加 -ic → 英语 symbiotic（1882）；1951 年起用于人类活动。","sensesIntro":{"en":"Eight senses begin with the bare relation, then move through partnership, bacteria, dependence, mutual benefit, root association, industry and human bonds.","cn":"八个义项从最朴素的关系开始，随后经过伙伴关系、细菌、依赖、互利、根际联合、产业与人际纽带。"},"semanticMap":{"core":{"en":"CORE IMAGE: roots and fungal threads woven together, arrows running both ways.","cn":"核心意象：根与真菌丝织在一起，箭头朝两个方向流动。"},"chain":["OF THE RELATION","TWO PARTNERS","MICROBES IN A HOST","DEPENDENCE","MUTUAL GAIN","A HUMAN BOND"],"branches":[{"senses":"S1","en":"RELATION: the bare adjective, neutral about benefit.","cn":"关系：最朴素的形容词，对获益保持中立。"},{"senses":"S2 · S3","en":"PARTNERS AND MICROBES: the relationship can be named neutrally, and bacteria are its commonest members.","cn":"伙伴与微生物：这种关系可以被中性命名，而细菌是其最常见的成员。"},{"senses":"S4 · S5","en":"DEPENDENCE AND GAIN: the union can be a burden or a benefit, and the adjective shades accordingly.","cn":"依赖与获益：这种结合可以是负担也可以是益处，形容词的色彩随之变化。"},{"senses":"S6","en":"ROOTS: botany supplies the clearest mutual exchange, sugar for minerals.","cn":"根际：植物学提供了最清楚的互利交换——糖换矿质。"},{"senses":"S7 · S8","en":"EXTENSIONS: industry reuses the image for material flows, and society for human bonds.","cn":"引申：工业把这一画面用于物质流，社会把它用于人际纽带。"}]},"affixes":{"intro":{"en":"Symbiotic is a Greek noun plus a relational ending: together, life, and 'of the kind of'.","cn":"symbiotic 是希腊名词加关系词尾：一起、生命，以及「属于这一类」。"},"latinIntro":{"en":"The parts are Greek, but the word reached English through scientific Latin forms such as symbioticus. Latin itself has no native verb or noun behind it.","cn":"成分是希腊语，但这个词经 symbioticus 等科学拉丁形式进入英语；拉丁语本身没有它的本族动词或名词。"},"items":[{"word":"symbiotic","structure":"symbiosis + -ic (relation)","meaning":"of a living together","meaningCN":"共同生活的","example":"A symbiotic alga lives in the coral.","exampleCN":"一种共生藻生活在珊瑚中。"},{"word":"symbiosis","structure":"Greek syn- + bios + -osis","meaning":"the relationship","meaningCN":"共生关系","example":"Symbiosis can be obligate.","exampleCN":"共生可以是专性的。"},{"word":"symbioses","structure":"Greek plural of symbiosis","meaning":"several such relationships","meaningCN":"多种此类关系","example":"Symbioses shaped early evolution.","exampleCN":"共生塑造了早期演化。"},{"word":"symbiont","structure":"Greek symbiont- (one living with)","meaning":"a partner in the relationship","meaningCN":"关系中的一方","example":"Each symbiont specialises.","exampleCN":"每个共生体都特化。"},{"word":"symbiotically","structure":"symbiotic + -ally","meaning":"in a symbiotic manner","meaningCN":"以共生方式地","example":"The ants and fungus live symbiotically.","exampleCN":"蚂蚁与真菌以共生方式生活。"},{"word":"endosymbiotic","structure":"endo- (within) + symbiotic","meaning":"living inside the partner's cells","meaningCN":"生活在伙伴细胞内部的","example":"Endosymbiotic bacteria became organelles.","exampleCN":"内共生细菌变成了细胞器。"},{"word":"nonsymbiotic","structure":"non- (not) + symbiotic","meaning":"not living in symbiosis","meaningCN":"非共生的","example":"Nonsymbiotic fungi live on dead wood.","exampleCN":"非共生真菌生活在枯木上。"},{"word":"mutualistic","structure":"mutual + -istic","meaning":"of the mutually beneficial type","meaningCN":"互利类型的","example":"A mutualistic pair both gains.","exampleCN":"互利的一对双方都获益。"}],"latinEntries":[{"word":"symbiosis","structure":"symbiosis, -is (f., scientific Latin from Greek)","meaning":"a living together","meaningCN":"共同生活"},{"word":"symbioticus","structure":"symbioticus, -a, -um (adj., Modern Latin from Greek)","meaning":"of a living together","meaningCN":"共同生活的"}]}}]);
